$sql = &amp;quot;select id,username,password from ctfshow_user where username !=&amp;#39;flag&amp;#39; and id = &amp;#39;&amp;quot;.$_GET[&amp;#39;id&amp;#39;].&amp;quot;&amp;#39; limit 1;&amp;quot;;


返回逻辑
//对传入的参数进行了过滤
