&lt;pre&gt;&lt;code class=&#34;mysql&#34;&gt;mysql&amp;gt; SELECT CONCAT(&amp;#39;my&amp;#39;, &amp;#39;s&amp;#39;, &amp;#39;ql&amp;#39;); 
