&lt;img data-src=&#34;\images\article_images\image-20250825165020916.png&#34; alt=&#34;image-20250825165020916&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;# -- coding:UTF-8 --
# Author:dota_st + modified
import requests
