URL = &amp;quot;http://9e4168dd-4d2c-48ca-8c74-fd46660d4f27.challenge.ctf.show/api/&amp;quot;
TARGET_USER = &amp;quot;admin&amp;quot;
MAX_TRY = 300
SUCCESS_FLAG = &amp;quot;\\u767b\\u9646\\u6210\\u529f&amp;quot;  # 登陆成功

# 配置区
