查询语句
  //插入数据
  $sql = &amp;quot;insert into ctfshow_user(username,pass) value(&amp;#39;&amp;#123;$username&amp;#125;&amp;#39;,&amp;#39;&amp;#123;$password&amp;#125;&amp;#39;);&amp;quot;;


返回逻辑
  //过滤空格 or 
